var SITUATIES = [{"n": 1, "t": "Kennismaken", "tt": {"de": "Sich kennenlernen", "nl": "Kennismaken", "en": "Getting to know each other", "fr": "Faire connaissance", "es": "Conocerse"}, "r": [["j", "Hallo, ich heiße Anna.", "Hallo, ik heet Anna.", "Hi, my name is Anna.", "Bonjour, je m'appelle Anna.", "Hola, me llamo Anna."], ["a", "Hallo Anna, ich bin Tom. Schön, dich kennenzulernen.", "Hallo Anna, ik ben Tom. Leuk je te ontmoeten.", "Hi Anna, I'm Tom. Nice to meet you.", "Salut Anna, je suis Tom. Enchanté.", "Hola Anna, soy Tom. Encantado de conocerte."], ["j", "Freut mich auch. Woher kommst du?", "Leuk je ook te ontmoeten. Waar kom je vandaan?", "Nice to meet you too. Where are you from?", "Moi aussi. Tu viens d'où ?", "Igualmente. ¿De dónde eres?"], ["a", "Ich komme aus Utrecht. Und du?", "Ik kom uit Utrecht. En jij?", "I'm from Utrecht. And you?", "Je viens d'Utrecht. Et toi ?", "Vengo de Utrecht. ¿Y tú?"], ["j", "Ich komme aus Groningen.", "Ik kom uit Groningen.", "I'm from Groningen.", "Je viens de Groningue.", "Yo vengo de Groninga."], ["a", "Wohnst du hier schon lange?", "Woon je hier al lang?", "Have you lived here long?", "Tu habites ici depuis longtemps ?", "¿Vives aquí desde hace mucho?"], ["j", "Nein, erst seit drei Monaten.", "Nee, pas drie maanden.", "No, only for three months.", "Non, depuis seulement trois mois.", "No, solo desde hace tres meses."], ["a", "Was machst du hier?", "Wat doe je hier?", "What do you do here?", "Qu'est-ce que tu fais ici ?", "¿A qué te dedicas aquí?"], ["j", "Ich mache eine Ausbildung in der Sozialen Arbeit.", "Ik volg een opleiding in de zorg.", "I'm doing a training in social care.", "Je fais une formation dans le social.", "Estoy haciendo una formación en atención social."], ["a", "Oh, das ist interessant. Wie lange dauert das?", "Oh, dat is interessant. Hoe lang duurt dat?", "Oh, that's interesting. How long does it take?", "Oh, c'est intéressant. Ça dure combien de temps ?", "Qué interesante. ¿Cuánto tiempo dura?"], ["j", "Noch ein Jahr.", "Nog een jaar.", "Another year.", "Encore un an.", "Un año más."], ["a", "Gut gemacht! Und hast du Hobbys?", "Goed bezig! Heb je hobby's?", "Well done! Do you have any hobbies?", "Bien joué ! Tu as des loisirs ?", "¡Muy bien! ¿Tienes aficiones?"], ["j", "Ja, ich mache gern Musik.", "Ja, ik maak graag muziek.", "Yes, I like making music.", "Oui, j'aime faire de la musique.", "Sí, me gusta hacer música."], ["a", "Cool. Welche Musik machst du?", "Cool. Wat voor muziek maak je?", "Cool. What kind of music do you make?", "Cool. Tu fais quel genre de musique ?", "Genial. ¿Qué tipo de música haces?"], ["j", "Ich mache Beats und Songs am Computer.", "Ik maak beats en liedjes op de computer.", "I make beats and songs on my computer.", "Je fais des beats et des chansons sur l'ordinateur.", "Hago beats y canciones en el ordenador."], ["a", "Super! Vielleicht hören wir mal etwas zusammen.", "Super! Misschien luisteren we samen eens iets.", "Great! Maybe we can listen to something together sometime.", "Super ! On pourra peut-être écouter quelque chose ensemble.", "¡Genial! Quizás algún día escuchamos algo juntos."]], "v": {"1": [["Hey Anna, ich bin Tom. Freut mich!", "Hoi Anna, ik ben Tom. Aangenaam.", "Hey Anna, I'm Tom. Pleased to meet you.", "Salut Anna, moi c'est Tom. Ravi de te rencontrer.", "Hola Anna, yo soy Tom. Mucho gusto."]], "2": [["Freut mich auch. Woher kommen Sie?", "Leuk u ook te ontmoeten. Waar komt u vandaan?", "Nice to meet you too. Where are you from?", "Moi aussi. D'où venez-vous ?", "Igualmente. ¿De dónde es usted?"]], "3": [["Ich komme aus Utrecht. Und Sie?", "Ik kom uit Utrecht. En u?", "I'm from Utrecht. And you?", "Je viens d'Utrecht. Et vous ?", "Vengo de Utrecht. ¿Y usted?"]], "5": [["Wohnen Sie hier schon lange?", "Woont u hier al lang?", "Have you lived here long?", "Vous habitez ici depuis longtemps ?", "¿Vive aquí desde hace mucho?"]], "7": [["Was machen Sie hier?", "Wat doet u hier?", "What do you do here?", "Qu'est-ce que vous faites ici ?", "¿A qué se dedica aquí?"]], "9": [["Oh, wie spannend! Wie lange dauert das?", "Oh, wat leuk! Hoe lang duurt dat?", "Oh, how exciting! How long does it take?", "Ah, ça a l'air intéressant. Ça dure combien de temps ?", "¡Qué interesante! ¿Cuánto tiempo dura?"]], "11": [["Gut gemacht! Und haben Sie Hobbys?", "Goed bezig! Heeft u hobby's?", "Well done! Do you have any hobbies?", "Bien joué ! Vous avez des loisirs ?", "¡Muy bien! ¿Tiene aficiones?"]], "13": [["Wow, das klingt cool. Welche Musik machen Sie?", "Wow, dat klinkt goed. Wat voor muziek maakt u?", "Wow, that sounds cool. What kind of music do you make?", "Ah, c'est sympa. Vous faites quel genre de musique ?", "Qué bien. ¿Qué tipo de música hace?"]]}}, {"n": 2, "t": "Begroeten en afscheid nemen", "tt": {"de": "Begrüßen und verabschieden", "nl": "Begroeten en afscheid nemen", "en": "Saying hello and goodbye", "fr": "Dire bonjour et au revoir", "es": "Saludar y despedirse"}, "r": [["j", "Guten Morgen! Wie geht es Ihnen?", "Goedemorgen! Hoe gaat het?", "Good morning! How are you?", "Bonjour ! Comment allez-vous ?", "¡Buenos días! ¿Cómo está usted?"], ["a", "Danke, gut. Und Ihnen?", "Dank u, goed. En met u?", "Thanks, good. And you?", "Merci, bien. Et vous ?", "Bien, gracias. ¿Y usted?"], ["j", "Auch gut, danke.", "Ook goed, dank u.", "Good too, thanks.", "Très bien, merci.", "Muy bien, gracias."], ["a", "Schön, Sie zu sehen.", "Fijn u te zien.", "Good to see you.", "Ravi de vous voir.", "Qué bueno verle."], ["j", "Ihnen auch. Bis später!", "U ook. Tot later!", "You too. See you later!", "Pareillement. À plus tard !", "Igualmente. ¡Hasta luego!"], ["a", "Ja, bis später. Viel Spaß heute!", "Ja, tot later. Veel plezier vandaag!", "Yes, see you later. Have fun today!", "Oui, à plus tard. Bonne journée !", "Sí, hasta luego. ¡Que lo pases bien hoy!"], ["j", "Danke, Ihnen auch. Auf Wiedersehen!", "Dank u, u ook. Tot ziens!", "Thanks, you too. Goodbye!", "Merci, vous aussi. Au revoir !", "Gracias, igualmente. ¡Adiós!"], ["a", "Auf Wiedersehen! Bis bald.", "Tot ziens! Tot snel.", "Goodbye! See you soon.", "Au revoir ! À bientôt.", "¡Adiós! Hasta pronto."], ["j", "Entschuldigung, ich muss gehen.", "Sorry, ik moet gaan.", "Sorry, I have to go.", "Désolé, je dois y aller.", "Perdón, tengo que irme."], ["a", "Kein Problem. Gute Reise!", "Geen probleem. Goede reis!", "No problem. Have a good trip!", "Pas de problème. Bon voyage !", "No hay problema. ¡Buen viaje!"], ["j", "Danke! Auf Wiedersehen.", "Dank u! Tot ziens.", "Thank you! Goodbye.", "Merci ! Au revoir.", "¡Gracias! Hasta la vista."], ["a", "Auf Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Hasta la vista!"], ["j", "Wie spät ist es eigentlich?", "Hoe laat is het eigenlijk?", "What time is it, by the way?", "Quelle heure est-il, au fait ?", "¿Qué hora es, por cierto?"], ["a", "Es ist kurz nach zehn.", "Het is net na tienen.", "It's just after ten.", "Il est dix heures passées.", "Son las diez y pico."], ["j", "Oh, dann muss ich wirklich los.", "O, dan moet ik echt gaan.", "Oh, then I really have to go.", "Oh, alors je dois vraiment partir.", "Vaya, entonces de verdad tengo que irme."], ["a", "Dann bis morgen!", "Dan tot morgen!", "Then see you tomorrow!", "Alors à demain !", "¡Entonces hasta mañana!"], ["j", "Bis morgen! Schlafen Sie gut.", "Tot morgen! Slaapt u lekker.", "See you tomorrow! Sleep well.", "À demain ! Bonne nuit.", "¡Hasta mañana! Que descanse."]], "v": {"0": [["Hallo! Wie geht es dir?", "Hoi! Hoe gaat het met je?", "Hi! How are you?", "Salut ! Ça va ?", "¡Hola! ¿Qué tal?"]], "1": [["Danke, gut. Und dir?", "Dank je, goed. En met jou?", "Thanks, good. And you?", "Merci, bien. Et toi ?", "Bien, gracias. ¿Y tú?"]]}}, {"n": 3, "t": "Station: kaartje kopen en perron vinden", "tt": {"de": "Bahnhof: Fahrkarte kaufen und Gleis finden", "nl": "Station: kaartje kopen en perron vinden", "en": "Station: buying a ticket and finding the platform", "fr": "Gare : acheter un billet et trouver le quai", "es": "Estación: comprar un billete y encontrar el andén"}, "r": [["j", "Entschuldigung, wo kann ich ein Ticket kaufen?", "Excuseer, waar kan ik een kaartje kopen?", "Excuse me, where can I buy a ticket?", "Excusez-moi, où puis-je acheter un billet ?", "Perdone, ¿dónde puedo comprar un billete?"], ["a", "Am Automaten dort drüben oder am Schalter.", "Bij de automaat daar of aan het loket.", "At the machine over there or at the counter.", "Au distributeur là-bas ou au guichet.", "En la máquina de allí o en la taquilla."], ["j", "Ein Ticket nach Amsterdam, bitte.", "Een kaartje naar Amsterdam, alstublieft.", "One ticket to Amsterdam, please.", "Un billet pour Amsterdam, s'il vous plaît.", "Un billete a Ámsterdam, por favor."], ["a", "Einfach oder hin und zurück?", "Enkele reis of retour?", "Single or return?", "Aller simple ou aller-retour ?", "¿Solo ida o ida y vuelta?"], ["j", "Hin und zurück, bitte.", "Retour, alstublieft.", "Return, please.", "Aller-retour, s'il vous plaît.", "Ida y vuelta, por favor."], ["a", "Das macht zwölf Euro fünfzig.", "Dat is twaalf euro vijftig.", "That's twelve euros fifty.", "Ça fait douze euros cinquante.", "Son doce euros con cincuenta."], ["j", "Kann ich mit Karte bezahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, natürlich. Der Automat akzeptiert Karten.", "Ja, natuurlijk. De automaat neemt pinpassen aan.", "Yes, of course. The machine accepts cards.", "Oui, bien sûr. Le distributeur accepte les cartes.", "Sí, claro. La máquina acepta tarjetas."], ["j", "Auf welchem Gleis fährt der Zug?", "Van welk spoor vertrekt de trein?", "Which platform does the train leave from?", "Quel quai pour le train ?", "¿De qué andén sale el tren?"], ["a", "Gleis drei, auf der anderen Seite.", "Spoor drie, aan de andere kant.", "Platform three, on the other side.", "Quai trois, de l'autre côté.", "Andén tres, al otro lado."], ["j", "Muss ich über die Brücke gehen?", "Moet ik over de brug lopen?", "Do I have to go over the bridge?", "Il faut passer par le pont ?", "¿Tengo que cruzar el puente?"], ["a", "Ja, über die Treppe oder den Aufzug.", "Ja, via de trap of de lift.", "Yes, by the stairs or the lift.", "Oui, par les escaliers ou l'ascenseur.", "Sí, por las escaleras o el ascensor."], ["j", "Gibt es hier einen Aufzug?", "Is er hier een lift?", "Is there a lift here?", "Il y a un ascenseur ici ?", "¿Hay un ascensor aquí?"], ["a", "Ja, am Ende des Bahnsteigs.", "Ja, aan het eind van het perron.", "Yes, at the end of the platform.", "Oui, au bout du quai.", "Sí, al final del andén."], ["j", "Danke. Ist der Zug pünktlich?", "Dank u. Rijdt de trein op tijd?", "Thanks. Is the train on time?", "Merci. Le train est à l'heure ?", "Gracias. ¿El tren llega a tiempo?"], ["a", "Ja, er fährt in fünf Minuten.", "Ja, hij vertrekt over vijf minuten.", "Yes, it leaves in five minutes.", "Oui, il part dans cinq minutes.", "Sí, sale en cinco minutos."], ["j", "Super, danke für die Hilfe!", "Super, bedankt voor de hulp!", "Great, thanks for the help!", "Super, merci pour votre aide !", "¡Genial, gracias por la ayuda!"], ["a", "Gern geschehen. Gute Fahrt!", "Graag gedaan. Goede reis!", "You're welcome. Have a good journey!", "Avec plaisir. Bon voyage !", "De nada. ¡Buen viaje!"]], "v": {"1": [["Da drüben, am Automaten.", "Daar, bij de automaat.", "Over there, at the machine.", "Là-bas, au distributeur.", "Allí, en la máquina."]], "3": [["Einfach oder retour?", "Enkel of retour?", "One way or return?", "Aller simple ou retour ?", "¿Ida o ida y vuelta?"]], "5": [["Zwölf Euro fünfzig, bitte.", "Dat zijn twaalf euro vijftig.", "That's twelve fifty.", "Douze euros cinquante.", "Doce con cincuenta."]]}, "p": [["Eine Fahrkarte nach [plaats], bitte.", "Een kaartje naar [plaats], alstublieft.", "A ticket to [plaats], please.", "Un billet pour [plaats], s'il vous plaît.", "Un billete a [plaats], por favor."], ["Wann fährt der Zug nach [plaats]?", "Wanneer vertrekt de trein naar [plaats]?", "When does the train to [plaats] leave?", "Quand part le train pour [plaats] ?", "¿Cuándo sale el tren a [plaats]?"]]}, {"n": 4, "t": "Trein en bus: plaats, instappen en vertraging", "tt": {"de": "Zug und Bus: Platz, Einsteigen und Verspätung", "nl": "Trein en bus: plaats, instappen en vertraging", "en": "Train and bus: seats, getting on and delays", "fr": "Train et bus : place, montée et retard", "es": "Tren y autobús: asiento, subir y retraso"}, "r": [["j", "Ist hier noch frei?", "Is deze plaats nog vrij?", "Is this seat free?", "Cette place est libre ?", "¿Está libre este asiento?"], ["a", "Ja, bitte setzen Sie sich.", "Ja, gaat u zitten.", "Yes, please sit down.", "Oui, asseyez-vous.", "Sí, siéntese, por favor."], ["j", "Danke. Fährt dieser Zug nach Den Haag?", "Dank u. Gaat deze trein naar Den Haag?", "Thanks. Does this train go to The Hague?", "Merci. Ce train va à La Haye ?", "Gracias. ¿Este tren va a La Haya?"], ["a", "Nein, der nächste Zug fährt in zehn Minuten.", "Nee, de volgende trein gaat over tien minuten.", "No, the next train leaves in ten minutes.", "Non, le prochain train part dans dix minutes.", "No, el próximo tren sale en diez minutos."], ["j", "Okay. Wo muss ich umsteigen?", "Oké. Waar moet ik overstappen?", "Okay. Where do I change?", "D'accord. Où dois-je changer ?", "Vale. ¿Dónde tengo que cambiar?"], ["a", "In Utrecht Centraal.", "In Utrecht Centraal.", "At Utrecht Centraal.", "À Utrecht Centraal.", "En Utrecht Centraal."], ["j", "Ist der Zug heute verspätet?", "Heeft de trein vertraging vandaag?", "Is the train delayed today?", "Le train a du retard aujourd'hui ?", "¿El tren va con retraso hoy?"], ["a", "Ja, etwa zwanzig Minuten.", "Ja, ongeveer twintig minuten.", "Yes, about twenty minutes.", "Oui, environ vingt minutes.", "Sí, unos veinte minutos."], ["j", "Kann ich mit diesem Ticket auch den Bus nehmen?", "Kan ik met dit kaartje ook de bus nemen?", "Can I also take the bus with this ticket?", "Puis-je prendre le bus avec ce billet ?", "¿Puedo tomar el autobús con este billete?"], ["a", "Ja, im Zug und im Bus gilt dasselbe Ticket.", "Ja, dit kaartje geldt in de trein en in de bus.", "Yes, the same ticket works on the train and the bus.", "Oui, le même billet vaut pour le train et le bus.", "Sí, el mismo billete vale para el tren y el autobús."], ["j", "Halte ich hier für das Zentrum?", "Stop ik hier voor het centrum?", "Do I get off here for the centre?", "Je descends ici pour le centre ?", "¿Me bajo aquí para el centro?"], ["a", "Nein, zwei Haltestellen weiter.", "Nee, twee haltes verder.", "No, two stops further.", "Non, deux arrêts plus loin.", "No, dos paradas más allá."], ["j", "Sagen Sie mir bitte Bescheid?", "Kunt u mij waarschuwen als we er zijn?", "Could you let me know when we get there?", "Vous pouvez me prévenir ?", "¿Me avisa, por favor?"], ["a", "Natürlich, ich sage Ihnen Bescheid.", "Natuurlijk, ik laat het u weten.", "Of course, I'll tell you.", "Bien sûr, je vous préviens.", "Claro, le aviso."], ["j", "Entschuldigung, ist das der Bus nach Zentrum?", "Sorry, is dit de bus naar het centrum?", "Sorry, is this the bus to the centre?", "Pardon, c'est le bus pour le centre ?", "Perdone, ¿este autobús va al centro?"], ["a", "Ja, steigen Sie hinten ein.", "Ja, stap achteraan in.", "Yes, get on at the back.", "Oui, montez par l'arrière.", "Sí, suba por atrás."], ["j", "Danke! Ich steige an der nächsten Haltestelle aus.", "Dank u! Ik stap uit bij de volgende halte.", "Thanks! I'll get off at the next stop.", "Merci ! Je descends au prochain arrêt.", "¡Gracias! Me bajo en la próxima parada."]], "v": {"1": [["Ja, natürlich. Nimm Platz.", "Ja, neem gerust plaats.", "Sure, take a seat.", "Bien sûr, prends place.", "Claro, siéntate."]], "15": [["Ja, steig hinten ein.", "Ja, stap achteraan in.", "Yes, get on at the back.", "Oui, monte par l'arrière.", "Sí, sube por atrás."]]}, "p": [["Fährt dieser Zug nach [plaats]?", "Gaat deze trein naar [plaats]?", "Does this train go to [plaats]?", "Ce train va-t-il à [plaats] ?", "¿Este tren va a [plaats]?"], ["Ich möchte um [tijd] aussteigen.", "Ik wil om [tijd] uitstappen.", "I'd like to get off at [tijd].", "Je voudrais descendre à [tijd].", "Quiero bajarme a las [tijd]."]]}, {"n": 5, "t": "De weg vragen", "tt": {"de": "Nach dem Weg fragen", "nl": "De weg vragen", "en": "Asking the way", "fr": "Demander son chemin", "es": "Preguntar el camino"}, "r": [["j", "Entschuldigung, wo ist der Bahnhof?", "Excuseer, waar is het station?", "Excuse me, where is the train station?", "Excusez-moi, où est la gare ?", "Perdone, ¿dónde está la estación?"], ["a", "Gehen Sie geradeaus und dann links.", "Gaat u maar rechtdoor en dan linksaf.", "Go straight and then turn left.", "Allez tout droit, puis tournez à gauche.", "Siga recto y luego gire a la izquierda."], ["j", "Wie weit ist das zu Fuß?", "Hoe ver is het lopend?", "How far is it on foot?", "C'est loin à pied ?", "¿A qué distancia está a pie?"], ["a", "Etwa zehn Minuten.", "Ongeveer tien minuten.", "About ten minutes.", "Environ dix minutes.", "Unos diez minutos."], ["j", "Muss ich über eine Ampel?", "Moet ik bij een stoplicht oversteken?", "Do I have to cross at a traffic light?", "Il faut traverser à un feu ?", "¿Tengo que cruzar en un semáforo?"], ["a", "Ja, an der zweiten Ampel rechts.", "Ja, bij het tweede stoplicht rechtsaf.", "Yes, turn right at the second traffic light.", "Oui, au deuxième feu, à droite.", "Sí, en el segundo semáforo gire a la derecha."], ["j", "Ist das die Hauptstraße?", "Is dit de hoofdstraat?", "Is this the main street?", "C'est la rue principale ?", "¿Es esta la calle principal?"], ["a", "Nein, das ist eine kleine Seitenstraße.", "Nee, dit is een zijstraatje.", "No, it's a small side street.", "Non, c'est une petite rue latérale.", "No, es una calle lateral pequeña."], ["j", "Kann ich das auf der Karte sehen?", "Kan ik dat even op de kaart zien?", "Can I see that on the map?", "Je peux voir ça sur la carte ?", "¿Puedo verlo en el mapa?"], ["a", "Natürlich. Hier, das ist die Straße.", "Natuurlijk. Hier, dit is de straat.", "Of course. Here, this is the street.", "Bien sûr. Voilà, c'est la rue.", "Claro. Aquí está la calle."], ["j", "Ach so, jetzt verstehe ich.", "Ah, nu snap ik het.", "Oh, now I understand.", "Ah, je comprends maintenant.", "Ah, ahora lo entiendo."], ["a", "Gut. Haben Sie noch Fragen?", "Goed. Heeft u nog vragen?", "Good. Do you have more questions?", "Bien. Vous avez encore des questions ?", "Bien. ¿Tiene más preguntas?"], ["j", "Nein, danke. Gibt es hier in der Nähe eine Apotheke?", "Nee, dank u. Is er hier in de buurt een apotheek?", "No, thanks. Is there a pharmacy nearby?", "Non, merci. Il y a une pharmacie près d'ici ?", "No, gracias. ¿Hay una farmacia cerca?"], ["a", "Ja, gleich um die Ecke.", "Ja, meteen om de hoek.", "Yes, just around the corner.", "Oui, juste au coin de la rue.", "Sí, a la vuelta de la esquina."], ["j", "Perfekt. Vielen Dank für Ihre Hilfe!", "Perfect. Dank u wel voor uw hulp!", "Perfect. Thank you for your help!", "Parfait. Merci pour votre aide !", "¡Perfecto! ¡Gracias por su ayuda!"], ["a", "Gern geschehen. Schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]], "v": {"1": [["Ganz einfach: geradeaus, dann links.", "Het is simpel: rechtdoor en dan linksaf.", "It's easy: straight on, then left.", "C'est simple : tout droit, puis à gauche.", "Es fácil: recto y luego a la izquierda."]], "3": [["So zehn Minuten, schätze ich.", "Een minuut of tien, schat ik.", "Ten minutes or so, I'd say.", "Une dizaine de minutes, je dirais.", "Diez minutos más o menos."]], "5": [["Ja, an der zweiten Ampel dann rechts.", "Ja, bij het tweede stoplicht dan rechts.", "Yes, at the second light, then right.", "Oui, au deuxième feu, puis à droite.", "Sí, en el segundo semáforo, luego a la derecha."]], "11": [["Gut. Hast du noch Fragen?", "Goed. Heb je nog vragen?", "Good. Do you have more questions?", "Bien. Tu as encore des questions ?", "Bien. ¿Tienes más preguntas?"]]}, "p": [["Wie komme ich nach [plaats]?", "Hoe kom ik naar [plaats]?", "How do I get to [plaats]?", "Comment aller à [plaats] ?", "¿Cómo llego a [plaats]?"], ["Wie weit ist es nach [plaats]?", "Hoe ver is het naar [plaats]?", "How far is it to [plaats]?", "C'est loin pour aller à [plaats] ?", "¿A qué distancia está [plaats]?"]]}, {"n": 6, "t": "Taxi: rit regelen en betalen", "tt": {"de": "Taxi: Fahrt vereinbaren und bezahlen", "nl": "Taxi: rit regelen en betalen", "en": "Taxi: arranging the ride and paying", "fr": "Taxi : organiser la course et payer", "es": "Taxi: pedir el viaje y pagar"}, "r": [["j", "Ein Taxi, bitte.", "Een taxi, alstublieft.", "A taxi, please.", "Un taxi, s'il vous plaît.", "Un taxi, por favor."], ["a", "Wohin möchten Sie fahren?", "Waar wilt u naartoe?", "Where would you like to go?", "Où voulez-vous aller ?", "¿A dónde quiere ir?"], ["j", "Zum Hauptbahnhof, bitte.", "Naar het centraal station, alstublieft.", "To the central station, please.", "À la gare centrale, s'il vous plaît.", "A la estación central, por favor."], ["a", "Steigen Sie ein. Das dauert etwa zehn Minuten.", "Stap maar in. Het duurt ongeveer tien minuten.", "Get in. It takes about ten minutes.", "Montez. Ça prend environ dix minutes.", "Suba. Tarda unos diez minutos."], ["j", "Können Sie bitte langsamer fahren?", "Kunt u iets langzamer rijden?", "Could you drive a bit slower, please?", "Vous pouvez rouler un peu moins vite ?", "¿Puede conducir un poco más despacio, por favor?"], ["a", "Natürlich. Ist es so in Ordnung?", "Natuurlijk. Is dit goed?", "Of course. Is this okay?", "Bien sûr. Ça vous va ?", "Claro. ¿Así está bien?"], ["j", "Ja, danke. Halten Sie bitte hier an!", "Ja, dank u. Stop hier alstublieft!", "Yes, thanks. Please stop here!", "Oui, merci. Arrêtez-vous ici, s'il vous plaît !", "Sí, gracias. ¡Pare aquí, por favor!"], ["a", "Das macht sechzehn Euro.", "Dat is zestien euro.", "That's sixteen euros.", "Ça fait seize euros.", "Son dieciséis euros."], ["j", "Kann ich mit Karte zahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, halten Sie das Gerät bitte hier.", "Ja, houd uw pas hier even vast.", "Yes, please hold the card here.", "Oui, approchez la carte ici, s'il vous plaît.", "Sí, acerque la tarjeta aquí, por favor."], ["j", "Hier ist die Quittung. Ich brauche eine Quittung.", "Hier is het bonnetje. Kan ik een bon krijgen?", "Here you go. I'd like a receipt.", "Voilà. Je voudrais un reçu, s'il vous plaît.", "Aquí tiene. Necesito un recibo."], ["a", "Hier bitte. Schönen Tag noch!", "Alstublieft. Fijne dag nog!", "Here you are. Have a nice day!", "Voilà. Bonne journée !", "Aquí tiene. ¡Que tenga buen día!"], ["j", "Danke, Ihnen auch!", "Dank u wel, u ook!", "Thanks, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"], ["a", "Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Hasta luego!"], ["j", "Entschuldigung, ich habe meine Tasche im Taxi vergessen.", "Sorry, ik ben mijn tas vergeten in de taxi.", "Sorry, I left my bag in the taxi.", "Excusez-moi, j'ai oublié mon sac dans le taxi.", "Perdone, me he dejado la bolsa en el taxi."], ["a", "Oh, ich schaue nach. Warten Sie kurz.", "Oh, ik kijk even. Wacht even.", "Oh, let me check. Wait a moment.", "Oh, je regarde. Attendez un instant.", "Ah, miro. Espere un momento."], ["j", "Ist die Tasche schwarz mit einem Reißverschluss?", "Is de tas zwart met een ritssluiting?", "Is the bag black with a zip?", "Le sac est noir avec une fermeture éclair ?", "¿La bolsa es negra con cremallera?"], ["a", "Ja, hier ist sie. Gut, dass Sie sie nicht verloren haben.", "Ja, hier is hij. Gelukkig is hij niet kwijt.", "Yes, here it is. Good that you didn't lose it.", "Oui, la voilà. Heureusement, vous ne l'avez pas perdu.", "Sí, aquí está. Menos mal que no la perdió."], ["j", "Vielen Dank! Sie haben mir sehr geholfen.", "Heel erg bedankt! U hebt me enorm geholpen.", "Thank you so much! You've been very helpful.", "Merci beaucoup ! Vous m'avez beaucoup aidé.", "¡Muchas gracias! Me ha ayudado mucho."]], "v": {"1": [["Wohin willst du fahren?", "Waar wil je naartoe?", "Where do you want to go?", "Où veux-tu aller ?", "¿A dónde quieres ir?"]], "3": [["Steig ein. Das dauert etwa zehn Minuten.", "Stap maar in. Het duurt ongeveer tien minuten.", "Hop in. It takes about ten minutes.", "Monte. Ça prend environ dix minutes.", "Sube. Tarda unos diez minutos."]], "4": [["Kannst du bitte langsamer fahren?", "Kun je iets langzamer rijden?", "Could you drive a bit slower, please?", "Tu peux rouler un peu moins vite ?", "¿Puedes conducir un poco más despacio, por favor?"]], "5": [["Klar. Passt es so?", "Natuurlijk. Zo goed?", "Sure. Is this okay?", "Bien sûr. Ça te va ?", "Claro. ¿Así te vale?"]], "6": [["Ja, danke. Halt bitte hier an!", "Ja, dank je. Stop hier even!", "Yes, thanks. Please stop here!", "Oui, merci. Arrête-toi ici, s'il te plaît !", "Sí, gracias. ¡Para aquí, por favor!"]], "7": [["Das wird sechzehn Euro.", "Dat wordt zestien euro.", "That'll be sixteen euros.", "Ça fera seize euros.", "Serán dieciséis euros."]], "9": [["Ja, halt das Gerät mal hier.", "Ja, houd je pas hier even vast.", "Yes, hold the card here.", "Oui, approche la carte ici.", "Sí, acerca la tarjeta aquí."]], "11": [["Hier, bitte. Schönen Tag noch!", "Alsjeblieft. Fijne dag nog!", "Here you go. Have a nice day!", "Voilà. Bonne journée !", "Aquí tienes. ¡Que tengas buen día!"]], "12": [["Danke, dir auch!", "Dank je, jij ook!", "Thanks, you too!", "Merci, toi aussi !", "¡Gracias, igualmente!"]], "13": [["Tschüss!", "Doei!", "Bye!", "Salut !", "¡Adiós!"]], "15": [["Oh, ich schaue mal. Warte kurz.", "Oh, ik kijk even. Wacht even.", "Oh, let me check. Wait a sec.", "Oh, je regarde. Attends un instant.", "Ah, miro. Espera un momento."]], "17": [["Ja, hier ist sie. Gut, dass du sie nicht verloren hast.", "Ja, hier is hij. Gelukkig ben je hem niet kwijt.", "Yes, here it is. Good that you didn't lose it.", "Oui, la voilà. Heureusement, tu ne l'as pas perdue.", "Sí, aquí está. Menos mal que no la perdiste."]], "18": [["Vielen Dank! Du hast mir sehr geholfen.", "Heel erg bedankt! Je hebt me enorm geholpen.", "Thank you so much! You've been very helpful.", "Merci beaucoup ! Tu m'as beaucoup aidé.", "¡Muchas gracias! Me has ayudado mucho."]]}, "p": [["Nach [plaats], bitte.", "Naar [plaats], alstublieft.", "To [plaats], please.", "À [plaats], s'il vous plaît.", "A [plaats], por favor."]]}, {"n": 7, "t": "Café: iets bestellen", "tt": {"de": "Café: etwas bestellen", "nl": "Café: iets bestellen", "en": "Café: ordering something", "fr": "Café : commander quelque chose", "es": "Cafetería: pedir algo"}, "r": [["j", "Guten Tag, was kann ich bestellen?", "Hallo, wat kan ik bestellen?", "Hi, what can I order?", "Bonjour, qu'est-ce que je peux commander ?", "Hola, ¿qué puedo pedir?"], ["a", "Was möchten Sie trinken?", "Wat wilt u drinken?", "What would you like to drink?", "Qu'est-ce que vous voulez boire ?", "¿Qué le gustaría beber?"], ["j", "Einen Kaffee, bitte. Mit Milch.", "Een koffie, alstublieft. Met melk.", "A coffee, please. With milk.", "Un café, s'il vous plaît. Avec du lait.", "Un café, por favor. Con leche."], ["a", "Groß oder klein?", "Groot of klein?", "Large or small?", "Grand ou petit ?", "¿Grande o pequeño?"], ["j", "Klein, bitte.", "Klein, alstublieft.", "Small, please.", "Petit, s'il vous plaît.", "Pequeño, por favor."], ["a", "Möchten Sie noch etwas essen?", "Wilt u nog iets eten?", "Would you like anything to eat?", "Vous voulez manger quelque chose ?", "¿Quiere algo de comer?"], ["j", "Haben Sie Kuchen?", "Hebben jullie taart?", "Do you have cake?", "Vous avez des gâteaux ?", "¿Tienen tarta?"], ["a", "Ja, Apfelkuchen und Käsekuchen.", "Ja, appeltaart en cheesecake.", "Yes, apple cake and cheesecake.", "Oui, tarte aux pommes et cheesecake.", "Sí, tarta de manzana y tarta de queso."], ["j", "Ein Stück Apfelkuchen, bitte.", "Een stuk appeltaart, alstublieft.", "A slice of apple cake, please.", "Une part de tarte aux pommes, s'il vous plaît.", "Un trozo de tarta de manzana, por favor."], ["a", "Hier bitte. Möchten Sie hier essen oder mitnehmen?", "Alstublieft. Eet u hier of neemt u het mee?", "Here you are. Eat here or take away?", "Voilà. Vous mangez sur place ou à emporter ?", "Aquí tiene. ¿Lo come aquí o para llevar?"], ["j", "Hier, bitte.", "Hier, alstublieft.", "Here, please.", "Ici, s'il vous plaît.", "Aquí, por favor."], ["a", "Gern. Das macht sieben Euro achtzig.", "Graag. Dat is zeven euro tachtig.", "Sure. That's seven euros eighty.", "Bien sûr. Ça fait sept euros quatre-vingts.", "Claro. Son siete euros con ochenta."], ["j", "Kann ich mit Karte bezahlen?", "Kan ik met pin betalen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, natürlich.", "Ja, natuurlijk.", "Yes, of course.", "Oui, bien sûr.", "Sí, claro."], ["j", "Gibt es hier WLAN? Wie ist das Passwort?", "Is er ook wifi hier? Wat is het wachtwoord?", "Is there wifi here? What's the password?", "Il y a le wifi ici ? Quel est le mot de passe ?", "¿Hay wifi aquí? ¿Cuál es la contraseña?"], ["a", "Ja, das Passwort steht auf dem Schild.", "Ja, het wachtwoord staat op het bordje.", "Yes, the password is on the sign.", "Oui, le mot de passe est sur la pancarte.", "Sí, la contraseña está en el cartel."], ["j", "Danke! Der Kuchen ist sehr lecker.", "Dank u! De taart is erg lekker.", "Thanks! The cake is delicious.", "Merci ! Le gâteau est délicieux.", "¡Gracias! La tarta está deliciosa."], ["a", "Das freut mich. Einen schönen Tag!", "Fijn dat het smaakt. Fijne dag!", "I'm glad you like it. Have a nice day!", "Ça me fait plaisir. Bonne journée !", "Me alegro. ¡Que tenga buen día!"]], "v": {"1": [["Was willst du trinken?", "Wat wil je drinken?", "What do you want to drink?", "Tu veux boire quoi ?", "¿Qué quieres beber?"]], "3": [["Große oder kleine?", "Grote of kleine?", "A large or a small one?", "Une grande ou une petite ?", "¿Una grande o una pequeña?"]], "5": [["Möchtest du noch was essen?", "Wil je nog iets eten?", "Would you like anything to eat?", "Tu veux manger quelque chose ?", "¿Quieres algo de comer?"]], "7": [["Ja, wir haben Apfelkuchen und Käsekuchen.", "Ja, we hebben appeltaart en cheesecake.", "Yes, we have apple cake and cheesecake.", "Oui, on a de la tarte aux pommes et du cheesecake.", "Sí, tenemos tarta de manzana y de queso."]], "9": [["Hier, bitte. Isst du hier oder nimmst du es mit?", "Alsjeblieft. Eet je hier of neem je het mee?", "Here you go. Eat in or take away?", "Voilà. Tu manges ici ou tu l'emportes ?", "Aquí tienes. ¿Comes aquí o te lo llevas?"]], "11": [["Gern. Das sind sieben Euro achtzig.", "Graag. Dat zijn zeven euro tachtig.", "Sure. That's seven eighty.", "Bien sûr. Ça fait sept euros quatre-vingts.", "Claro. Son siete ochenta."]], "13": [["Ja, klar.", "Ja, zeker.", "Yes, sure.", "Oui, bien sûr.", "Sí, por supuesto."]], "15": [["Ja, das Passwort steht auf dem Zettel.", "Ja, het wachtwoord staat op het briefje.", "Yes, the password is on the note.", "Oui, le mot de passe est sur le papier.", "Sí, la contraseña está en el papel."]], "17": [["Das freut mich. Schönen Tag noch!", "Fijn dat het smaakt. Fijne dag nog!", "I'm glad you like it. Have a nice day!", "Ça me fait plaisir. Bonne journée encore !", "Me alegro. ¡Que tengas buen día!"]]}}, {"n": 8, "t": "Restaurant: eten bestellen en rekening vragen", "tt": {"de": "Restaurant: Essen bestellen und um die Rechnung bitten", "nl": "Restaurant: eten bestellen en rekening vragen", "en": "Restaurant: ordering food and asking for the bill", "fr": "Restaurant : commander et demander l'addition", "es": "Restaurante: pedir la comida y la cuenta"}, "r": [["j", "Haben Sie noch einen Tisch für zwei Personen?", "Hebben jullie nog een tafel voor twee personen?", "Do you have a table for two left?", "Vous avez encore une table pour deux ?", "¿Tienen todavía una mesa para dos?"], ["a", "Ja, hier entlang, bitte.", "Ja, deze kant op, alstublieft.", "Yes, this way, please.", "Oui, par ici, s'il vous plaît.", "Sí, por aquí, por favor."], ["j", "Haben Sie eine Speisekarte?", "Heeft u een menukaart?", "Could we have the menu?", "Vous avez la carte, s'il vous plaît ?", "¿Tiene la carta, por favor?"], ["a", "Hier bitte. Möchten Sie schon etwas trinken?", "Alstublieft. Wilt u al iets drinken?", "Here you are. Would you like something to drink?", "Voilà. Vous voulez déjà boire quelque chose ?", "Aquí tiene. ¿Quiere beber algo ya?"], ["j", "Zwei Wasser und ein Glas Rotwein, bitte.", "Twee water en een glas rode wijn, alstublieft.", "Two waters and a glass of red wine, please.", "Deux eaux et un verre de vin rouge, s'il vous plaît.", "Dos aguas y una copa de vino tinto, por favor."], ["a", "Haben Sie schon entschieden?", "Hebt u al gekozen?", "Have you decided?", "Vous avez choisi ?", "¿Ya han decidido?"], ["j", "Ja, ich nehme das Gericht des Tages.", "Ja, ik neem het dagmenu.", "Yes, I'll have the dish of the day.", "Oui, je prends le plat du jour.", "Sí, yo tomo el plato del día."], ["a", "Und Sie?", "En u?", "And for you?", "Et pour vous ?", "¿Y usted?"], ["j", "Ich hätte gern die Suppe, und dann Fisch.", "Ik wil graag de soep, en daarna de vis.", "I'd like the soup, and then the fish.", "Je voudrais la soupe, puis le poisson.", "Quiero la sopa y luego el pescado."], ["a", "Ist alles in Ordnung mit dem Essen?", "Is alles naar wens?", "Is everything all right with the food?", "Tout est bon ?", "¿Todo bien con la comida?"], ["j", "Ja, sehr lecker, danke.", "Ja, heel lekker, dank u.", "Yes, very tasty, thanks.", "Oui, très bon, merci.", "Sí, muy rico, gracias."], ["a", "Möchten Sie noch etwas?", "Wilt u nog iets?", "Would you like anything else?", "Vous voulez autre chose ?", "¿Quiere algo más?"], ["j", "Die Rechnung, bitte.", "De rekening, alstublieft.", "The bill, please.", "L'addition, s'il vous plaît.", "La cuenta, por favor."], ["a", "Zusammen oder getrennt?", "Samen of apart?", "Together or separate?", "Ensemble ou séparé ?", "¿Juntos o por separado?"], ["j", "Getrennt, bitte.", "Apart, alstublieft.", "Separate, please.", "Séparément, s'il vous plaît.", "Por separado, por favor."], ["a", "Gern. Das macht zusammen vierzig Euro.", "Natuurlijk. Dat is samen veertig euro.", "Of course. That's forty euros in total.", "Bien sûr. Ça fait quarante euros en tout.", "Claro. Son cuarenta euros en total."], ["j", "Kann ich bar zahlen?", "Kan ik contant betalen?", "Can I pay in cash?", "Je peux payer en espèces ?", "¿Puedo pagar en efectivo?"], ["a", "Ja, klar. Hier ist das Wechselgeld.", "Ja, natuurlijk. Hier is het wisselgeld.", "Yes, sure. Here's your change.", "Oui, bien sûr. Voilà la monnaie.", "Sí, claro. Aquí tiene el cambio."], ["j", "Danke, das Essen war ausgezeichnet!", "Dank u, het eten was uitstekend!", "Thanks, the food was excellent!", "Merci, le repas était excellent !", "¡Gracias, la comida estaba excelente!"], ["a", "Freut mich! Auf Wiedersehen.", "Fijn! Tot ziens.", "Glad to hear it! Goodbye.", "Ravi ! Au revoir.", "¡Me alegro! Adiós."]], "v": {"0": [["Hast du noch einen Tisch für zwei?", "Heb je nog een tafel voor twee?", "Do you have a table for two left?", "Tu as encore une table pour deux ?", "¿Tienes todavía una mesa para dos?"]], "1": [["Ja, hier lang, bitte.", "Ja, deze kant op.", "Yes, this way.", "Oui, par ici.", "Sí, por aquí."]], "2": [["Hast du eine Speisekarte?", "Heb je een menukaart?", "Could we have the menu?", "Tu as la carte, s'il te plaît ?", "¿Tienes la carta, por favor?"]], "3": [["Hier, bitte. Willst du schon was trinken?", "Alsjeblieft. Wil je al iets drinken?", "Here you go. Want something to drink already?", "Voilà. Tu veux déjà boire quelque chose ?", "Aquí tienes. ¿Quieres beber algo ya?"]], "5": [["Habt ihr schon entschieden?", "Hebben jullie al gekozen?", "Have you guys decided?", "Vous avez choisi ?", "¿Ya se han decidido?"]], "7": [["Und du?", "En jij?", "And for you?", "Et pour toi ?", "¿Y tú?"]], "9": [["Schmeckt es Ihnen?", "Smaakt het u?", "Is the food all right for you?", "Ça vous plaît ?", "¿Le gusta la comida?"]], "11": [["Möchtest du noch was?", "Wil je nog iets?", "Would you like anything else?", "Tu veux autre chose ?", "¿Quieres algo más?"]], "13": [["Alles zusammen?", "Alles samen?", "All together?", "Tout ensemble ?", "¿Todo junto?"]], "15": [["Gern. Das macht vierzig Euro.", "Natuurlijk. Dat is veertig euro.", "Sure. That's forty euros.", "Bien sûr. Ça fait quarante euros.", "Claro. Son cuarenta euros."]], "17": [["Ja, gerne. Hier ist das Restgeld.", "Ja, graag. Hier is het wisselgeld.", "Yes, sure. Here's your change.", "Oui, bien sûr. Voilà la monnaie.", "Sí, claro. Aquí está el cambio."]], "19": [["Freut mich! Tschüss.", "Fijn! Doei.", "Glad to hear it! Bye.", "Ravi ! Salut.", "¡Me alegro! Adiós."]]}, "p": [["Einen Tisch für [getal] Personen, bitte.", "Een tafel voor [getal] personen, alstublieft.", "A table for [getal], please.", "Une table pour [getal], s'il vous plaît.", "Una mesa para [getal], por favor."]]}, {"n": 9, "t": "Winkel: boodschappen en vragen naar producten", "tt": {"de": "Geschäft: Einkaufen und nach Produkten fragen", "nl": "Winkel: boodschappen en vragen naar producten", "en": "Shop: groceries and asking about products", "fr": "Magasin : courses et questions sur les produits", "es": "Tienda: la compra y preguntar por productos"}, "r": [["j", "Entschuldigung, wo finde ich Milch?", "Excuseer, waar vind ik melk?", "Excuse me, where can I find milk?", "Excusez-moi, où est le lait ?", "Perdone, ¿dónde encuentro leche?"], ["a", "Im hinteren Teil des Ladens, rechts.", "Achterin de winkel, rechts.", "At the back of the shop, on the right.", "Au fond du magasin, à droite.", "Al fondo de la tienda, a la derecha."], ["j", "Haben Sie auch laktosefreie Milch?", "Hebben jullie ook lactosevrije melk?", "Do you also have lactose-free milk?", "Vous avez aussi du lait sans lactose ?", "¿También tienen leche sin lactosa?"], ["a", "Ja, die Milch steht dort neben dem Joghurt.", "Ja, die staat daar naast de yoghurt.", "Yes, it's over there next to the yoghurt.", "Oui, il est là-bas à côté du yaourt.", "Sí, está allí al lado del yogur."], ["j", "Wie viel kostet das Brot?", "Hoeveel kost dit brood?", "How much is this bread?", "Combien coûte ce pain ?", "¿Cuánto cuesta este pan?"], ["a", "Das kostet 2,50 Euro.", "Dat kost twee euro vijftig.", "That's two euros fifty.", "Ça coûte deux euros cinquante.", "Cuesta dos euros con cincuenta."], ["j", "Haben Sie eine Tüte?", "Heeft u een tas?", "Do you have a bag?", "Vous avez un sac ?", "¿Tiene una bolsa?"], ["a", "Ja, eine Tüte kostet zehn Cent.", "Ja, een tas kost tien cent.", "Yes, a bag costs ten cents.", "Oui, un sac coûte dix centimes.", "Sí, una bolsa cuesta diez céntimos."], ["j", "Ist dieser Käse aus der Region?", "Komt deze kaas uit de streek?", "Is this cheese from the region?", "Ce fromage vient de la région ?", "¿Este queso es de la región?"], ["a", "Ja, der ist von einem Bauernhof hier in der Nähe.", "Ja, die komt van een boerderij hier in de buurt.", "Yes, it's from a farm near here.", "Oui, il vient d'une ferme près d'ici.", "Sí, viene de una granja cercana."], ["j", "Haben Sie das auch in einer kleineren Packung?", "Hebben jullie dit ook in een kleinere verpakking?", "Do you have this in a smaller pack?", "Vous avez ça en plus petit format ?", "¿Tienen esto en un envase más pequeño?"], ["a", "Ich schaue nach. Einen Moment, bitte.", "Ik kijk even. Eén moment.", "Let me check. One moment, please.", "Je regarde. Un instant, s'il vous plaît.", "Miro. Un momento, por favor."], ["j", "Danke. Wann machen Sie heute zu?", "Dank u. Hoe laat sluit u vandaag?", "Thanks. When do you close today?", "Merci. Vous fermez à quelle heure aujourd'hui ?", "Gracias. ¿A qué hora cierran hoy?"], ["a", "Um zwanzig Uhr.", "Om acht uur.", "At eight o'clock.", "À vingt heures.", "A las ocho."], ["j", "Wo ist die Kasse?", "Waar is de kassa?", "Where is the checkout?", "Où est la caisse ?", "¿Dónde está la caja?"], ["a", "Vorne, neben dem Eingang.", "Vooraan, naast de ingang.", "At the front, next to the entrance.", "Devant, à côté de l'entrée.", "Al frente, junto a la entrada."], ["j", "Danke, schönen Tag noch!", "Dank u, fijne dag nog!", "Thanks, have a nice day!", "Merci, bonne journée !", "¡Gracias, que tenga buen día!"], ["a", "Danke, Ihnen auch!", "Dank u, u ook!", "Thank you, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"]], "v": {"1": [["Ganz hinten im Laden, rechts.", "Helemaal achterin, rechts.", "Right at the back, on your right.", "Tout au fond, à droite.", "Al fondo, a la derecha."]], "3": [["Ja, die steht da, neben dem Joghurt.", "Ja, die staat daar naast de yoghurt.", "Yes, it's over there, next to the yoghurt.", "Oui, il est là, à côté du yaourt.", "Sí, está ahí, al lado del yogur."]], "5": [["Das sind 2,50 Euro.", "Dat is twee euro vijftig.", "That's two fifty.", "Ça fait deux euros cinquante.", "Son dos con cincuenta."]], "6": [["Hast du eine Tüte?", "Heb je een tas?", "Do you have a bag?", "Tu as un sac ?", "¿Tienes una bolsa?"]], "7": [["Ja, die kostet zehn Cent.", "Ja, een tasje kost tien cent.", "Yes, it costs ten cents.", "Oui, ça coûte dix centimes.", "Sí, cuesta diez céntimos."]], "9": [["Ja, der kommt von einem Hof hier in der Nähe.", "Ja, die komt van een boerderij hier vlakbij.", "Yes, it comes from a farm nearby.", "Oui, il vient d'une ferme tout près.", "Sí, viene de una granja aquí cerca."]], "11": [["Ich schau mal nach. Einen Moment.", "Ik kijk even. Een moment.", "Let me check. One moment.", "Je regarde. Un instant.", "Miro. Un momento."]], "13": [["Um acht Uhr abends.", "Om acht uur 's avonds.", "At eight in the evening.", "À vingt heures.", "A las ocho de la noche."]], "15": [["Vorne, gleich beim Eingang.", "Helemaal vooraan, bij de ingang.", "At the front, right by the entrance.", "Tout devant, près de l'entrée.", "Al frente, junto a la entrada."]], "17": [["Danke, dir auch!", "Dank je, jij ook!", "Thank you, you too!", "Merci, toi aussi !", "¡Gracias, igualmente!"]]}}, {"n": 10, "t": "Betalen: pinnen, kassa en korting", "tt": {"de": "Bezahlen: Karte, Kasse und Rabatt", "nl": "Betalen: pinnen, kassa en korting", "en": "Paying: card, checkout and discounts", "fr": "Payer : carte, caisse et réduction", "es": "Pagar: tarjeta, caja y descuento"}, "r": [["j", "Ich möchte bezahlen.", "Ik wil betalen.", "I'd like to pay.", "Je voudrais payer.", "Quiero pagar."], ["a", "Das macht zusammen neun Euro dreißig.", "Dat is samen negen euro dertig.", "That's nine euros thirty together.", "Ça fait neuf euros trente en tout.", "Son nueve euros con treinta en total."], ["j", "Kann ich mit Karte zahlen?", "Kan ik pinnen?", "Can I pay by card?", "Je peux payer par carte ?", "¿Puedo pagar con tarjeta?"], ["a", "Ja, halten Sie die Karte bitte an das Gerät.", "Ja, houd uw pas tegen het apparaat.", "Yes, please hold your card to the reader.", "Oui, approchez la carte du terminal.", "Sí, acerque la tarjeta al terminal."], ["j", "Der Betrag ist falsch. Ich habe nur einen Artikel.", "Het bedrag klopt niet. Ik heb maar één artikel.", "The amount is wrong. I only have one item.", "Le montant est faux. Je n'ai qu'un article.", "El importe está mal. Solo llevo un artículo."], ["a", "Oh, entschuldigen Sie. Ich schaue nach.", "O, sorry. Ik kijk even.", "Oh, sorry. Let me check.", "Oh, pardon. Je regarde.", "Ay, perdone. Miro."], ["j", "Haben Sie eine Kundenkarte?", "Heeft u een klantenkaart?", "Do you have a loyalty card?", "Vous avez une carte de fidélité ?", "¿Tienen tarjeta de cliente?"], ["a", "Ja, haben Sie Ihre Karte dabei?", "Ja, heeft u uw kaart bij u?", "Yes, do you have your card with you?", "Oui, vous avez votre carte ?", "Sí, ¿tiene su tarjeta con usted?"], ["j", "Nein, leider nicht. Kann ich eine neue bekommen?", "Nee, helaas niet. Kan ik er een nieuwe krijgen?", "No, unfortunately not. Can I get a new one?", "Non, malheureusement pas. Je peux en avoir une nouvelle ?", "No, por desgracia no. ¿Puedo conseguir una nueva?"], ["a", "Ja, an der Kasse, kostenlos.", "Ja, bij de kassa, gratis.", "Yes, at the checkout, for free.", "Oui, à la caisse, gratuitement.", "Sí, en la caja, gratis."], ["j", "Gibt es heute einen Rabatt?", "Is er vandaag korting?", "Is there a discount today?", "Il y a une réduction aujourd'hui ?", "¿Hay algún descuento hoy?"], ["a", "Ja, zwanzig Prozent auf Obst.", "Ja, twintig procent op fruit.", "Yes, twenty percent off fruit.", "Oui, vingt pour cent sur les fruits.", "Sí, veinte por ciento en fruta."], ["j", "Super! Ich nehme dann die Äpfel.", "Super! Dan neem ik de appels.", "Great! Then I'll take the apples.", "Super ! Je prends alors les pommes.", "¡Genial! Entonces me llevo las manzanas."], ["a", "Haben Sie noch eine Tüte?", "Hebt u nog een tas nodig?", "Do you need another bag?", "Vous voulez encore un sac ?", "¿Necesita otra bolsa?"], ["j", "Ja, bitte. Haben Sie einen Kassenbon?", "Ja, graag. Krijg ik een bonnetje?", "Yes, please. Can I have a receipt?", "Oui, s'il vous plaît. Vous avez un ticket de caisse ?", "Sí, por favor. ¿Me da un ticket?"], ["a", "Hier ist er. Schönen Abend!", "Hier is hij. Fijne avond!", "Here it is. Have a nice evening!", "Le voilà. Bonne soirée !", "Aquí lo tiene. ¡Buenas tardes!"], ["j", "Danke, Ihnen auch!", "Dank u, u ook!", "Thanks, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"], ["a", "Auf Wiedersehen!", "Tot ziens!", "Goodbye!", "Au revoir !", "¡Adiós!"]], "v": {"1": [["Das sind zusammen neun Euro dreißig.", "Dat zijn samen negen euro dertig.", "That's nine thirty altogether.", "Ça fait neuf euros trente au total.", "Son nueve con treinta en total."]], "3": [["Ja, halt die Karte bitte ans Gerät.", "Ja, houd je pas tegen het apparaat.", "Yes, hold your card to the reader.", "Oui, approche la carte du terminal.", "Sí, acerca la tarjeta al terminal."]], "5": [["Oh, entschuldige. Ich schau mal nach.", "O, sorry. Ik kijk even.", "Oh, sorry. Let me check.", "Oh, pardon. Je regarde.", "Ay, perdona. Miro."]], "7": [["Ja, hast du deine Karte dabei?", "Ja, heb je je kaart bij je?", "Yes, do you have your card with you?", "Oui, tu as ta carte ?", "Sí, ¿tienes tu tarjeta contigo?"]], "9": [["Ja, an der Kasse, das ist kostenlos.", "Ja, bij de kassa, dat is gratis.", "Yes, at the checkout, it's free.", "Oui, à la caisse, c'est gratuit.", "Sí, en la caja, es gratis."]], "11": [["Ja, zwanzig Prozent auf alles Obst.", "Ja, twintig procent op al het fruit.", "Yes, twenty percent off all fruit.", "Oui, vingt pour cent sur tous les fruits.", "Sí, veinte por ciento en toda la fruta."]], "13": [["Brauchst du noch eine Tüte?", "Heb je nog een tas nodig?", "Do you need another bag?", "Tu veux encore un sac ?", "¿Necesitas otra bolsa?"]], "15": [["Hier, bitte. Schönen Abend noch!", "Alsjeblieft. Fijne avond nog!", "Here you go. Have a nice evening!", "Voilà. Bonne soirée !", "Aquí lo tiene. ¡Que tenga buenas tardes!"]], "17": [["Tschüss!", "Doei!", "Bye!", "Salut !", "¡Adiós!"]]}, "p": [["Das sind [getal] Euro, oder?", "Het is [getal] euro, toch?", "That's [getal] euros, right?", "C'est [getal] euros, c'est ça ?", "Son [getal] euros, ¿no?"]]}, {"n": 11, "t": "Kleding: maat, kleur en passen", "tt": {"de": "Kleidung: Größe, Farbe und Anprobieren", "nl": "Kleding: maat, kleur en passen", "en": "Clothes: size, colour and trying on", "fr": "Vêtements : taille, couleur et essayage", "es": "Ropa: talla, color y probarse"}, "r": [["j", "Haben Sie diese Jacke auch in Größe M?", "Hebben jullie deze jas ook in maat M?", "Do you have this jacket in size M?", "Vous avez cette veste en taille M ?", "¿Tienen esta chaqueta en talla M?"], ["a", "Ich schaue nach. Einen Moment.", "Ik kijk even. Eén moment.", "Let me check. One moment.", "Je regarde. Un instant.", "Miro. Un momento."], ["j", "Haben Sie das auch in Schwarz?", "Hebben jullie die ook in zwart?", "Do you have it in black?", "Vous l'avez aussi en noir ?", "¿La tienen también en negro?"], ["a", "Ja, hier ist die Jacke in Schwarz.", "Ja, hier is de jas in zwart.", "Yes, here's the jacket in black.", "Oui, voici la veste en noir.", "Sí, aquí está la chaqueta en negro."], ["j", "Kann ich das anprobieren?", "Mag ik dit passen?", "Can I try this on?", "Je peux l'essayer ?", "¿Puedo probármela?"], ["a", "Natürlich. Die Umkleidekabine ist dort hinten.", "Natuurlijk. De pashokjes zijn daar achterin.", "Of course. The fitting room is at the back.", "Bien sûr. Les cabines sont au fond.", "Claro. El probador está al fondo."], ["j", "Wie passt sie? Ist sie zu klein?", "Hoe zit hij? Is hij te klein?", "How does it fit? Is it too small?", "Comment elle va ? Elle est trop petite ?", "¿Cómo le queda? ¿Es muy pequeña?"], ["a", "M passt gut, aber an den Schultern ist es etwas eng.", "M zit goed, maar bij de schouders is hij wat strak.", "Size M fits well, but it's a bit tight at the shoulders.", "La M va bien, mais un peu serrée aux épaules.", "La M le queda bien, pero un poco ajustada de hombros."], ["j", "Haben Sie eine Nummer größer?", "Hebben jullie een maat groter?", "Do you have one size bigger?", "Vous avez une taille au-dessus ?", "¿Tienen una talla más grande?"], ["a", "Ja, Größe L. Einen Moment.", "Ja, maat L. Een moment.", "Yes, size L. One moment.", "Oui, en L. Un instant.", "Sí, en talla L. Un momento."], ["j", "Die passt mir perfekt. Was kostet sie?", "Deze past perfect. Hoeveel kost hij?", "This one fits perfectly. How much is it?", "Celle-ci me va parfaitement. Combien coûte-t-elle ?", "Esta me queda perfecta. ¿Cuánto cuesta?"], ["a", "Sie kostet 79 Euro.", "Die kost 79 euro.", "It costs 79 euros.", "Elle coûte 79 euros.", "Cuesta 79 euros."], ["j", "Gibt es einen Rabatt bei Barzahlung?", "Krijg ik korting als ik contant betaal?", "Is there a discount for paying cash?", "Il y a une réduction si je paie en espèces ?", "¿Hay descuento si pago en efectivo?"], ["a", "Nein, leider nicht. Aber wir haben heute ein Angebot.", "Nee, helaas niet. Maar we hebben vandaag een aanbieding.", "No, unfortunately not. But we have a special offer today.", "Non, malheureusement pas. Mais nous avons une promotion aujourd'hui.", "No, por desgracia no. Pero hoy tenemos una oferta."], ["j", "Kann ich die Jacke umtauschen, wenn sie mir nicht gefällt?", "Kan ik de jas ruilen als hij me toch niet bevalt?", "Can I exchange the jacket if I don't like it?", "Je peux échanger la veste si elle ne me plaît pas ?", "¿Puedo cambiar la chaqueta si no me gusta?"], ["a", "Ja, innerhalb von 14 Tagen mit Kassenbon.", "Ja, binnen veertien dagen met bonnetje.", "Yes, within 14 days with the receipt.", "Oui, dans les 14 jours avec le ticket de caisse.", "Sí, dentro de 14 días con el ticket."], ["j", "Gut, ich nehme sie.", "Oké, ik neem hem.", "Good, I'll take it.", "Très bien, je la prends.", "Bien, me la llevo."], ["a", "Möchten Sie eine Tüte?", "Wilt u een tas?", "Would you like a bag?", "Vous voulez un sac ?", "¿Quiere una bolsa?"], ["j", "Ja, bitte. Danke für Ihre Hilfe.", "Ja, graag. Dank u voor uw hulp.", "Yes, please. Thanks for your help.", "Oui, s'il vous plaît. Merci pour votre aide.", "Sí, por favor. Gracias por su ayuda."], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga un buen día!"]], "v": {"1": [["Ich guck mal. Einen Moment.", "Ik kijk even. Een moment.", "Let me look. One moment.", "Je regarde. Un instant.", "Miro. Un momento."]], "3": [["Ja, hier hängt sie, in Schwarz.", "Ja, hier hangt hij, in zwart.", "Yes, it's here, in black.", "Oui, la voici, en noir.", "Sí, aquí está, en negro."]], "5": [["Klar. Die Kabine ist da hinten.", "Natuurlijk. De pashokjes zijn daarachter.", "Sure. The fitting room is back there.", "Bien sûr. Les cabines sont là-bas.", "Claro. El probador está allí atrás."]], "7": [["M sitzt gut, aber an den Schultern ist es etwas eng.", "M zit prima, maar hij is wat strak op de schouders.", "M fits fine, but it's a bit snug on the shoulders.", "Le M va bien, mais un peu serré aux épaules.", "La M queda bien, pero un poco apretada de hombros."]], "9": [["Ja, die habe ich in L. Einen Moment.", "Ja, die heb ik in L. Even wachten.", "Yes, I have it in L. One moment.", "Oui, en L. Un instant.", "Sí, en talla L. Un momento."]], "11": [["Die kostet 79 Euro.", "Die is 79 euro.", "That's 79 euros.", "Elle fait 79 euros.", "Son 79 euros."]], "13": [["Nein, leider nicht. Aber heute gibt es eine Aktion.", "Nee, sorry, niet. Wel is er vandaag een actie.", "No, sorry. But there's a promotion today.", "Non, désolé. Mais il y a une promotion aujourd'hui.", "No, lo siento. Pero hoy hay una promoción."]], "15": [["Ja, innerhalb von vierzehn Tagen, mit dem Kassenbon.", "Ja, binnen twee weken met je bonnetje.", "Yes, within two weeks, with your receipt.", "Oui, dans les deux semaines, avec le ticket.", "Sí, en un plazo de dos semanas, con el ticket."]], "17": [["Willst du eine Tüte?", "Wil je een tasje?", "Want a bag?", "Tu veux un sac ?", "¿Quieres una bolsa?"]], "18": [["Ja, bitte. Danke für deine Hilfe.", "Ja, graag. Bedankt voor je hulp.", "Yes, please. Thanks for your help.", "Oui, s'il te plaît. Merci pour ton aide.", "Sí, por favor. Gracias por tu ayuda."]], "19": [["Gern. Schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tengas un buen día!"]]}, "p": [["Ich brauche Größe [getal].", "Ik heb maat [getal] nodig.", "I need size [getal].", "Il me faut la taille [getal].", "Necesito la talla [getal]."]]}, {"n": 12, "t": "Hotel: inchecken en reserveren", "tt": {"de": "Hotel: Einchecken und Reservieren", "nl": "Hotel: inchecken en reserveren", "en": "Hotel: checking in and booking", "fr": "Hôtel : arrivée et réservation", "es": "Hotel: registrarse y reservar"}, "r": [["j", "Guten Abend, ich habe ein Zimmer reserviert.", "Goedenavond, ik heb een kamer gereserveerd.", "Good evening, I have a room booked.", "Bonsoir, j'ai réservé une chambre.", "Buenas noches, tengo una habitación reservada."], ["a", "Auf welchen Namen?", "Op welke naam?", "Under what name?", "Au nom de qui ?", "¿A nombre de quién?"], ["j", "Auf den Namen Anna Berg.", "Op de naam Anna Berg.", "Under the name Anna Berg.", "Au nom de Anna Berg.", "A nombre de Anna Berg."], ["a", "Ja, zwei Nächte im Doppelzimmer. Hier ist Ihr Schlüssel.", "Ja, twee nachten in de tweepersoonskamer. Hier is uw sleutel.", "Yes, two nights in a double room. Here is your key.", "Oui, deux nuits en chambre double. Voici votre clé.", "Sí, dos noches en habitación doble. Aquí tiene la llave."], ["j", "Wann gibt es Frühstück?", "Hoe laat is het ontbijt?", "When is breakfast?", "À quelle heure est le petit-déjeuner ?", "¿A qué hora es el desayuno?"], ["a", "Von sieben bis zehn Uhr im Erdgeschoss.", "Van zeven tot tien uur op de begane grond.", "From seven to ten, on the ground floor.", "De sept heures à dix heures, au rez-de-chaussée.", "De siete a diez, en la planta baja."], ["j", "Ist das Frühstück im Preis inbegriffen?", "Is het ontbijt bij de prijs inbegrepen?", "Is breakfast included in the price?", "Le petit-déjeuner est inclus dans le prix ?", "¿El desayuno está incluido en el precio?"], ["a", "Ja, es ist inklusive.", "Ja, het is inbegrepen.", "Yes, it's included.", "Oui, il est inclus.", "Sí, está incluido."], ["j", "Gibt es hier WLAN?", "Is er hier wifi?", "Is there wifi here?", "Il y a le wifi ici ?", "¿Hay wifi aquí?"], ["a", "Ja, das Passwort steht auf Ihrer Karte.", "Ja, het wachtwoord staat op uw kaart.", "Yes, the password is on your card.", "Oui, le mot de passe est sur votre carte.", "Sí, la contraseña está en su tarjeta."], ["j", "Wann muss ich auschecken?", "Hoe laat moet ik uitchecken?", "What time do I need to check out?", "À quelle heure dois-je libérer la chambre ?", "¿A qué hora tengo que dejar la habitación?"], ["a", "Bis elf Uhr am Morgen.", "Tot elf uur 's ochtends.", "By eleven in the morning.", "Avant onze heures du matin.", "Antes de las once de la mañana."], ["j", "Kann ich mein Gepäck hier lassen, wenn ich später komme?", "Kan ik mijn bagage hier laten als ik later kom?", "Can I leave my luggage here if I come back later?", "Je peux laisser mes bagages ici si je reviens plus tard ?", "¿Puedo dejar mi equipaje aquí si vuelvo más tarde?"], ["a", "Ja, natürlich. Wir bewahren es für Sie auf.", "Ja, natuurlijk. Wij bewaren het voor u.", "Yes, of course. We'll keep it for you.", "Oui, bien sûr. Nous le garderons pour vous.", "Sí, claro. Lo guardamos para usted."], ["j", "Haben Sie für morgen noch ein Zimmer frei?", "Hebben jullie morgen nog een kamer vrij?", "Do you have a room free for tomorrow?", "Vous avez une chambre libre pour demain ?", "¿Tienen una habitación libre para mañana?"], ["a", "Ja, aber nur noch ein Einzelzimmer.", "Ja, maar alleen nog een eenpersoonskamer.", "Yes, but only a single room left.", "Oui, mais il ne reste qu'une chambre simple.", "Sí, pero solo queda una individual."], ["j", "Das ist in Ordnung. Danke!", "Dat is goed. Dank u!", "That's fine. Thanks!", "Ça me va. Merci !", "Está bien. ¡Gracias!"], ["a", "Gern geschehen. Gute Nacht!", "Graag gedaan. Welterusten!", "You're welcome. Good night!", "Avec plaisir. Bonne nuit !", "De nada. ¡Buenas noches!"]], "v": {"1": [["Und auf welchen Namen bitte?", "Op welke naam, alstublieft?", "And what name is it under?", "Et à quel nom, s'il vous plaît ?", "¿Y a nombre de quién, por favor?"]], "3": [["Ja, zwei Nächte im Doppelzimmer. Hier hast du den Schlüssel.", "Ja, twee nachten. Hier is je sleutel.", "Yes, two nights in a double room. Here's your key.", "Oui, deux nuits. Voilà ta clé.", "Sí, dos noches. Aquí tienes la llave."]], "5": [["Das Frühstück gibt es von sieben bis zehn Uhr, unten.", "Van zeven tot tien uur, op de begane grond.", "Breakfast is from seven to ten, downstairs.", "De sept à dix heures, au rez-de-chaussée.", "De siete a diez, abajo."]], "7": [["Ja, das ist dabei.", "Ja, dat is inbegrepen.", "Yes, that's included.", "Oui, c'est compris.", "Sí, va incluido."]], "9": [["Ja, das Passwort steht auf der Karte.", "Ja, het wachtwoord staat op je sleutelkaart.", "Yes, the password is on your card.", "Oui, le mot de passe est sur ta carte.", "Sí, la contraseña está en tu tarjeta."]], "11": [["Spätestens um elf Uhr morgens.", "Uiterlijk elf uur 's ochtends.", "By eleven a.m. at the latest.", "Au plus tard à onze heures du matin.", "A más tardar a las once de la mañana."]], "13": [["Ja, klar. Wir bewahren es für dich auf.", "Ja, natuurlijk. We bewaren het voor je.", "Yes, sure. We'll keep it for you.", "Oui, bien sûr. On le gardera pour toi.", "Sí, claro. Lo guardamos para ti."]], "15": [["Ja, aber wir haben nur noch ein Einzelzimmer.", "Ja, maar er is nog één eenpersoonskamer.", "Yes, but we only have one single room left.", "Oui, mais il ne reste qu'une chambre individuelle.", "Sí, pero solo queda una habitación individual."]], "17": [["Gern. Gute Nacht!", "Graag gedaan. Welterusten!", "You're welcome. Good night!", "Avec plaisir. Bonne nuit !", "De nada. ¡Buenas noches!"]]}, "p": [["Ich bleibe [getal] Nächte.", "Ik blijf [getal] nachten.", "I'll stay [getal] nights.", "Je reste [getal] nuits.", "Me quedo [getal] noches."], ["Ich reise am [dag] ab.", "Ik vertrek op [dag].", "I leave on [dag].", "Je pars [dag].", "Me voy el [dag]."]]}, {"n": 13, "t": "Hotel: klacht over de kamer", "tt": {"de": "Hotel: Beschwerde über das Zimmer", "nl": "Hotel: klacht over de kamer", "en": "Hotel: a complaint about the room", "fr": "Hôtel : une réclamation sur la chambre", "es": "Hotel: una queja sobre la habitación"}, "r": [["j", "Entschuldigung, in meinem Zimmer ist es sehr kalt.", "Sorry, in mijn kamer is het erg koud.", "Excuse me, my room is very cold.", "Excusez-moi, il fait très froid dans ma chambre.", "Perdone, en mi habitación hace mucho frío."], ["a", "Oh, das tut mir leid. Ich schaue nach der Heizung.", "Oh, wat vervelend. Ik kijk even naar de verwarming.", "Oh, I'm sorry. I'll check the heating.", "Oh, je suis désolé. Je vais vérifier le chauffage.", "Lo siento. Miro la calefacción."], ["j", "Kann ich ein anderes Zimmer bekommen?", "Kan ik een andere kamer krijgen?", "Can I get a different room?", "Je peux avoir une autre chambre ?", "¿Puedo cambiar de habitación?"], ["a", "Ja, ich kann Ihnen ein Zimmer im dritten Stock geben.", "Ja, ik kan u een kamer op de derde verdieping geven.", "Yes, I can give you a room on the third floor.", "Oui, je peux vous donner une chambre au troisième étage.", "Sí, le puedo dar una habitación en la tercera planta."], ["j", "Ist das Zimmer ruhiger?", "Is die kamer rustiger?", "Is that room quieter?", "Cette chambre est plus calme ?", "¿Esa habitación es más tranquila?"], ["a", "Ja, es liegt zur Rückseite des Hotels.", "Ja, hij ligt aan de achterkant van het hotel.", "Yes, it faces the back of the hotel.", "Oui, elle donne sur l'arrière de l'hôtel.", "Sí, da a la parte trasera del hotel."], ["j", "Ich habe auch kein warmes Wasser im Bad.", "Ik heb ook geen warm water in de badkamer.", "I also have no hot water in the bathroom.", "Je n'ai pas non plus d'eau chaude dans la salle de bain.", "Tampoco tengo agua caliente en el baño."], ["a", "Das ist nicht gut. Ich rufe den Techniker.", "Dat is niet goed. Ik bel de monteur.", "That's not good. I'll call the technician.", "Ce n'est pas bien. J'appelle le technicien.", "Eso no está bien. Llamo al técnico."], ["j", "Wie lange dauert das ungefähr?", "Hoe lang duurt dat ongeveer?", "How long will that take roughly?", "Ça prendra combien de temps environ ?", "¿Cuánto tardará más o menos?"], ["a", "Etwa eine halbe Stunde.", "Ongeveer een half uur.", "About half an hour.", "Environ une demi-heure.", "Unos treinta minutos."], ["j", "Gut, ich warte. Danke.", "Oké, ik wacht. Dank u.", "Okay, I'll wait. Thanks.", "D'accord, j'attends. Merci.", "Vale, espero. Gracias."], ["a", "Ich bringe Ihnen einen Tee, während Sie warten.", "Ik breng u thee terwijl u wacht.", "I'll bring you a tea while you wait.", "Je vous apporte un thé en attendant.", "Le traigo un té mientras espera."], ["j", "Das ist sehr nett. Danke!", "Dat is erg aardig. Bedankt!", "That's very kind. Thanks!", "C'est très gentil. Merci !", "Qué amable. ¡Gracias!"], ["a", "Gern geschehen. Ich sage Bescheid, wenn das Zimmer fertig ist.", "Graag gedaan. Ik laat u weten als de kamer klaar is.", "You're welcome. I'll let you know when the room is ready.", "Avec plaisir. Je vous préviens quand la chambre sera prête.", "De nada. Le aviso cuando la habitación esté lista."]], "v": {"1": [["Oh, das tut mir leid. Ich sehe mal nach der Heizung.", "Oh, wat vervelend. Ik check de verwarming.", "Oh, sorry about that. I'll look at the heating.", "Oh, désolé. Je vérifie le chauffage.", "Lo siento. Reviso la calefacción."]], "3": [["Ja, ich kann dir ein Zimmer im dritten Stock geben.", "Ja, ik kan je een kamer geven op de derde.", "Yes, I can give you a room on the third floor.", "Oui, je peux te donner une chambre au troisième.", "Sí, te puedo dar una habitación en la tercera planta."]], "5": [["Ja, das liegt auf der Rückseite.", "Ja, die ligt aan de achterkant.", "Yes, it's at the back of the hotel.", "Oui, elle est à l'arrière de l'hôtel.", "Sí, está en la parte de atrás del hotel."]], "7": [["Das ist nicht gut. Ich rufe kurz den Techniker.", "Dat is niet goed. Ik bel even de monteur.", "That's not good. I'll call the technician.", "Ce n'est pas bien. J'appelle le technicien.", "Eso no está bien. Llamo al técnico."]], "9": [["So eine halbe Stunde, denke ich.", "Een halfuurtje, denk ik.", "About half an hour, I think.", "Une demi-heure, je pense.", "Unos treinta minutos, creo."]], "11": [["Ich bringe dir einen Tee, während du wartest.", "Ik breng je even een thee.", "I'll bring you a tea while you wait.", "Je t'apporte un thé en attendant.", "Te traigo un té mientras esperas."]], "13": [["Gern geschehen. Ich sage dir Bescheid, wenn das Zimmer fertig ist.", "Graag gedaan. Ik zeg het je als de kamer klaar is.", "You're welcome. I'll let you know when the room's ready.", "Avec plaisir. Je te préviens quand la chambre est prête.", "De nada. Te aviso cuando la habitación esté lista."]]}}, {"n": 14, "t": "Apotheek: vragen over een medicijn", "tt": {"de": "Apotheke: Fragen zu einem Medikament", "nl": "Apotheek: vragen over een medicijn", "en": "Pharmacy: questions about a medicine", "fr": "Pharmacie : questions sur un médicament", "es": "Farmacia: preguntas sobre un medicamento"}, "r": [["j", "Guten Tag, ich brauche etwas gegen Kopfschmerzen.", "Hallo, ik heb iets nodig tegen hoofdpijn.", "Hi, I need something for a headache.", "Bonjour, il me faudrait quelque chose contre les maux de tête.", "Hola, necesito algo para el dolor de cabeza."], ["a", "Haben Sie ein Rezept?", "Heeft u een recept?", "Do you have a prescription?", "Vous avez une ordonnance ?", "¿Tiene receta?"], ["j", "Nein, ich habe kein Rezept. Was können Sie empfehlen?", "Nee, ik heb geen recept. Wat kunt u aanraden?", "No, I don't have a prescription. What can you recommend?", "Non, je n'ai pas d'ordonnance. Que me conseillez-vous ?", "No, no tengo receta. ¿Qué me recomienda?"], ["a", "Paracetamol ist gut. Nehmen Sie es mit Wasser.", "Paracetamol is goed. Neem het met water in.", "Paracetamol is good. Take it with water.", "Le paracétamol convient bien. Prenez-le avec de l'eau.", "El paracetamol va bien. Tómelo con agua."], ["j", "Wie oft darf ich das nehmen?", "Hoe vaak mag ik dat innemen?", "How often can I take it?", "Je peux en prendre combien de fois ?", "¿Cada cuánto lo puedo tomar?"], ["a", "Alle vier bis sechs Stunden, nicht öfter als vier Mal am Tag.", "Elke vier tot zes uur, niet vaker dan vier keer per dag.", "Every four to six hours, no more than four times a day.", "Toutes les quatre à six heures, maximum quatre fois par jour.", "Cada cuatro a seis horas, no más de cuatro veces al día."], ["j", "Darf ich das mit Alkohol nehmen?", "Mag ik dit innemen met alcohol?", "Can I take this with alcohol?", "Je peux le prendre avec de l'alcool ?", "¿Puedo tomarlo con alcohol?"], ["a", "Nein, das ist nicht empfohlen. Fragen Sie bei Zweifeln den Apotheker.", "Nee, dat wordt afgeraden. Vraag het de apotheker bij twijfel.", "No, that's not advised. Ask the pharmacist if you're unsure.", "Non, ce n'est pas recommandé. Demandez au pharmacien en cas de doute.", "No, no es recomendable. Pregunte al farmacéutico si tiene dudas."], ["j", "Ich nehme auch andere Tabletten. Gibt es Wechselwirkungen?", "Ik gebruik ook andere pillen. Zijn er wisselwerkingen?", "I also take other tablets. Are there interactions?", "Je prends aussi d'autres comprimés. Il y a des interactions ?", "También tomo otras pastillas. ¿Hay interacciones?"], ["a", "Sagen Sie mir bitte, welche Tabletten das sind.", "Zeg me alstublieft welke pillen het zijn.", "Please tell me which tablets they are.", "Dites-moi lesquels, s'il vous plaît.", "Dígame cuáles son, por favor."], ["j", "Eine Tablette gegen Bluthochdruck und eine gegen Allergie.", "Een pil tegen hoge bloeddruk en een tegen allergie.", "One for high blood pressure and one for allergies.", "Un pour la tension et un pour les allergies.", "Una para la presión alta y otra para la alergia."], ["a", "Dann sollten Sie vorher mit Ihrem Arzt sprechen.", "Dan kunt u het beste eerst met uw arts overleggen.", "Then you should talk to your doctor first.", "Dans ce cas, parlez-en d'abord à votre médecin.", "En ese caso, hable antes con su médico."], ["j", "Okay. Ich nehme eine Packung Paracetamol, bitte.", "Oké. Ik neem een doosje paracetamol, alstublieft.", "Okay. I'll take a pack of paracetamol, please.", "D'accord. Je prends une boîte de paracétamol, s'il vous plaît.", "Vale. Me llevo una caja de paracetamol, por favor."], ["a", "Das macht sechs Euro achtzig.", "Dat is zes euro tachtig.", "That's six euros eighty.", "Ça fait six euros quatre-vingts.", "Son seis euros con ochenta."], ["j", "Danke. Gute Besserung!", "Dank u. Beterschap!", "Thanks. Get well soon!", "Merci. Bon courage !", "Gracias. ¡Que se mejore!"], ["a", "Danke, auf Wiedersehen.", "Dank u, tot ziens.", "Thank you, goodbye.", "Merci, au revoir.", "Gracias, adiós."]], "v": {"1": [["Hast du ein Rezept?", "Heb je een recept?", "Do you have a prescription?", "Tu as une ordonnance ?", "¿Tienes receta?"]], "3": [["Paracetamol ist gut. Nimm es mit Wasser ein.", "Paracetamol is een goed middel. Neem het met water in.", "Paracetamol is fine. Take it with water.", "Le paracétamol va bien. Prends-le avec de l'eau.", "El paracetamol va bien. Tómalo con agua."]], "5": [["Alle vier bis sechs Stunden, aber nicht öfter als vier Mal am Tag.", "Om de vier tot zes uur, maximaal vier keer per dag.", "Every four to six hours, four times a day at most.", "Toutes les quatre à six heures, quatre fois par jour au maximum.", "Cada cuatro a seis horas, cuatro veces al día como máximo."]], "7": [["Nein, das wird nicht empfohlen. Frag kurz den Apotheker.", "Nee, dat wordt afgeraden. Vraag het even aan de apotheker.", "No, that's not recommended. Ask the pharmacist.", "Non, ce n'est pas conseillé. Demande au pharmacien.", "No, no se recomienda. Pregúntale al farmacéutico."]], "9": [["Welche Tabletten sind das?", "Welke pillen zijn dat?", "Tell me which tablets they are.", "Dis-moi lesquels.", "Dime cuáles son."]], "11": [["Dann besprich es am besten zuerst mit deinem Arzt.", "Dan overleg je het beste eerst met je arts.", "Then you should talk to your doctor first.", "Dans ce cas, parle-en d'abord à ton médecin.", "En ese caso, habla antes con tu médico."]], "13": [["Sechs Euro achtzig, bitte.", "Zes euro tachtig, alstublieft.", "That'll be six euros eighty.", "Ça fera six euros quatre-vingts.", "Serán seis euros con ochenta."]], "15": [["Danke, tschüss.", "Dank je, tot ziens.", "Thank you, bye.", "Merci, salut.", "Gracias, adiós."]]}}, {"n": 15, "t": "Dokter: klachten uitleggen", "tt": {"de": "Arzt: Beschwerden erklären", "nl": "Dokter: klachten uitleggen", "en": "Doctor: explaining your symptoms", "fr": "Médecin : expliquer ses symptômes", "es": "Médico: explicar los síntomas"}, "r": [["j", "Guten Tag, ich bin hier wegen meiner Halsschmerzen.", "Goedemiddag, ik ben hier vanwege keelpijn.", "Hello, I'm here because of a sore throat.", "Bonjour, je viens pour un mal de gorge.", "Buenos días, vengo por un dolor de garganta."], ["a", "Seit wann haben Sie die Schmerzen?", "Sinds wanneer heeft u die pijn?", "Since when have you had the pain?", "Depuis quand avez-vous mal ?", "¿Desde cuándo tiene el dolor?"], ["j", "Seit gestern Abend. Und ich habe auch Fieber.", "Sinds gisteravond. En ik heb ook koorts.", "Since last night. And I also have a fever.", "Depuis hier soir. Et j'ai aussi de la fièvre.", "Desde anoche. Y también tengo fiebre."], ["a", "Wie hoch ist das Fieber? Haben Sie es gemessen?", "Hoe hoog is de koorts? Heeft u het gemeten?", "How high is the fever? Have you measured it?", "Quelle est la température ? Vous l'avez mesurée ?", "¿Qué temperatura tiene? ¿Se la ha medido?"], ["j", "Ja, achtunddreißig Komma acht Grad.", "Ja, achtendertig komma acht graden.", "Yes, thirty-eight point eight degrees.", "Oui, trente-huit virgule huit degrés.", "Sí, treinta y ocho coma ocho grados."], ["a", "Haben Sie auch Husten oder Schnupfen?", "Heeft u ook hoest of een verkoudheid?", "Do you also have a cough or a cold?", "Vous avez aussi de la toux ou un rhume ?", "¿También tiene tos o resfriado?"], ["j", "Ich habe ein bisschen Husten, aber keinen Schnupfen.", "Ik heb een beetje hoest, maar geen verkoudheid.", "I have a little cough, but no runny nose.", "J'ai un peu de toux, mais pas de rhume.", "Tengo un poco de tos, pero no estoy resfriado."], ["a", "Machen Sie bitte den Mund auf. Ihr Hals ist sehr rot.", "Doe uw mond eens open. Uw keel is erg rood.", "Please open your mouth. Your throat is very red.", "Ouvrez la bouche, s'il vous plaît. Votre gorge est très rouge.", "Abra la boca, por favor. Tiene la garganta muy roja."], ["j", "Ist das schlimm? Brauche ich Antibiotika?", "Is dat erg? Heb ik antibiotica nodig?", "Is it serious? Do I need antibiotics?", "C'est grave ? J'ai besoin d'antibiotiques ?", "¿Es grave? ¿Necesito antibióticos?"], ["a", "Ich denke, es ist eine Virusinfektion. Antibiotika helfen da nicht.", "Ik denk dat het een virusinfectie is. Antibiotica helpen dan niet.", "I think it's a viral infection. Antibiotics won't help with that.", "Je pense que c'est une infection virale. Les antibiotiques ne serviront à rien.", "Creo que es una infección viral. Los antibióticos no ayudan en ese caso."], ["j", "Was kann ich dann tun?", "Wat kan ik dan doen?", "What can I do then?", "Qu'est-ce que je peux faire alors ?", "¿Qué puedo hacer entonces?"], ["a", "Viel trinken, sich ausruhen und ein fiebersenkendes Mittel nehmen.", "Veel drinken, rusten en een koortswerend middel nemen.", "Drink plenty, rest, and take something for the fever.", "Buvez beaucoup, reposez-vous et prenez un médicament contre la fièvre.", "Beba mucho líquido, descanse y tome algo para la fiebre."], ["j", "Wann muss ich wieder kommen?", "Wanneer moet ik terugkomen?", "When do I need to come back?", "Quand dois-je revenir ?", "¿Cuándo tengo que volver?"], ["a", "Wenn es nach drei Tagen nicht besser ist oder Sie schlechter atmen.", "Als het na drie dagen niet beter is of u moeilijker ademt.", "If it's not better after three days or your breathing gets worse.", "Si ça ne va pas mieux en trois jours. Ou si vous respirez mal.", "Si después de tres días no mejora, o si respira peor."], ["j", "Danke, Herr Doktor. Auf Wiedersehen.", "Dank u, dokter. Tot ziens.", "Thank you, doctor. Goodbye.", "Merci, docteur. Au revoir.", "Gracias, doctor. Adiós."], ["a", "Gute Besserung! Auf Wiedersehen.", "Beterschap! Tot ziens.", "Get well soon! Goodbye.", "Bon rétablissement ! Au revoir.", "¡Que se mejore! Adiós."]], "v": {"1": [["Seit wann hast du die Schmerzen?", "Sinds wanneer heb je die pijn?", "Since when have you had the pain?", "Depuis quand as-tu mal ?", "¿Desde cuándo tienes el dolor?"]], "3": [["Wie hoch ist das Fieber? Hast du es gemessen?", "Hoeveel koorts heb je? Heb je het gemeten?", "How high is the fever? Have you measured it?", "Tu as combien de fièvre ? Tu l'as mesurée ?", "¿Cuánta fiebre tienes? ¿Te la has medido?"]], "5": [["Hast du auch Husten oder eine Erkältung?", "Heb je ook last van hoesten of een neus?", "Do you also have a cough or a cold?", "Tu as aussi de la toux ou un rhume ?", "¿También tienes tos o resfriado?"]], "7": [["Mach mal den Mund auf. Dein Hals ist sehr rot.", "Doe je mond eens open. Je keel is erg rood.", "Open your mouth, please. Your throat is very red.", "Ouvre la bouche. Ta gorge est très rouge.", "Abre la boca, por favor. Tienes la garganta muy roja."]], "9": [["Ich denke, es ist ein Virus. Antibiotika helfen dabei nicht.", "Ik denk dat het een virus is, daar helpen antibiotica niet bij.", "I think it's a virus. Antibiotics won't help.", "Je crois que c'est un virus. Les antibiotiques ne serviront pas.", "Creo que es un virus. Los antibióticos no sirven."]], "11": [["Trink viel, ruh dich aus und nimm etwas gegen das Fieber.", "Veel drinken, rust nemen en iets voor de koorts.", "Drink lots, rest and take something for the fever.", "Bois beaucoup, repose-toi et prends quelque chose contre la fièvre.", "Bebe mucho, descansa y toma algo para la fiebre."]], "13": [["Wenn es nach drei Tagen nicht besser ist oder du schwerer atmest.", "Als het na drie dagen niet over is of je slechter ademt.", "If it's not better after three days or your breathing gets worse.", "Si ça ne va pas mieux en trois jours. Ou si tu respires mal.", "Si después de tres días no mejora, o si respiras peor."]], "15": [["Gute Besserung! Tschüss.", "Beterschap! Doei.", "Get well soon! Bye.", "Bon rétablissement ! Salut.", "¡Que se mejore! Adiós."]]}}, {"n": 16, "t": "Afspraak maken en afzeggen", "tt": {"de": "Termin vereinbaren und absagen", "nl": "Afspraak maken en afzeggen", "en": "Making and cancelling an appointment", "fr": "Prendre et annuler un rendez-vous", "es": "Pedir y anular una cita"}, "r": [["j", "Guten Tag, ich möchte einen Termin machen.", "Hallo, ik wil graag een afspraak maken.", "Hello, I'd like to make an appointment.", "Bonjour, je voudrais prendre rendez-vous.", "Hola, quisiera pedir una cita."], ["a", "Gerne. Für wann möchten Sie kommen?", "Graag. Wanneer wilt u komen?", "Sure. When would you like to come?", "Bien sûr. Pour quand souhaitez-vous venir ?", "Claro. ¿Para cuándo quiere venir?"], ["j", "Hätten Sie nächste Woche Dienstag Zeit?", "Hebben jullie volgende week dinsdag een plek?", "Do you have time next Tuesday?", "Vous avez de la disponibilité mardi prochain ?", "¿Tienen hueco el martes que viene?"], ["a", "Am Dienstag um zehn Uhr oder um vierzehn Uhr.", "Dinsdag om tien uur of om twee uur.", "On Tuesday at ten or at two.", "Mardi à dix heures ou à quatorze heures.", "El martes a las diez o a las dos."], ["j", "Um zehn Uhr, bitte.", "Om tien uur, graag.", "At ten, please.", "À dix heures, s'il vous plaît.", "A las diez, por favor."], ["a", "Wie ist Ihr Name und Ihr Geburtsdatum?", "Wat is uw naam en geboortedatum?", "What is your name and date of birth?", "Quel est votre nom et votre date de naissance ?", "¿Cuál es su nombre y fecha de nacimiento?"], ["j", "Anna Berg, geboren am 3. Mai 1990.", "Anna Berg, geboren op 3 mei 1990.", "Anna Berg, born on 3 May 1990.", "Anna Berg, née le 3 mai 1990.", "Anna Berg, nacida el 3 de mayo de 1990."], ["a", "Gut, Ihr Termin ist am Dienstag um zehn Uhr.", "Goed, uw afspraak is dinsdag om tien uur.", "Good, your appointment is Tuesday at ten.", "Très bien, votre rendez-vous est mardi à dix heures.", "Bien, su cita es el martes a las diez."], ["j", "Muss ich etwas mitbringen?", "Moet ik iets meenemen?", "Do I need to bring anything?", "Je dois apporter quelque chose ?", "¿Tengo que traer algo?"], ["a", "Ja, bitte Ihre Versichertenkarte und den Ausweis.", "Ja, graag uw verzekeringspas en identiteitsbewijs.", "Yes, please bring your insurance card and ID.", "Oui, apportez votre carte d'assurance et votre pièce d'identité.", "Sí, traiga su tarjeta de seguro y su documento de identidad."], ["j", "Ich muss den Termin leider absagen.", "Helaas moet ik de afspraak afzeggen.", "Unfortunately I need to cancel the appointment.", "Malheureusement, je dois annuler le rendez-vous.", "Lamentablemente tengo que cancelar la cita."], ["a", "Kein Problem. Wann können Sie wieder kommen?", "Geen probleem. Wanneer kunt u weer komen?", "No problem. When can you come back?", "Pas de problème. Quand pouvez-vous revenir ?", "No hay problema. ¿Cuándo puede volver?"], ["j", "Vielleicht in zwei Wochen. Kann ich das später sagen?", "Misschien over twee weken. Kan ik dat later laten weten?", "Maybe in two weeks. Can I tell you later?", "Peut-être dans deux semaines. Je peux vous le dire plus tard ?", "Quizás en dos semanas. ¿Puedo decírselo más tarde?"], ["a", "Ja, rufen Sie einfach wieder an.", "Ja, bel gewoon weer.", "Yes, just call again.", "Oui, rappelez simplement.", "Sí, simplemente vuelva a llamar."], ["j", "Wie kann ich den Termin verschieben?", "Hoe kan ik de afspraak verzetten?", "How can I reschedule the appointment?", "Comment puis-je reporter le rendez-vous ?", "¿Cómo puedo cambiar la cita de fecha?"], ["a", "Am Telefon oder über unsere Website.", "Telefonisch of via onze website.", "By phone or through our website.", "Par téléphone ou sur notre site.", "Por teléfono o en nuestra web."], ["j", "Gut. Vielen Dank für Ihre Hilfe.", "Goed. Heel erg bedankt voor uw hulp.", "Good. Thank you very much for your help.", "Bien. Merci beaucoup pour votre aide.", "Bien. Muchas gracias por su ayuda."], ["a", "Gern geschehen. Auf Wiederhören!", "Graag gedaan. Tot ziens!", "You're welcome. Goodbye!", "Avec plaisir. Au revoir !", "De nada. ¡Hasta luego!"]], "v": {"1": [["Gern. Für wann willst du kommen?", "Graag. Wanneer wil je komen?", "Sure. When do you want to come?", "Bien sûr. Pour quand tu veux venir ?", "Claro. ¿Para cuándo quieres venir?"]], "3": [["Dienstag, entweder um zehn oder um vierzehn Uhr.", "Dinsdag, om tien uur of om twee uur 's middags.", "Tuesday, either at ten or at two.", "Mardi, à dix heures ou à quatorze heures.", "El martes, a las diez o a las dos."]], "5": [["Wie heißt du und wann bist du geboren?", "Wat is je naam en wanneer ben je geboren?", "What's your name and date of birth?", "Quel est ton nom et ta date de naissance ?", "¿Cómo te llamas y cuándo naciste?"]], "7": [["Gut, dein Termin ist Dienstag um zehn Uhr.", "Prima, je bent dinsdag om tien uur ingepland.", "Good, your appointment is Tuesday at ten.", "Très bien, ton rendez-vous est mardi à dix heures.", "Bien, tu cita es el martes a las diez."]], "9": [["Ja, bring deine Versicherungskarte und deinen Ausweis mit.", "Ja, neem je pasje van de verzekering en je ID mee.", "Yes, bring your insurance card and ID.", "Oui, prends ta carte d'assurance et ta pièce d'identité.", "Sí, trae tu tarjeta de seguro y tu documento de identidad."]], "11": [["Kein Problem. Wann kannst du wieder kommen?", "Geen probleem. Wanneer kun je weer komen?", "No problem. When can you come back?", "Pas de problème. Quand peux-tu revenir ?", "No hay problema. ¿Cuándo puedes volver?"]], "13": [["Ja, ruf einfach noch mal an.", "Ja, bel maar weer.", "Yes, just call back.", "Oui, rappelle simplement.", "Sí, simplemente vuelve a llamar."]], "15": [["Am Telefon oder über unsere Website.", "Gewoon bellen of via onze site.", "You can call or use our website.", "Par téléphone ou via notre site.", "Por teléfono o por nuestra web."]], "17": [["Gern geschehen. Tschüss!", "Graag gedaan. Doei!", "You're welcome. Bye!", "Avec plaisir. Salut !", "De nada. ¡Adiós!"]]}, "p": [["Haben Sie um [tijd] noch einen Termin frei?", "Heeft u om [tijd] nog plek?", "Do you have a slot at [tijd]?", "Vous avez encore une place à [tijd] ?", "¿Tiene hueco a las [tijd]?"]]}, {"n": 17, "t": "Openingstijden en informatie vragen", "tt": {"de": "Öffnungszeiten und Informationen erfragen", "nl": "Openingstijden en informatie vragen", "en": "Asking about opening hours and information", "fr": "Demander les horaires et des informations", "es": "Preguntar el horario y pedir información"}, "r": [["j", "Entschuldigung, wann öffnen Sie morgen?", "Excuseer, hoe laat openen jullie morgen?", "Excuse me, when do you open tomorrow?", "Excusez-moi, à quelle heure ouvrez-vous demain ?", "Perdone, ¿a qué hora abren mañana?"], ["a", "Um neun Uhr.", "Om negen uur.", "At nine o'clock.", "À neuf heures.", "A las nueve."], ["j", "Und am Sonntag?", "En op zondag?", "And on Sunday?", "Et dimanche ?", "¿Y el domingo?"], ["a", "Am Sonntag sind wir geschlossen.", "Op zondag zijn we gesloten.", "On Sunday we're closed.", "Le dimanche, nous sommes fermés.", "El domingo estamos cerrados."], ["j", "Bis wann ist heute geöffnet?", "Tot hoe laat is het vandaag open?", "Until what time are you open today?", "Vous êtes ouverts jusqu'à quelle heure aujourd'hui ?", "¿Hasta qué hora están abiertos hoy?"], ["a", "Bis achtzehn Uhr.", "Tot zes uur.", "Until six p.m.", "Jusqu'à dix-huit heures.", "Hasta las seis de la tarde."], ["j", "Gibt es hier eine Mittagspause?", "Is er hier een lunchpauze?", "Is there a lunch break?", "Il y a une pause déjeuner ?", "¿Hay pausa para comer?"], ["a", "Ja, von zwölf bis dreizehn Uhr.", "Ja, van twaalf tot één uur.", "Yes, from twelve to one.", "Oui, de midi à treize heures.", "Sí, de doce a una."], ["j", "Wie kann ich Sie erreichen, wenn es geschlossen ist?", "Hoe kan ik u bereiken als u gesloten bent?", "How can I reach you when you're closed?", "Comment peut-on vous joindre quand vous êtes fermés ?", "¿Cómo puedo contactarle si está cerrado?"], ["a", "Über die E-Mail oder die Nummer auf der Website.", "Via de e-mail of het nummer op de website.", "By email or the number on the website.", "Par e-mail ou au numéro indiqué sur le site.", "Por correo o con el número de la web."], ["j", "Haben Sie auch einen Parkplatz?", "Hebben jullie ook een parkeerplaats?", "Do you also have a parking space?", "Vous avez aussi un parking ?", "¿Tienen también aparcamiento?"], ["a", "Ja, direkt vor dem Gebäude, aber nur zwei Stunden.", "Ja, direct voor het gebouw, maar alleen twee uur.", "Yes, right in front of the building, but only for two hours.", "Oui, juste devant le bâtiment, mais seulement deux heures.", "Sí, justo delante del edificio, pero solo dos horas."], ["j", "Ist der Eingang auch rollstuhlgerecht?", "Is de ingang ook geschikt voor een rolstoel?", "Is the entrance also wheelchair accessible?", "L'entrée est-elle accessible en fauteuil roulant ?", "¿La entrada también es accesible para silla de ruedas?"], ["a", "Ja, es gibt eine Rampe an der Seite.", "Ja, aan de zijkant is een oprit.", "Yes, there's a ramp on the side.", "Oui, il y a une rampe sur le côté.", "Sí, hay una rampa en el lateral."], ["j", "Danke für die Information.", "Dank u voor de informatie.", "Thanks for the information.", "Merci pour les informations.", "Gracias por la información."], ["a", "Gern geschehen. Schönen Tag!", "Graag gedaan. Fijne dag!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]], "v": {"1": [["Ab neun Uhr.", "Vanaf negen uur.", "From nine o'clock.", "À partir de neuf heures.", "A partir de las nueve."]], "3": [["Sonntags haben wir geschlossen.", "Op zondag hebben we dicht.", "We're closed on Sundays.", "Le dimanche, c'est fermé.", "Los domingos cerramos."]], "5": [["Bis sechs Uhr abends.", "Tot zes uur 's avonds.", "Until six in the evening.", "Jusqu'à dix-huit heures.", "Hasta las seis de la tarde."]], "7": [["Ja, von zwölf bis eins.", "Ja, van twaalf tot één.", "Yes, between twelve and one.", "Oui, entre midi et treize heures.", "Sí, entre las doce y la una."]], "9": [["Per E-Mail oder unter der Nummer auf der Website.", "Stuur een mail of bel het nummer op de site.", "By email or the number on the site.", "Par mail ou au numéro sur le site.", "Por correo o al número de la web."]], "11": [["Ja, direkt vor dem Gebäude, aber maximal zwei Stunden.", "Ja, vlakbij de ingang, maar maximaal twee uur.", "Yes, right outside, but only for two hours.", "Oui, juste devant, mais deux heures maximum.", "Sí, justo delante, pero solo dos horas."]], "13": [["Ja, an der Seite gibt es eine Rampe.", "Ja, aan de zijkant is een hellingbaan.", "Yes, there's a ramp at the side.", "Oui, il y a une rampe sur le côté.", "Sí, hay una rampa a un lado."]], "15": [["Gern. Schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, "p": [["Wann öffnen Sie am [dag]?", "Hoe laat openen jullie op [dag]?", "When do you open on [dag]?", "À quelle heure ouvrez-vous [dag] ?", "¿A qué hora abren el [dag]?"]]}, {"n": 18, "t": "Bank en post", "tt": {"de": "Bank und Post", "nl": "Bank en post", "en": "Bank and post office", "fr": "Banque et poste", "es": "Banco y correos"}, "r": [["j", "Guten Tag, ich möchte ein Paket verschicken.", "Hallo, ik wil graag een pakket versturen.", "Hello, I'd like to send a parcel.", "Bonjour, je voudrais envoyer un colis.", "Hola, quisiera enviar un paquete."], ["a", "Wohin soll es gehen?", "Waar moet het naartoe?", "Where is it going?", "Vers où ?", "¿A dónde va?"], ["j", "Nach Deutschland, Berlin.", "Naar Duitsland, Berlijn.", "To Germany, Berlin.", "En Allemagne, à Berlin.", "A Alemania, a Berlín."], ["a", "Das kostet 12 Euro, mit Versicherung 15 Euro.", "Dat kost twaalf euro, met verzekering vijftien euro.", "That's twelve euros, or fifteen with insurance.", "Ça coûte douze euros, quinze avec l'assurance.", "Cuesta doce euros, o quince con seguro."], ["j", "Mit Versicherung, bitte. Wie lange dauert es?", "Met verzekering, alstublieft. Hoe lang duurt het?", "With insurance, please. How long does it take?", "Avec assurance, s'il vous plaît. Ça prend combien de temps ?", "Con seguro, por favor. ¿Cuánto tarda?"], ["a", "Etwa drei bis fünf Werktage.", "Ongeveer drie tot vijf werkdagen.", "About three to five working days.", "Environ trois à cinq jours ouvrables.", "Unos tres a cinco días laborables."], ["j", "Ich möchte auch Geld auf mein Konto einzahlen.", "Ik wil ook geld storten op mijn rekening.", "I'd also like to deposit money into my account.", "Je voudrais aussi déposer de l'argent sur mon compte.", "También quisiera ingresar dinero en mi cuenta."], ["a", "Haben Sie Ihre Bankkarte und Ihren Ausweis dabei?", "Heeft u uw bankpas en identiteitsbewijs bij u?", "Do you have your bank card and ID with you?", "Vous avez votre carte bancaire et votre pièce d'identité ?", "¿Tiene su tarjeta bancaria y su documento de identidad?"], ["j", "Ja, hier sind sie.", "Ja, hier zijn ze.", "Yes, here they are.", "Oui, les voici.", "Sí, aquí están."], ["a", "Wie viel möchten Sie einzahlen?", "Hoeveel wilt u storten?", "How much would you like to deposit?", "Combien voulez-vous déposer ?", "¿Cuánto quiere ingresar?"], ["j", "Hundert Euro, bitte.", "Honderd euro, alstublieft.", "One hundred euros, please.", "Cent euros, s'il vous plaît.", "Cien euros, por favor."], ["a", "Gut. Bitte unterschreiben Sie hier.", "Goed. Wilt u hier tekenen.", "Good. Please sign here.", "Bien. Signez ici, s'il vous plaît.", "Bien. Firme aquí, por favor."], ["j", "Kann ich auch einen Kontoauszug bekommen?", "Kan ik ook een rekeningoverzicht krijgen?", "Can I also get an account statement?", "Je peux aussi avoir un relevé de compte ?", "¿Puedo también obtener un extracto de cuenta?"], ["a", "Ja, er kommt gleich aus dem Drucker.", "Ja, die komt zo uit de printer.", "Yes, it'll come out of the printer shortly.", "Oui, il sort de l'imprimante dans un instant.", "Sí, saldrá enseguida de la impresora."], ["j", "Danke, das war sehr hilfreich.", "Dank u, dat was erg fijn.", "Thanks, that was very helpful.", "Merci, c'était très utile.", "Gracias, me ha sido muy útil."], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]], "v": {"1": [["Wohin soll das Paket denn?", "Waar gaat het pakket naartoe?", "Where's it going to?", "Il va où ?", "¿A dónde va a ir?"]], "3": [["Zwölf Euro, mit Versicherung fünfzehn.", "Twaalf euro, met verzekering vijftien.", "That's twelve, or fifteen with insurance.", "Douze euros, ou quinze avec assurance.", "Doce euros, o quince con seguro."]], "5": [["Drei bis fünf Werktage, ungefähr.", "Drie tot vijf werkdagen, ongeveer.", "Around three to five working days.", "Trois à cinq jours ouvrés, à peu près.", "Tres a cinco días hábiles, más o menos."]], "7": [["Hast du deine Bankkarte und deinen Ausweis dabei?", "Heb je je pas en identiteitsbewijs bij je?", "Have you got your bank card and ID with you?", "Tu as ta carte bancaire et ta pièce d'identité ?", "¿Tienes tu tarjeta bancaria y tu documento de identidad?"]], "9": [["Wie viel möchtest du einzahlen?", "Hoeveel ga je storten?", "How much do you want to deposit?", "Combien tu veux déposer ?", "¿Cuánto quieres ingresar?"]], "11": [["Gut. Unterschreib bitte hier.", "Goed. Wil je hier even tekenen.", "Good. Please sign here.", "Bien. Signe ici, s'il te plaît.", "Bien. Firma aquí, por favor."]], "13": [["Ja, einen Moment, er kommt gleich aus dem Drucker.", "Ja, even wachten, hij komt zo uit de printer.", "Yes, it'll be out of the printer in a moment.", "Oui, il sort tout de suite de l'imprimante.", "Sí, saldrá en un momento de la impresora."]], "15": [["Gern. Schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]]}, "p": [["Ich möchte ein Paket nach [plaats] schicken.", "Ik wil een pakket naar [plaats] sturen.", "I'd like to send a parcel to [plaats].", "Je voudrais envoyer un colis à [plaats].", "Quisiera enviar un paquete a [plaats]."]]}, {"n": 19, "t": "Noodgeval: hulp roepen en eerste hulp", "tt": {"de": "Notfall: Hilfe rufen und Erste Hilfe", "nl": "Noodgeval: hulp roepen en eerste hulp", "en": "Emergency: calling for help and first aid", "fr": "Urgence : appeler à l'aide et premiers secours", "es": "Emergencia: pedir ayuda y primeros auxilios"}, "r": [["j", "Hilfe! Bitte helfen Sie mir!", "Help! Help me alstublieft!", "Help! Please help me!", "Au secours ! Aidez-moi, s'il vous plaît !", "¡Socorro! ¡Por favor, ayúdeme!"], ["a", "Was ist passiert?", "Wat is er gebeurd?", "What happened?", "Qu'est-ce qui s'est passé ?", "¿Qué ha pasado?"], ["j", "Mein Freund ist gestürzt. Er blutet am Kopf.", "Mijn vriend is gevallen. Hij bloedt aan zijn hoofd.", "My friend fell. He's bleeding from his head.", "Mon ami est tombé. Il saigne à la tête.", "Mi amigo se ha caído. Sangra de la cabeza."], ["a", "Rufen Sie sofort den Notruf, die 112.", "Bel meteen het alarmnummer, de 112.", "Call emergency services right away, 112.", "Appelez tout de suite les urgences, le 112.", "Llame ya a emergencias, al 112."], ["j", "Ich rufe jetzt an. Wo sind wir hier?", "Ik bel nu. Waar zijn we hier?", "I'm calling now. Where are we?", "J'appelle maintenant. On est où ici ?", "Llamo ahora. ¿Dónde estamos?"], ["a", "Sagen Sie die Straße und die Hausnummer.", "Zeg de straat en het huisnummer.", "Tell them the street and the house number.", "Donnez la rue et le numéro.", "Diga la calle y el número de la casa."], ["j", "Wir sind in der Hauptstraße, Nummer dreizehn.", "We zijn op de hoofdstraat, nummer dertien.", "We're on the main street, number thirteen.", "Nous sommes dans la rue principale, numéro treize.", "Estamos en la calle principal, número trece."], ["a", "Legen Sie ihn hin und halten Sie den Kopf still.", "Leg hem neer en houd zijn hoofd stil.", "Lay him down and keep his head still.", "Allongez-le et gardez la tête immobile.", "Acuéstelo y mantenga la cabeza quieta."], ["j", "Er ist wach, aber er ist sehr blass.", "Hij is wakker, maar hij is erg bleek.", "He's awake, but he's very pale.", "Il est conscient, mais il est très pâle.", "Está consciente, pero está muy pálido."], ["a", "Decken Sie ihn zu, damit er nicht auskühlt.", "Dek hem toe, zodat hij niet afkoelt.", "Cover him so he doesn't get cold.", "Couvrez-le pour éviter qu'il ne refroidisse.", "Cúbralo para que no se enfríe."], ["j", "Soll ich ihm Wasser geben?", "Moet ik hem water geven?", "Should I give him water?", "Je peux lui donner de l'eau ?", "¿Le doy agua?"], ["a", "Nein, nichts zu trinken, bis der Rettungsdienst da ist.", "Nee, niets te drinken tot de ambulance er is.", "No, nothing to drink until the ambulance arrives.", "Non, rien à boire avant l'arrivée des secours.", "No, nada de beber hasta que llegue la ambulancia."], ["j", "Die Sanitäter kommen gleich. Danke!", "De ambulance komt er zo aan. Dank u!", "The paramedics are coming now. Thanks!", "Les secours arrivent. Merci !", "Ya vienen los paramédicos. ¡Gracias!"], ["a", "Gut. Bleiben Sie bei ihm und sprechen Sie mit ihm.", "Goed. Blijf bij hem en praat met hem.", "Good. Stay with him and keep talking to him.", "Bien. Restez avec lui et parlez-lui.", "Bien. Quédese con él y hable con él."], ["j", "Ich bleibe hier. Alles wird gut.", "Ik blijf hier. Het komt goed.", "I'm staying here. It'll be alright.", "Je reste ici. Tout va bien aller.", "Me quedo aquí. Todo va a salir bien."], ["a", "Danke. Wir sind sehr froh, dass Sie geholfen haben.", "Dank u. We zijn blij dat u hebt geholpen.", "Thank you. We're very glad you helped.", "Merci. Nous sommes très reconnaissants de votre aide.", "Gracias. Nos alegra mucho que haya ayudado."]], "v": {"1": [["Was ist los?", "Wat is er aan de hand?", "What's going on?", "Qu'est-ce qui se passe ?", "¿Qué pasa?"]], "3": [["Ruf sofort die 112 an.", "Bel nu meteen 112.", "Call 112 right now.", "Appelle tout de suite le 112.", "Llama ya al 112."]], "5": [["Sag die Straße und die Hausnummer, schnell.", "Geef de straatnaam en het huisnummer door.", "Tell them the street and the house number.", "Donne la rue et le numéro.", "Dígales la calle y el número."]], "7": [["Leg ihn flach hin und halt den Kopf ruhig.", "Leg hem plat en houd zijn hoofd stil.", "Lay him down and keep his head still.", "Allonge-le et garde sa tête immobile.", "Acuéstalo y mantén la cabeza quieta."]], "9": [["Deck ihn zu, dann kühlt er nicht aus.", "Doe een deken over hem heen.", "Cover him up so he doesn't get cold.", "Couvre-le, qu'il ne refroidisse pas.", "Tápalo para que no se enfríe."]], "11": [["Nein, nichts zu trinken, bis der Krankenwagen da ist.", "Nee, niks te drinken tot de ambulance er is.", "No, nothing to drink until the ambulance comes.", "Non, rien à boire avant l'ambulance.", "No, nada de beber hasta que llegue la ambulancia."]], "13": [["Gut. Bleib bei ihm und sprich mit ihm.", "Mooi. Blijf bij hem en blijf tegen hem praten.", "Good. Stay with him and keep talking.", "Bien. Reste avec lui et parle-lui.", "Bien. Quédate con él y háblale."]], "15": [["Danke dir. Schön, dass du geholfen hast.", "Dank je. Fijn dat je er was.", "Thanks. Glad you were here to help.", "Merci. Heureusement que tu étais là.", "Gracias. Menos mal que estabas aquí."]]}, "p": [["Wir sind in [plaats].", "We zijn in [plaats].", "We're in [plaats].", "Nous sommes à [plaats].", "Estamos en [plaats]."]]}, {"n": 20, "t": "Politie en verloren spullen", "tt": {"de": "Polizei und verlorene Sachen", "nl": "Politie en verloren spullen", "en": "Police and lost property", "fr": "Police et objets perdus", "es": "Policía y objetos perdidos"}, "r": [["j", "Entschuldigung, ich habe meine Tasche verloren.", "Excuseer, ik ben mijn tas kwijt.", "Excuse me, I've lost my bag.", "Excusez-moi, j'ai perdu mon sac.", "Perdone, he perdido mi bolso."], ["a", "Wann und wo haben Sie sie verloren?", "Wanneer en waar bent u hem kwijtgeraakt?", "When and where did you lose it?", "Quand et où l'avez-vous perdu ?", "¿Cuándo y dónde lo perdió?"], ["j", "Heute Morgen, im Bus Nummer vier.", "Vanochtend, in bus vier.", "This morning, on bus number four.", "Ce matin, dans le bus numéro quatre.", "Esta mañana, en el autobús número cuatro."], ["a", "Wie sieht die Tasche aus?", "Hoe ziet de tas eruit?", "What does the bag look like?", "À quoi ressemble le sac ?", "¿Cómo es el bolso?"], ["j", "Sie ist braun, aus Leder, mit einem roten Schlüsselanhänger.", "Hij is bruin, van leer, met een rode sleutelhanger.", "It's brown, made of leather, with a red keyring.", "Il est marron, en cuir, avec un porte-clés rouge.", "Es marrón, de piel, con un llavero rojo."], ["a", "Ich schaue im Fundbüro nach. Füllen Sie bitte dieses Formular aus.", "Ik kijk in de gevonden voorwerpen. Vul dit formulier in.", "I'll check the lost property office. Please fill in this form.", "Je vais vérifier au bureau des objets trouvés. Remplissez ce formulaire.", "Miro en objetos perdidos. Rellene este formulario."], ["j", "Was muss ich hier eintragen?", "Wat moet ik hier invullen?", "What do I need to write here?", "Qu'est-ce que je dois écrire ici ?", "¿Qué tengo que poner aquí?"], ["a", "Ihren Namen, Ihre Adresse und eine Telefonnummer.", "Uw naam, adres en telefoonnummer.", "Your name, address and a phone number.", "Votre nom, votre adresse et un numéro de téléphone.", "Su nombre, su dirección y un número de teléfono."], ["j", "Ist in der Tasche etwas Wichtiges? Ein Ausweis?", "Zit er iets belangrijks in de tas? Een identiteitsbewijs?", "Is there anything important in the bag? An ID?", "Il y a quelque chose d'important dedans ? Une pièce d'identité ?", "¿Hay algo importante dentro? ¿Un documento de identidad?"], ["a", "Ja, und Sie müssen auch eine Anzeige bei der Polizei machen.", "Ja, en u moet ook aangifte doen bij de politie.", "Yes, and you also have to report it to the police.", "Oui, et vous devez aussi faire une déclaration à la police.", "Sí, y también tiene que presentar una denuncia en la policía."], ["j", "Wo ist die nächste Polizeistation?", "Waar is het dichtstbijzijnde politiebureau?", "Where is the nearest police station?", "Où est le commissariat le plus proche ?", "¿Dónde está la comisaría más cercana?"], ["a", "Gleich um die Ecke, in der Hauptstraße.", "Vlakbij, op de hoofdstraat.", "Just around the corner, on the main street.", "Juste au coin, dans la rue principale.", "A la vuelta de la esquina, en la calle principal."], ["j", "Kann ich die Anzeige online machen?", "Kan ik de aangifte ook online doen?", "Can I report it online?", "Je peux faire la déclaration en ligne ?", "¿Puedo presentar la denuncia en línea?"], ["a", "Ja, auf der Website der Polizei, mit Ihrer Nummer.", "Ja, op de website van de politie, met uw nummer.", "Yes, on the police website, with your reference number.", "Oui, sur le site de la police, avec votre numéro.", "Sí, en la web de la policía, con su número."], ["j", "Danke, Sie haben mir sehr geholfen.", "Dank u, u hebt me erg geholpen.", "Thanks, you've been very helpful.", "Merci, vous m'avez beaucoup aidé.", "Gracias, me ha ayudado mucho."], ["a", "Viel Glück! Ich hoffe, Sie finden die Tasche.", "Veel succes! Ik hoop dat u de tas vindt.", "Good luck! I hope you find the bag.", "Bonne chance ! J'espère que vous retrouverez le sac.", "¡Mucha suerte! Espero que encuentre el bolso."]], "v": {"1": [["Wann und wo hast du ihn verloren?", "Wanneer en waar is hij weg?", "When and where did you lose it?", "Quand et où tu l'as perdu ?", "¿Cuándo y dónde lo perdiste?"]], "3": [["Wie sieht er aus?", "Hoe ziet hij eruit?", "What's the bag like?", "À quoi il ressemble ?", "¿Cómo es?"]], "5": [["Ich schaue im Fundbüro nach. Füll das kurz aus.", "Ik check de gevonden voorwerpen. Vul dit even in.", "I'll check lost property. Fill in this form, please.", "Je regarde aux objets trouvés. Remplis ce formulaire.", "Miro en objetos perdidos. Rellene este formulario, por favor."]], "7": [["Dein Name, deine Adresse und eine Telefonnummer.", "Je naam, adres en telefoonnummer.", "Your name, address and a phone number.", "Ton nom, ton adresse et un numéro de téléphone.", "Tu nombre, tu dirección y un número de teléfono."]], "9": [["Ja, und du musst auch Anzeige erstatten.", "Ja, en je moet ook even aangifte doen.", "Yes, and you also need to report it to the police.", "Oui, et tu dois aussi faire une déclaration.", "Sí, y también tienes que poner una denuncia."]], "11": [["Gleich um die Ecke, auf der Hauptstraße.", "Gewoon om de hoek, op de hoofdstraat.", "Just round the corner, on the main street.", "Juste au coin de la rue principale.", "Justo a la vuelta, en la calle principal."]], "13": [["Ja, über die Website der Polizei, mit deiner Nummer.", "Ja, via de website van de politie, met je nummer.", "Yes, through the police website, with your reference number.", "Oui, via le site de la police, avec ton numéro.", "Sí, a través de la web de la policía, con tu número."]], "15": [["Viel Glück! Ich hoffe, du findest sie wieder.", "Veel geluk! Hopelijk vind je hem.", "Good luck! I hope you find it.", "Bonne chance ! J'espère que tu le retrouveras.", "¡Mucha suerte! Espero que lo encuentres."]]}}, {"n": 21, "t": "Telefoon en internet: storing melden", "tt": {"de": "Telefon und Internet: Störung melden", "nl": "Telefoon en internet: storing melden", "en": "Phone and internet: reporting a fault", "fr": "Téléphone et internet : signaler une panne", "es": "Teléfono e internet: avisar de una avería"}, "r": [["j", "Guten Tag, mein Internet funktioniert nicht.", "Hallo, mijn internet werkt niet.", "Hello, my internet isn't working.", "Bonjour, mon internet ne fonctionne pas.", "Hola, mi internet no funciona."], ["a", "Seit wann haben Sie das Problem?", "Sinds wanneer heeft u dit probleem?", "Since when have you had this problem?", "Depuis quand avez-vous ce problème ?", "¿Desde cuándo tiene este problema?"], ["j", "Seit heute Morgen. Die Lampe am Router blinkt rot.", "Sinds vanmorgen. Het lampje van de router knippert rood.", "Since this morning. The light on the router is blinking red.", "Depuis ce matin. Le voyant du routeur clignote en rouge.", "Desde esta mañana. La luz del router parpadea en rojo."], ["a", "Haben Sie den Router schon einmal neu gestartet?", "Heeft u de router al eens opnieuw opgestart?", "Have you restarted the router yet?", "Vous avez déjà redémarré le routeur ?", "¿Ya ha reiniciado el router?"], ["j", "Ja, zweimal. Es hat nichts geholfen.", "Ja, twee keer. Het heeft niets geholpen.", "Yes, twice. It didn't help.", "Oui, deux fois. Ça n'a rien changé.", "Sí, dos veces. No ha servido de nada."], ["a", "Dann melden wir die Störung. Wie ist Ihre Kundennummer?", "Dan melden we de storing. Wat is uw klantnummer?", "Then we'll report the outage. What's your customer number?", "Alors nous signalons la panne. Quel est votre numéro client ?", "Entonces registramos la avería. ¿Cuál es su número de cliente?"], ["j", "Die Nummer ist auf dem Vertrag. Ich suche sie kurz.", "Het nummer staat op het contract. Ik zoek het even op.", "The number is on the contract. Let me look it up.", "Le numéro est sur le contrat. Je le cherche.", "El número está en el contrato. Lo busco un momento."], ["a", "Kein Problem, nehmen Sie sich Zeit.", "Geen probleem, neem de tijd.", "No problem, take your time.", "Pas de problème, prenez votre temps.", "No hay problema, tómese su tiempo."], ["j", "Hier ist die Nummer: vierzehn sieben zwei.", "Hier is het nummer: veertien zeven twee.", "Here's the number: fourteen seven two.", "Voici le numéro : quatorze, sept, deux.", "Aquí está el número: catorce siete dos."], ["a", "Danke. Wann können Sie einen Techniker empfangen?", "Dank u. Wanneer bent u thuis voor een monteur?", "Thanks. When are you available for a technician?", "Merci. Quand êtes-vous disponible pour un technicien ?", "Gracias. ¿Cuándo puede recibir a un técnico?"], ["j", "Am Donnerstag zwischen acht und zwölf Uhr.", "Donderdag tussen acht en twaalf uur.", "On Thursday between eight and twelve.", "Jeudi entre huit heures et midi.", "El jueves entre las ocho y las doce."], ["a", "Gut, der Techniker kommt am Donnerstag.", "Goed, de monteur komt donderdag.", "Good, the technician will come on Thursday.", "Très bien, le technicien viendra jeudi.", "Bien, el técnico vendrá el jueves."], ["j", "Kostet das etwas?", "Kost dat iets?", "Does that cost anything?", "Ça coûte quelque chose ?", "¿Cuesta algo?"], ["a", "Nein, wenn es ein Problem bei uns ist, ist es kostenlos.", "Nee, als het aan onze kant ligt, is het gratis.", "No, if the problem is on our side, it's free.", "Non, si le problème vient de chez nous, c'est gratuit.", "No, si el problema es nuestro, es gratis."], ["j", "Und kann ich bis dahin mein Handy als Hotspot nutzen?", "Kan ik tot die tijd mijn telefoon als hotspot gebruiken?", "Until then, can I use my phone as a hotspot?", "En attendant, je peux utiliser mon téléphone comme point d'accès ?", "Mientras tanto, ¿puedo usar el móvil como punto de acceso?"], ["a", "Ja, das geht. Schalten Sie die Funktion in den Einstellungen ein.", "Ja, dat kan. Zet de functie aan in de instellingen.", "Yes, that works. Turn the feature on in the settings.", "Oui, c'est possible. Activez la fonction dans les paramètres.", "Sí, eso funciona. Actívelo en los ajustes."], ["j", "Danke, Sie haben mir sehr geholfen. Auf Wiederhören!", "Dank u, u hebt me erg geholpen. Tot ziens!", "Thanks, you've been very helpful. Goodbye!", "Merci, vous m'avez beaucoup aidé. Au revoir !", "Gracias, me ha ayudado mucho. ¡Adiós!"], ["a", "Gern geschehen. Einen schönen Tag noch!", "Graag gedaan. Fijne dag nog!", "You're welcome. Have a nice day!", "Avec plaisir. Bonne journée !", "De nada. ¡Que tenga buen día!"]], "v": {"1": [["Seit wann hast du das Problem?", "Sinds wanneer heb je dit probleem?", "Since when have you had this problem?", "Depuis quand as-tu ce problème ?", "¿Desde cuándo tienes este problema?"]], "3": [["Hast du den Router schon mal neu gestartet?", "Heb je de router al eens opnieuw opgestart?", "Have you restarted the router yet?", "Tu as déjà redémarré le routeur ?", "¿Ya has reiniciado el router?"]], "5": [["Dann melden wir die Störung. Wie lautet deine Kundennummer?", "Dan melden we het. Wat is je klantnummer?", "Then we'll report the outage. What's your customer number?", "Alors on signale la panne. Quel est ton numéro client ?", "Entonces registramos la avería. ¿Cuál es tu número de cliente?"]], "7": [["Kein Problem, nimm dir Zeit.", "Geen probleem, neem gerust de tijd.", "No problem, take your time.", "Pas de problème, prends ton temps.", "No hay problema, tómate tu tiempo."]], "9": [["Danke. Wann bist du für den Techniker zu Hause?", "Dank je. Wanneer kun je een monteur ontvangen?", "Thanks. When can you have a technician visit?", "Merci. Quand peux-tu recevoir un technicien ?", "Gracias. ¿Cuándo puedes recibir a un técnico?"]], "11": [["Gut, dann kommt der Techniker am Donnerstag.", "Goed, dan komt de monteur donderdag.", "Great, the technician comes on Thursday.", "Très bien, le technicien vient jeudi.", "Bien, el técnico viene el jueves."]], "13": [["Nein, wenn es an uns liegt, ist es kostenlos.", "Nee, als het aan ons ligt, kost het niets.", "No, if it's on our end, it's free.", "Non, si c'est de notre côté, c'est gratuit.", "No, si el fallo es nuestro, es gratis."]], "15": [["Ja, das geht. Schalte die Funktion in den Einstellungen ein.", "Ja, dat kan prima. Zet de hotspot aan in de instellingen.", "Yes, that works. Switch it on in the settings.", "Oui, ça marche. Active la fonction dans les réglages.", "Sí, eso funciona. Actívalo en los ajustes."]], "17": [["Gern geschehen. Schönen Tag!", "Graag gedaan. Fijne dag!", "You're welcome. Goodbye!", "Avec plaisir. Au revoir !", "De nada. ¡Adiós!"]]}, "p": [["Der Techniker kann am [dag] kommen.", "De monteur kan [dag] komen.", "The technician can come on [dag].", "Le technicien peut venir [dag].", "El técnico puede venir el [dag]."]]}, {"n": 22, "t": "Werk en school: collega's en docent", "tt": {"de": "Arbeit und Schule: Kollegen und Lehrer", "nl": "Werk en school: collega's en docent", "en": "Work and school: colleagues and teacher", "fr": "Travail et école : collègues et professeur", "es": "Trabajo y escuela: compañeros y profesor"}, "r": [["j", "Guten Morgen, hast du kurz Zeit?", "Goedemorgen, heb je even tijd?", "Good morning, do you have a minute?", "Bonjour, tu as un moment ?", "Buenos días, ¿tienes un momento?"], ["a", "Ja, klar. Was gibt es?", "Ja, natuurlijk. Wat is er?", "Yes, sure. What's up?", "Oui, bien sûr. Qu'est-ce qu'il y a ?", "Sí, claro. ¿Qué pasa?"], ["j", "Ich wollte die Planung für nächste Woche besprechen.", "Ik wilde de planning voor volgende week bespreken.", "I wanted to discuss the schedule for next week.", "Je voulais parler du planning de la semaine prochaine.", "Quería hablar de la planificación de la semana que viene."], ["a", "Gut. Ich habe um elf Uhr Zeit.", "Goed. Ik heb om elf uur tijd.", "Good. I have time at eleven.", "Très bien. J'ai du temps à onze heures.", "Bien. Tengo tiempo a las once."], ["j", "Passt das für dich?", "Past dat voor jou?", "Does that work for you?", "Ça te convient ?", "¿Te viene bien?"], ["a", "Ja, perfekt. Bis dann.", "Ja, prima. Tot dan.", "Yes, perfect. See you then.", "Oui, parfait. À tout à l'heure.", "Sí, perfecto. Hasta entonces."], ["j", "Entschuldigung, ich bin heute zu spät. Der Bus hatte Verspätung.", "Sorry, ik ben vandaag te laat. De bus had vertraging.", "Sorry, I'm late today. The bus was delayed.", "Désolé, je suis en retard aujourd'hui. Le bus avait du retard.", "Perdona, llego tarde hoy. El autobús iba con retraso."], ["a", "Kein Problem. Kannst du das bitte im System eintragen?", "Geen probleem. Kun je dat even in het systeem zetten?", "No problem. Can you log it in the system, please?", "Pas de problème. Tu peux l'enregistrer dans le système ?", "No pasa nada. ¿Puedes registrarlo en el sistema?"], ["j", "Mache ich. Wer macht heute die Post?", "Doe ik. Wie doet vandaag de post?", "Will do. Who's doing the post today?", "Je le fais. Qui s'occupe du courrier aujourd'hui ?", "Lo hago. ¿Quién se encarga hoy del correo?"], ["a", "Das macht Lisa. Frag sie einfach.", "Dat doet Lisa. Vraag het haar gewoon.", "Lisa is. Just ask her.", "C'est Lisa. Demande-lui simplement.", "Lo hace Lisa. Pregúntale sin más."], ["j", "Okay, danke. Könntest du mir den Ordner geben?", "Oké, dank je. Kun je me de map geven?", "Okay, thanks. Could you give me the folder?", "D'accord, merci. Tu peux me donner le dossier ?", "Vale, gracias. ¿Me darías la carpeta?"], ["a", "Hier bitte. Die Unterlagen sind vollständig.", "Alsjeblieft. De stukken zijn compleet.", "Here you go. The documents are complete.", "Voilà. Les documents sont complets.", "Aquí tienes. Los documentos están completos."], ["j", "Super, danke dir. Wann ist die Besprechung?", "Super, bedankt. Wanneer is de vergadering?", "Great, thanks. When is the meeting?", "Super, merci. Quand est la réunion ?", "Genial, gracias. ¿Cuándo es la reunión?"], ["a", "Morgen um zehn Uhr im Konferenzraum.", "Morgen om tien uur in de vergaderzaal.", "Tomorrow at ten in the meeting room.", "Demain à dix heures dans la salle de réunion.", "Mañana a las diez en la sala de reuniones."], ["j", "Ich komme. Danke für die Info!", "Ik kom. Bedankt voor de info!", "I'll be there. Thanks for the info!", "J'y serai. Merci pour l'info !", "Allí estaré. ¡Gracias por la información!"], ["a", "Super. Bis morgen!", "Top. Tot morgen!", "Great. See you tomorrow!", "Super. À demain !", "Genial. ¡Hasta mañana!"]], "v": {"1": [["Ja, klar. Worum geht's?", "Ja hoor. Waar gaat het over?", "Yes, sure. What's up?", "Oui, bien sûr. Qu'est-ce qui se passe ?", "Sí, claro. ¿Qué pasa?"]], "3": [["Prima. Ich habe um elf Uhr Zeit.", "Oké. Om elf uur heb ik tijd.", "Great. I've got time at eleven.", "Très bien. J'ai du temps à onze heures.", "Vale. Tengo tiempo a las once."]], "5": [["Ja, perfekt. Bis dann.", "Ja, perfect. Tot dan.", "Yes, perfect. See you then.", "Oui, parfait. À tout à l'heure.", "Sí, perfecto. Hasta luego."]], "7": [["Kein Problem. Können Sie das kurz registrieren?", "Geen zorgen. Zet u het even in het systeem?", "No worries. Could you log it in the system?", "Pas de souci. Pouvez-vous l'enregistrer ?", "No pasa nada. ¿Puede anotarlo en el sistema?"]], "9": [["Lisa macht das. Frag sie einfach.", "Dat is Lisa. Vraag het haar maar.", "Lisa's doing it. Just ask her.", "C'est Lisa. Demande-lui tout simplement.", "Lo hace Lisa. Pregúntaselo sin problema."]], "11": [["Hier. Die Unterlagen sind vollständig.", "Alsjeblieft. Alles zit erin.", "Here you go. Everything's in there.", "Voilà. Tout est là.", "Aquí tienes. Está todo."]], "13": [["Morgen um zehn. Im großen Besprechungsraum.", "Morgen om tien uur. In de grote vergaderzaal.", "Tomorrow at ten, in the meeting room.", "Demain à dix heures, dans la salle de réunion.", "Mañana a las diez, en la sala de reuniones."]], "15": [["Gut. Bis morgen.", "Prima. Tot morgen.", "Great. See you tomorrow!", "Super. À demain !", "Genial. ¡Hasta mañana!"]]}, "p": [["Können wir die Besprechung um [tijd] machen?", "Kunnen we om [tijd] de vergadering houden?", "Can we hold the meeting at [tijd]?", "On peut faire la réunion à [tijd] ?", "¿Podemos hacer la reunión a las [tijd]?"]]}, {"n": 23, "t": "Wonen: buren en huur", "tt": {"de": "Wohnen: Nachbarn und Miete", "nl": "Wonen: buren en huur", "en": "Living: neighbours and rent", "fr": "Logement : voisins et loyer", "es": "Vivienda: vecinos y alquiler"}, "r": [["j", "Hallo, ich wohne nebenan. Ich wollte mich vorstellen.", "Hoi, ik woon hiernaast. Ik wilde me even voorstellen.", "Hi, I live next door. I wanted to introduce myself.", "Bonjour, j'habite à côté. Je voulais me présenter.", "Hola, vivo al lado. Quería presentarme."], ["a", "Oh, schön, Sie kennenzulernen. Ich bin Frau Krause.", "Oh, leuk u te ontmoeten. Ik ben mevrouw Krause.", "Oh, nice to meet you. I'm Mrs Krause.", "Oh, enchanté. Je suis Madame Krause.", "Qué bien conocerle. Soy la señora Krause."], ["j", "Ich bin Anna. Wir sind erst seit einer Woche hier.", "Ik ben Anna. We wonen hier pas een week.", "I'm Anna. We've only been here a week.", "Je suis Anna. Nous ne sommes là que depuis une semaine.", "Soy Anna. Solo llevamos aquí una semana."], ["a", "Herzlich willkommen! Wenn Sie etwas brauchen, sagen Sie Bescheid.", "Welkom! Als u iets nodig hebt, laat het gerust weten.", "Welcome! If you need anything, just let me know.", "Bienvenue ! Si vous avez besoin de quoi que ce soit, dites-le-moi.", "¡Bienvenidos! Si necesitan algo, avísenme."], ["j", "Danke. Wissen Sie, wann der Müll abgeholt wird?", "Dank u. Weet u wanneer de vuilnis wordt opgehaald?", "Thanks. Do you know when the rubbish is collected?", "Merci. Vous savez quand les poubelles sont ramassées ?", "Gracias. ¿Sabe cuándo recogen la basura?"], ["a", "Dienstags und freitags, am frühen Morgen.", "Dinsdag en vrijdag, vroeg in de ochtend.", "Tuesdays and Fridays, early in the morning.", "Le mardi et le vendredi, tôt le matin.", "Los martes y viernes, por la mañana temprano."], ["j", "Und wo sind die Fahrräder abgestellt?", "En waar kan ik de fietsen neerzetten?", "And where can bicycles be parked?", "Et où peut-on garer les vélos ?", "¿Y dónde se pueden aparcar las bicis?"], ["a", "Im Hof, hinter dem Haus.", "In de binnenplaats, achter het huis.", "In the courtyard, behind the house.", "Dans la cour, derrière la maison.", "En el patio, detrás de la casa."], ["j", "Gibt es Probleme mit Lärm? Ich habe einen Hund.", "Is er vaak last van lawaai? Ik heb een hond.", "Is there a problem with noise? I have a dog.", "Il y a des problèmes de bruit ? J'ai un chien.", "¿Hay problemas con el ruido? Tengo un perro."], ["a", "Nein, kein Problem. Wir haben auch Hunde im Haus.", "Nee, geen probleem. We hebben ook honden in het huis.", "No, no problem. We have dogs in the building too.", "Non, aucun problème. Nous avons aussi des chiens dans l'immeuble.", "No, ningún problema. También hay perros en el edificio."], ["j", "Ich bin mit der Heizung unsicher. Wie funktioniert sie?", "Ik weet niet zo goed hoe de verwarming werkt. Hoe werkt die?", "I'm not sure how the heating works. How does it work?", "Je ne sais pas très bien comment marche le chauffage. Comment ça marche ?", "No sé bien cómo funciona la calefacción. ¿Cómo funciona?"], ["a", "Am Thermostat im Flur. Ich zeige es Ihnen gern.", "Bij de thermostaat in de gang. Ik laat het u graag zien.", "On the thermostat in the hall. I'm happy to show you.", "Sur le thermostat dans le couloir. Je vous montre volontiers.", "En el termostato del pasillo. Con gusto se lo enseño."], ["j", "Das wäre super. Danke!", "Dat zou fijn zijn. Dank u!", "That would be great. Thanks!", "Ce serait super. Merci !", "Sería genial. ¡Gracias!"], ["a", "Gern. Wir sehen uns bestimmt wieder.", "Graag. We zien elkaar vast nog wel.", "Gladly. We'll see each other again for sure.", "Avec plaisir. On se reverra sûrement.", "Con gusto. Seguro que nos volvemos a ver."]], "v": {"1": [["Oh, schön, dich kennenzulernen. Ich bin Frau Krause.", "Oh, leuk je te ontmoeten. Ik ben Krause.", "Oh, nice to meet you. I'm Mrs Krause.", "Oh, enchantée. Je suis Madame Krause.", "Qué bien conocerte. Soy la señora Krause."]], "3": [["Willkommen! Wenn du etwas brauchst, sag einfach Bescheid.", "Welkom! Als je iets nodig hebt, zeg het gerust.", "Welcome! If you need anything, just let me know.", "Bienvenue ! Si tu as besoin de quoi que ce soit, dis-le-moi.", "¡Bienvenidos! Si necesitas algo, avísame."]], "5": [["Dienstags und freitags, früh am Morgen.", "Op dinsdag en vrijdag, 's ochtends vroeg.", "On Tuesdays and Fridays, early in the morning.", "Le mardi et le vendredi, tôt le matin.", "Los martes y viernes, temprano por la mañana."]], "7": [["Hinter dem Haus, auf dem Innenhof.", "Gewoon achter het huis, in de binnenplaats.", "Behind the house, in the courtyard.", "Derrière la maison, dans la cour.", "Detrás de la casa, en el patio."]], "9": [["Nein, kein Problem. Hier gibt es noch mehr Hunde.", "Nee hoor. Hier wonen ook honden.", "No, no problem. There are other dogs here too.", "Non, pas de problème. Il y a d'autres chiens ici.", "No, ningún problema. Hay más perros aquí."]], "11": [["Beim Thermostat im Flur. Ich zeige es dir.", "Die zit in de gang. Ik laat het je graag zien.", "On the thermostat in the hall. I'll show you.", "Sur le thermostat du couloir. Je te montre.", "En el termostato del pasillo. Te lo enseño."]], "13": [["Gern. Wir sehen uns sicher noch.", "Graag. We zien elkaar vast nog.", "Sure. We'll see each other again.", "Avec plaisir. On se reverra.", "Con gusto. Seguro que nos vemos otra vez."]]}}, {"n": 24, "t": "Uitnodiging en verjaardag", "tt": {"de": "Einladung und Geburtstag", "nl": "Uitnodiging en verjaardag", "en": "Invitation and birthday", "fr": "Invitation et anniversaire", "es": "Invitación y cumpleaños"}, "r": [["j", "Hast du am Samstag Zeit? Ich feiere meinen Geburtstag.", "Heb je zaterdag tijd? Ik vier mijn verjaardag.", "Are you free on Saturday? I'm celebrating my birthday.", "Tu es libre samedi ? Je fête mon anniversaire.", "¿Tienes tiempo el sábado? Celebro mi cumpleaños."], ["a", "Ja, gern! Wann fängt es an?", "Ja, graag! Hoe laat begint het?", "Yes, I'd love to! What time does it start?", "Oui, avec plaisir ! À quelle heure ça commence ?", "¡Sí, encantado! ¿A qué hora empieza?"], ["j", "Um neunzehn Uhr, bei mir zu Hause.", "Om zeven uur, bij mij thuis.", "At seven in the evening, at my place.", "À dix-neuf heures, chez moi.", "A las siete de la tarde, en mi casa."], ["a", "Super! Soll ich etwas mitbringen?", "Super! Moet ik iets meenemen?", "Great! Should I bring something?", "Super ! Je dois apporter quelque chose ?", "¡Genial! ¿Tengo que llevar algo?"], ["j", "Ein paar Getränke wären toll. Ich mache das Essen.", "Een paar drankjes zou fijn zijn. Ik maak het eten.", "A few drinks would be great. I'm making the food.", "Quelques boissons seraient parfaites. Je m'occupe de la nourriture.", "Algunas bebidas estarían bien. Yo me encargo de la comida."], ["a", "Alles klar. Ich bringe Wein mit.", "Goed. Ik neem wijn mee.", "Got it. I'll bring some wine.", "D'accord. J'apporte du vin.", "Vale. Llevaré vino."], ["j", "Danke! Ich freue mich, dass du kommst.", "Dank je! Ik ben blij dat je komt.", "Thanks! I'm glad you're coming.", "Merci ! Je suis contente que tu viennes.", "¡Gracias! Me alegra que vengas."], ["a", "Herzlichen Glückwunsch nachträglich! Ich freue mich auch.", "Alvast gefeliciteerd! Ik kijk ernaar uit.", "Happy birthday in advance! I'm looking forward to it.", "Joyeux anniversaire d'avance ! J'ai hâte.", "¡Feliz cumpleaños por adelantado! Tengo ganas."], ["j", "Kannst du noch Freunde mitbringen?", "Mag je nog vrienden meenemen?", "Can you bring some friends too?", "Tu peux amener des amis ?", "¿Puedes traer amigos también?"], ["a", "Ja, klar. Wie viele Leute kommen ungefähr?", "Ja, natuurlijk. Hoeveel mensen komen er ongeveer?", "Yes, of course. How many people are coming roughly?", "Oui, bien sûr. Il y aura environ combien de personnes ?", "Sí, claro. ¿Más o menos cuántas personas vendrán?"], ["j", "Etwa zehn Leute. Das Haus ist nicht sehr groß.", "Ongeveer tien mensen. Het huis is niet zo groot.", "About ten people. The house isn't very big.", "Une dizaine de personnes. La maison n'est pas très grande.", "Unas diez personas. La casa no es muy grande."], ["a", "Kein Problem, wir kommen pünktlich.", "Geen probleem, we komen op tijd.", "No problem, we'll be on time.", "Pas de problème, nous arriverons à l'heure.", "No hay problema, llegaremos puntuales."], ["j", "Super, bis Samstag!", "Super, tot zaterdag!", "Great, see you Saturday!", "Super, à samedi !", "¡Genial, hasta el sábado!"], ["a", "Bis Samstag! Schönen Abend noch.", "Tot zaterdag! Fijne avond nog.", "See you Saturday! Have a good evening.", "À samedi ! Bonne soirée.", "¡Hasta el sábado! Que tengas buena tarde."]], "v": {"0": [["Haben Sie am Samstag Zeit? Ich feiere meinen Geburtstag.", "Heeft u zaterdag tijd? Ik vier mijn verjaardag.", "Are you free on Saturday? I'm celebrating my birthday.", "Vous êtes libre samedi ? Je fête mon anniversaire.", "¿Tiene tiempo el sábado? Celebro mi cumpleaños."]], "1": [["Ja, super! Wann fängt es an?", "Ja, leuk! Hoe laat is het?", "Yes, sounds great! What time does it start?", "Oui, super ! Ça commence à quelle heure ?", "¡Sí, genial! ¿A qué hora empieza?"]], "3": [["Toll! Soll ich etwas mitbringen?", "Mooi! Wil je dat ik iets meeneem?", "Great! Shall I bring something?", "Super ! Tu veux que j'apporte quelque chose ?", "¡Genial! ¿Llevo algo?"]], "5": [["Okay. Ich bringe Wein mit.", "Prima. Ik zorg voor wijn.", "Okay. I'll bring some wine.", "D'accord. J'amène du vin.", "Vale. Llevo vino."]], "7": [["Schon mal herzlichen Glückwunsch! Ich freue mich schon.", "Alvast een fijne verjaardag! Ik heb er zin in.", "Happy birthday in advance! Can't wait.", "Bon anniversaire d'avance ! J'ai hâte.", "¡Feliz cumpleaños por adelantado! Qué ganas."]], "9": [["Ja, tuurlijk. Hoeveel mensen komen er ongeveer?", "Ja hoor. Hoeveel komen er ongeveer?", "Sure. Roughly how many people are coming?", "Oui, bien sûr. Ça fait à peu près combien de personnes ?", "Sí, claro. ¿Más o menos cuántos vienen?"]], "11": [["Keine Sorge, wir sind pünktlich.", "Prima, we komen op tijd.", "No worries, we'll be on time.", "Pas de souci, on sera à l'heure.", "No pasa nada, llegaremos a tiempo."]], "13": [["Bis Samstag! Bis dann.", "Tot zaterdag! Tot dan.", "See you Saturday! Have a good evening.", "À samedi ! Bonne soirée.", "¡Hasta el sábado! Que tengas buena tarde."]]}, "p": [["Ich mache am [dag] um [tijd] eine Party.", "Ik geef een feestje op [dag] om [tijd].", "I'm having a party on [dag] at [tijd].", "Je fais une fête [dag] à [tijd].", "Hago una fiesta el [dag] a las [tijd]."]]}, {"n": 25, "t": "Weer en kleine praatjes", "tt": {"de": "Wetter und Smalltalk", "nl": "Weer en kleine praatjes", "en": "Weather and small talk", "fr": "Météo et petites conversations", "es": "El tiempo y charlas cortas"}, "r": [["j", "Was für ein schönes Wetter heute!", "Wat een mooi weer vandaag!", "What lovely weather today!", "Quel beau temps aujourd'hui !", "¡Qué buen tiempo hace hoy!"], ["a", "Ja, endlich mal Sonne!", "Ja, eindelijk zon!", "Yes, finally some sun!", "Oui, enfin du soleil !", "¡Sí, por fin sol!"], ["j", "Ist es morgen auch so warm?", "Wordt het morgen ook zo warm?", "Will it be this warm tomorrow too?", "Il fera aussi chaud demain ?", "¿Mañana también hará este calor?"], ["a", "Ich glaube, es wird kälter und es regnet.", "Ik denk dat het kouder wordt en gaat regenen.", "I think it'll get colder and it'll rain.", "Je crois qu'il fera plus froid et qu'il pleuvra.", "Creo que hará más frío y lloverá."], ["j", "Oh, dann nehme ich lieber einen Regenschirm mit.", "Oh, dan neem ik beter een paraplu mee.", "Oh, then I'd better take an umbrella.", "Oh, alors je ferais mieux de prendre un parapluie.", "Vaya, entonces mejor me llevo un paraguas."], ["a", "Gute Idee. Hast du das Wochenende schon geplant?", "Goed idee. Heb je het weekend al gepland?", "Good idea. Have you planned your weekend yet?", "Bonne idée. Tu as déjà prévu ton week-end ?", "Buena idea. ¿Ya tienes planes para el fin de semana?"], ["j", "Noch nicht. Vielleicht ein bisschen Sport, du?", "Nog niet. Misschien een beetje sporten, jij?", "Not yet, maybe some sport. What about you?", "Pas encore. Peut-être un peu de sport, et toi ?", "Todavía no. Quizás hacer deporte, ¿y tú?"], ["a", "Ich gehe joggen. Das ist für mich der beste Start.", "Ik ga hardlopen. Dat is voor mij de beste start.", "I go jogging. That's the best start for me.", "Je fais du jogging. C'est le meilleur départ pour moi.", "Yo salgo a correr. Para mí es el mejor comienzo."], ["j", "Klingt gesund! Wo läufst du gern?", "Klinkt gezond! Waar loop je graag?", "Sounds healthy! Where do you like to run?", "Ça a l'air sain ! Tu aimes courir où ?", "¡Suena sano! ¿Dónde te gusta correr?"], ["a", "Im Park am Fluss. Der ist sehr schön.", "In het park langs de rivier. Dat is erg mooi.", "In the park by the river. It's very nice.", "Dans le parc au bord de la rivière. C'est très joli.", "En el parque junto al río. Es muy bonito."], ["j", "Den kenne ich noch nicht. Danke für den Tipp!", "Die ken ik nog niet. Bedankt voor de tip!", "I don't know it yet. Thanks for the tip!", "Je ne le connais pas encore. Merci pour le conseil !", "Todavía no lo conozco. ¡Gracias por el consejo!"], ["a", "Gern geschehen. Viel Spaß!", "Graag gedaan. Veel plezier!", "You're welcome. Have fun!", "Avec plaisir. Amuse-toi bien !", "De nada. ¡Que lo disfrutes!"], ["j", "Danke, dir auch einen schönen Tag!", "Dank je, jij ook een fijne dag!", "Thanks, have a nice day too!", "Merci, bonne journée à toi aussi !", "¡Gracias, que tengas buen día tú también!"], ["a", "Tschüss! Bis bald.", "Doei! Tot snel.", "Bye! See you soon.", "Salut ! À bientôt.", "¡Adiós! Hasta pronto."]], "v": {"1": [["Ja, endlich wieder Sonne!", "Ja, eindelijk weer zon!", "Yes, finally, some sunshine!", "Oui, enfin du soleil !", "¡Sí, por fin un poco de sol!"]], "3": [["Ich denke, morgen wird es kälter und regnet es.", "Ik denk van niet, het wordt kouder en het gaat regenen.", "I don't think so, it'll get colder and rain.", "Je pense que non, il fera plus froid et il pleuvra.", "Creo que no, hará más frío y lloverá."]], "5": [["Schöne Idee. Haben Sie das Wochenende schon geplant?", "Leuk idee. Heeft u het weekend al gepland?", "Nice idea. Have you planned your weekend yet?", "Belle idée. Avez-vous déjà prévu votre week-end ?", "Qué buena idea. ¿Ya tiene planes para el fin de semana?"]], "7": [["Ich gehe joggen. Das ist für mich ein guter Start.", "Ik ga joggen, dat is mijn start van de dag.", "I go running. That's how I start the day.", "Je vais courir. C'est mon meilleur départ.", "Yo salgo a correr. Es mi mejor comienzo."]], "9": [["Im Park am Fluss. Wirklich schön.", "In het park bij de rivier. Echt mooi.", "In the park by the river. It's lovely.", "Dans le parc au bord de la rivière. C'est magnifique.", "En el parque del río. Es precioso."]], "11": [["Kein Problem. Viel Spaß!", "Geen probleem. Veel plezier!", "You're welcome. Enjoy!", "Avec plaisir. Profite bien !", "De nada. ¡Que lo disfrutes!"]], "13": [["Tschüss! Bis später.", "Doei! Tot later.", "Bye! See you soon.", "Salut ! À plus tard.", "¡Adiós! Hasta luego."]]}, "p": [["Wie ist das Wetter in [plaats]?", "Hoe is het weer in [plaats]?", "What's the weather like in [plaats]?", "Quel temps fait-il à [plaats] ?", "¿Qué tiempo hace en [plaats]?"]]}, {"n": 26, "t": "Restaurant: allergie en dieet", "tt": {"de": "Restaurant: Allergie und Ernährung", "nl": "Restaurant: allergie en dieet", "en": "Restaurant: allergies and diet", "fr": "Restaurant : allergies et régime", "es": "Restaurante: alergias y dieta"}, "r": [["j", "Ich bin allergisch gegen Nüsse.", "Ik ben allergisch voor noten.", "I'm allergic to nuts.", "Je suis allergique aux noix.", "Soy alérgico a los frutos secos."], ["a", "Okay. Ist in der Soße Nuss?", "Oké. Zit er noten in de saus?", "Okay. Are there nuts in the sauce?", "D'accord. Il y a des noix dans la sauce ?", "Vale. ¿La salsa lleva frutos secos?"], ["j", "Ist hier Fleisch drin?", "Zit hier vlees in?", "Is there meat in this?", "Il y a de la viande dedans ?", "¿Esto lleva carne?"], ["a", "Nein, das ist ein vegetarisches Gericht.", "Nee, dit is een vegetarisch gerecht.", "No, this is a vegetarian dish.", "Non, c'est un plat végétarien.", "No, este plato es vegetariano."], ["j", "Ich esse glutenfrei.", "Ik eet glutenvrij.", "I eat gluten-free.", "Je mange sans gluten.", "Como sin gluten."], ["j", "Was empfehlen Sie?", "Wat raadt u aan?", "What do you recommend?", "Qu'est-ce que vous me conseillez ?", "¿Qué me recomienda?"], ["a", "Probieren Sie die Gemüsesuppe, die ist glutenfrei und ohne Nüsse.", "Probeer de groentesoep, die is glutenvrij en zonder noten.", "Try the vegetable soup. It's gluten-free and nut-free.", "Goûtez la soupe de légumes, elle est sans gluten et sans noix.", "Pruebe la sopa de verduras. Es sin gluten y sin frutos secos."], ["j", "Ist die Suppe bestimmt frei von Nüssen?", "Is de soep zeker vrij van noten?", "Are you sure the soup is nut-free?", "Vous êtes sûr que la soupe ne contient pas de noix ?", "¿Está seguro de que la sopa no tiene frutos secos?"], ["a", "Ich schaue kurz in der Küche nach. Einen Moment, bitte.", "Ik kijk even in de keuken. Een moment, alstublieft.", "Let me check in the kitchen. One moment, please.", "Je vérifie en cuisine. Un instant, s'il vous plaît.", "Voy a mirar en la cocina. Un momento, por favor."], ["j", "Danke, das ist für mich wichtig.", "Dank u, dat is voor mij belangrijk.", "Thanks, that's important to me.", "Merci, c'est important pour moi.", "Gracias, es importante para mí."], ["a", "Ja, die Suppe ist sicher nussfrei und glutenfrei.", "Ja, de soep is zeker vrij van noten en glutenvrij.", "Yes, the soup is definitely nut-free and gluten-free.", "Oui, la soupe est bien sans noix et sans gluten.", "Sí, la sopa está segura: sin frutos secos y sin gluten."], ["j", "Ich nehme die Suppe. Und danach?", "Ik neem de soep. En daarna?", "I'll have the soup. And after that?", "Je prends la soupe. Et après ?", "Tomo la sopa. ¿Y después?"], ["a", "Das Hauptgericht ist Hähnchen mit Reis, ohne Soße mit Nüssen.", "Het hoofdgerecht is kip met rijst, zonder saus met noten.", "The main course is chicken with rice, without the sauce with nuts.", "Le plat principal est du poulet au riz, sans sauce aux noix.", "El plato principal es pollo con arroz, sin salsa de frutos secos."], ["j", "Haben Sie auch ein vegetarisches Hauptgericht?", "Heeft u ook een vegetarisch hoofdgerecht?", "Do you also have a vegetarian main course?", "Vous avez aussi un plat principal végétarien ?", "¿Tienen también un plato principal vegetariano?"], ["a", "Ja, die Gemüsepasta. Die ist ohne Nüsse, aber nicht glutenfrei.", "Ja, de groentepasta. Die is zonder noten, maar niet glutenvrij.", "Yes, the vegetable pasta. It's nut-free, but not gluten-free.", "Oui, les pâtes aux légumes. Elles sont sans noix, mais pas sans gluten.", "Sí, la pasta de verduras. Está sin frutos secos, pero no es sin gluten."], ["j", "Dann nehme ich die Suppe. Vielen Dank.", "Dan neem ik de soep. Dank u wel.", "Then I'll have the soup. Thank you.", "Alors je prends la soupe. Merci beaucoup.", "Entonces tomo la sopa. Muchas gracias."], ["a", "Gut. Ich bringe sie gleich.", "Goed. Ik breng hem zo.", "Okay. I'll bring it right away.", "Très bien. Je vous l'apporte tout de suite.", "Muy bien. Se la traigo enseguida."]], "v": {"0": [["Ich habe eine Nussallergie.", "Ik heb een notenallergie.", "I have a nut allergy.", "J'ai une allergie aux noix.", "Tengo alergia a los frutos secos."]], "1": [["Okay. Ist in dem Gericht Nuss?", "Oké. Zit er noten in het gerecht?", "Okay. Are there nuts in the dish?", "D'accord. Il y a des noix dans le plat ?", "Vale. ¿El plato lleva frutos secos?"]], "3": [["Nein, das ist vegetarisch.", "Nee, dit is vegetarisch.", "No, it's vegetarian.", "Non, c'est végétarien.", "No, es vegetariano."]], "4": [["Ich mache eine glutenfreie Diät.", "Ik heb een glutenvrij dieet.", "I'm on a gluten-free diet.", "Je suis au régime sans gluten.", "Sigo una dieta sin gluten."]], "5": [["Was empfiehlst du?", "Wat raad je aan?", "What do you recommend?", "Qu'est-ce que tu me conseilles ?", "¿Qué me recomiendas?"]], "6": [["Probier die Gemüsesuppe, die ist glutenfrei und nussfrei.", "Neem de groentesoep, die is glutenvrij en zonder noten.", "Go for the vegetable soup, it's gluten-free and nut-free.", "Prends la soupe de légumes, elle est sans gluten et sans noix.", "Toma la sopa de verduras, es sin gluten y sin frutos secos."]], "10": [["Ja, die Suppe ist garantiert ohne Nüsse und glutenfrei.", "Ja, de soep is zeker zonder noten en glutenvrij.", "Yes, the soup is definitely without nuts and gluten-free.", "Oui, la soupe est certainement sans noix et sans gluten.", "Sí, la sopa seguro que no lleva frutos secos ni gluten."]], "14": [["Ja, die Gemüsepasta, ohne Nüsse. Glutenfrei ist sie nicht.", "Ja, de groentepasta, zonder noten. Glutenvrij is die niet.", "Yes, the vegetable pasta, no nuts. It's not gluten-free, though.", "Oui, les pâtes aux légumes, sans noix. Mais elles ne sont pas sans gluten.", "Sí, la pasta de verduras, sin frutos secos. Pero no es sin gluten."]], "15": [["Dann nehme ich die Suppe. Danke.", "Dan neem ik de soep. Bedankt.", "Then I'll have the soup. Thanks.", "Alors je prends la soupe. Merci.", "Entonces tomo la sopa. Gracias."]]}}, {"n": 27, "t": "Je niet goed voelen onderweg", "tt": {"de": "Unterwegs geht es dir nicht gut", "nl": "Je niet goed voelen onderweg", "en": "Feeling unwell while out", "fr": "Se sentir mal en route", "es": "Encontrarse mal fuera de casa"}, "r": [["j", "Mir geht es nicht gut.", "Ik voel me niet goed.", "I don't feel well.", "Je ne me sens pas bien.", "No me encuentro bien."], ["a", "Was ist los?", "Wat is er aan de hand?", "What's wrong?", "Qu'est-ce qui ne va pas ?", "¿Qué le pasa?"], ["j", "Mir ist schwindelig.", "Ik ben duizelig.", "I feel dizzy.", "J'ai la tête qui tourne.", "Estoy mareado."], ["a", "Setzen Sie sich bitte hin. Ich hole Ihnen Wasser.", "Gaat u even zitten. Ik haal water voor u.", "Sit down. I'll get you some water.", "Asseyez-vous. Je vous chercherai de l'eau.", "Siéntese. Le traigo agua."], ["j", "Ich brauche Hilfe.", "Ik heb hulp nodig.", "I need help.", "J'ai besoin d'aide.", "Necesito ayuda."], ["a", "Was kann ich für Sie tun?", "Wat kan ik voor u doen?", "What can I do for you?", "Que puis-je faire pour vous ?", "¿Qué puedo hacer por usted?"], ["j", "Können Sie einen Arzt rufen?", "Kunt u een dokter bellen?", "Could you call a doctor?", "Pouvez-vous appeler un médecin ?", "¿Puede llamar a un médico?"], ["a", "Ja, ich rufe sofort an. Möchten Sie sich kurz auf die Bank setzen?", "Ja, ik bel meteen. Wilt u even op een bankje zitten?", "Yes, I'll call right away. Would you like to sit on the bench?", "Oui, j'appelle tout de suite. Vous voulez vous asseoir sur le banc ?", "Sí, llamo enseguida. ¿Quiere sentarse en el banco?"], ["j", "Ja, gern. Danke schön.", "Ja, graag. Dank u wel.", "Yes, please. Thank you.", "Oui, merci beaucoup.", "Sí, por favor. Muchas gracias."], ["a", "Hier ist Wasser. Trinken Sie langsam.", "Hier is water. Neemt u rustig een slokje.", "Here's some water. Drink slowly.", "Voilà de l'eau. Buvez doucement.", "Aquí tiene agua. Beba despacio."], ["j", "Mein Kopf dreht sich. Ich kann nicht laufen.", "Mijn hoofd draait. Ik kan niet lopen.", "My head is spinning. I can't walk.", "J'ai la tête qui tourne. Je ne peux pas marcher.", "Me da vueltas la cabeza. No puedo caminar."], ["a", "Bleiben Sie sitzen, ich rufe den Krankenwagen.", "Blijft u zitten, ik bel de ambulance.", "Stay seated, I'll call an ambulance.", "Restez assis, j'appelle une ambulance.", "Quédese sentado, llamo a una ambulancia."], ["j", "Danke. Ich fühle mich schon etwas besser.", "Dank u. Ik voel me al een beetje beter.", "Thanks. I already feel a bit better.", "Merci. Je me sens déjà un peu mieux.", "Gracias. Ya me siento un poco mejor."], ["a", "Schön. Bleiben Sie trotzdem sitzen, bis der Krankenwagen da ist.", "Fijn. Blijft u toch zitten tot de ambulance er is.", "Good. Stay seated until the ambulance gets here anyway.", "Tant mieux. Restez tout de même assis jusqu'à l'arrivée de l'ambulance.", "Qué bien. Quédese sentado de todos modos hasta que llegue la ambulancia."]], "v": {"0": [["Mir geht es gerade gar nicht gut.", "Ik voel me nu echt niet goed.", "I really don't feel well right now.", "Je me sens mal.", "Me siento mal."]], "1": [["Alles okay? Was fühlst du?", "Gaat het? Wat voel je?", "Are you okay? What do you feel?", "Ça va ? Qu'est-ce que tu ressens ?", "¿Estás bien? ¿Qué sientes?"]], "3": [["Setz dich hin. Ich hole dir Wasser.", "Ga even zitten. Ik haal water voor je.", "Sit down. I'll get you some water.", "Assieds-toi. Je t'apporte de l'eau.", "Siéntate. Te traigo agua."]], "5": [["Was kann ich für dich tun?", "Wat kan ik voor je doen?", "What can I do for you?", "Que puis-je faire pour toi ?", "¿Qué puedo hacer por ti?"]], "6": [["Kannst du einen Arzt rufen?", "Kun je een dokter bellen?", "Could you call a doctor?", "Tu peux appeler un médecin ?", "¿Puedes llamar a un médico?"]], "9": [["Hier ist Wasser. Trink langsam.", "Hier is water. Drink maar rustig.", "Here's some water. Drink slowly.", "Voilà de l'eau. Bois doucement.", "Aquí tienes agua. Bebe despacio."]], "11": [["Bleib sitzen, ich rufe sofort den Krankenwagen.", "Blijf zitten, ik bel meteen de ambulance.", "Stay seated, I'm calling an ambulance now.", "Reste assis, j'appelle l'ambulance.", "Quédate sentado, llamo a la ambulancia."]]}}, {"n": 28, "t": "Toerist in de stad", "tt": {"de": "Als Tourist in der Stadt", "nl": "Toerist in de stad", "en": "Tourist in town", "fr": "Touriste en ville", "es": "Turista en la ciudad"}, "r": [["j", "Können Sie ein Foto von uns machen?", "Kunt u een foto van ons maken?", "Could you take a photo of us?", "Vous pourriez nous prendre en photo ?", "¿Puede hacernos una foto?"], ["a", "Natürlich. Wo muss ich drücken?", "Natuurlijk. Waar moet ik op drukken?", "Sure. Which button do I press?", "Bien sûr. Sur quel bouton j'appuie ?", "Claro. ¿Dónde tengo que pulsar?"], ["j", "Hier, der Knopf unten.", "Hier, op de knop onderaan.", "Here, the button at the bottom.", "Ici, le bouton en bas.", "Aquí, el botón de abajo."], ["a", "Sind Sie bereit? Ich stelle den Timer ein.", "Staan jullie klaar? Ik zet hem op de timer.", "Are you ready? I'll set the timer.", "Vous êtes prêts ? Je mets le minuteur.", "¿Están listos? Lo pongo en el temporizador."], ["j", "Ja, wir sind so weit. Danke!", "Ja, we zijn klaar. Dank u!", "Yes, we're ready. Thanks!", "Oui, on est prêts. Merci !", "Sí, estamos listos. ¡Gracias!"], ["a", "Hier ist das Foto.", "Hier is de foto.", "Here's the photo.", "Voilà la photo.", "Aquí tiene la foto."], ["j", "Schön! Wo ist die Innenstadt?", "Mooi! Waar is het centrum?", "Lovely! Where's the city centre?", "Super ! Où est le centre-ville ?", "¡Qué bien! ¿Dónde está el centro?"], ["a", "Das Zentrum ist auf der anderen Seite der Brücke. Fünf Minuten zu Fuß.", "Het centrum is aan de overkant van de brug, vijf minuten lopen.", "The centre is across the bridge, five minutes on foot.", "Le centre est de l'autre côté du pont. Cinq minutes à pied.", "El centro está al otro lado del puente. Cinco minutos a pie."], ["j", "Ist es weit zu Fuß?", "Is het ver lopen?", "Is it far to walk?", "C'est loin à pied ?", "¿Está lejos a pie?"], ["a", "Nein, nicht weit. Eine Viertelstunde.", "Nee, het is niet ver. Een kwartiertje.", "No, it's not far. About fifteen minutes.", "Non, pas très loin. Un quart d'heure.", "No, no está lejos. Unos quince minutos."], ["j", "Was kann man hier gut sehen?", "Wat is hier leuk om te zien?", "What's worth seeing here?", "Qu'est-ce qui vaut le détour ici ?", "¿Qué se puede ver aquí?"], ["a", "Die alte Kirche und der Markt am Samstag sind wirklich schön.", "De oude kerk en de markt op zaterdag zijn echt mooi.", "The old church and the Saturday market are really nice.", "La vieille église et le marché du samedi valent vraiment le détour.", "La iglesia antigua y el mercado del sábado son muy bonitos."], ["j", "Vielen Dank für den Tipp!", "Dank u wel voor de tip!", "Thanks for the tip!", "Merci pour le conseil !", "¡Gracias por el consejo!"], ["a", "Gern geschehen. Viel Spaß in unserer Stadt!", "Graag gedaan. Veel plezier in onze stad!", "You're welcome. Enjoy our city!", "Avec plaisir. Profitez bien de notre ville !", "De nada. ¡Disfrute de nuestra ciudad!"]], "v": {"0": [["Kannst du ein Foto von uns machen?", "Kun je een foto van ons maken?", "Could you take a photo of us?", "Tu peux nous prendre en photo ?", "¿Puedes hacernos una foto?"]], "2": [["Hier, der Knopf da unten.", "Hier, de knop onderaan.", "Here, the button at the bottom.", "Là, le bouton en bas.", "Aquí, el botón de abajo."]], "6": [["Schön! Wo genau ist das Zentrum?", "Mooi! Waar is het centrum precies?", "Lovely! Where exactly is the centre?", "Super ! Le centre-ville, c'est où exactement ?", "¡Qué bonito! ¿Dónde está exactamente el centro?"]], "9": [["Nein, gar nicht weit. Eine Viertelstunde.", "Nee hoor, het is niet ver. Een kwartier.", "No, not far at all. About fifteen minutes.", "Non, pas loin du tout. Un quart d'heure.", "No, no está nada lejos. Unos quince minutos."]], "11": [["Die alte Kirche und der Samstagsmarkt, unbedingt.", "De oude kerk en de markt op zaterdag, zeker doen.", "The old church and the Saturday market, definitely.", "La vieille église et le marché du samedi, sans hésiter.", "La iglesia antigua y el mercado del sábado, sin duda."]]}}, {"n": 29, "t": "De weg gewezen krijgen", "tt": {"de": "Den Weg erklärt bekommen", "nl": "De weg gewezen krijgen", "en": "Being given directions", "fr": "Se faire indiquer le chemin", "es": "Que te indiquen el camino"}, "r": [["j", "Wie komme ich zum Museum?", "Hoe kom ik bij het museum?", "How do I get to the museum?", "Comment on va au musée ?", "¿Cómo llego al museo?"], ["a", "Am Ende dieser Straße gehen Sie rechts.", "Aan het einde van deze straat gaat u rechts.", "At the end of this street, turn right.", "Au bout de cette rue, tournez à droite.", "Al final de esta calle, gire a la derecha."], ["j", "Am Ende der Straße, rechts. Stimmt das?", "Aan het einde van de straat, rechts. Klopt dat?", "At the end of the street, right. Is that right?", "Au bout de la rue, à droite. C'est ça ?", "Al final de la calle, a la derecha. ¿Es así?"], ["a", "Ja, genau. Dann die zweite Straße links.", "Ja, precies. Dan de tweede straat links.", "Yes, exactly. Then the second street on the left.", "Oui, exactement. Puis la deuxième rue à gauche.", "Sí, exacto. Luego la segunda calle a la izquierda."], ["j", "Die zweite links.", "De tweede links.", "The second on the left.", "La deuxième à gauche.", "La segunda a la izquierda."], ["a", "Nach der Ampel gehen Sie weiter.", "Na het stoplicht loopt u door.", "After the traffic light, keep walking.", "Après le feu, continuez.", "Después del semáforo, siga caminando."], ["j", "Nach der Ampel, weitergehen.", "Na het stoplicht, doorlopen.", "After the traffic light, keep going.", "Après le feu, continuer.", "Después del semáforo, seguir."], ["a", "Das Museum steht gegenüber der Kirche.", "Het museum staat tegenover de kerk.", "The museum is opposite the church.", "Le musée est en face de l'église.", "El museo está enfrente de la iglesia."], ["j", "Gegenüber der Kirche. Wie lange dauert der Weg?", "Tegenover de kerk. Hoe lang duurt het lopen?", "Opposite the church. How long does it take to walk?", "En face de l'église. Ça prend combien de temps à pied ?", "Enfrente de la iglesia. ¿Cuánto se tarda andando?"], ["a", "Etwa zehn Minuten.", "Ongeveer tien minuten.", "About ten minutes.", "Environ dix minutes.", "Unos diez minutos."], ["j", "Also: am Ende der Straße rechts, die zweite links, nach der Ampel. Stimmt das?", "Dus: aan het eind rechts, de tweede links, na het stoplicht. Klopt dat?", "So: at the end, right, second left, after the traffic light. Is that right?", "Au bout, à droite. Puis la deuxième à gauche, après le feu. C'est ça ?", "Al final, a la derecha. Luego la segunda a la izquierda, después del semáforo. ¿Es así?"], ["a", "Ja, das stimmt. Genau so.", "Ja, dat klopt. Precies zo.", "Yes, that's right. Exactly.", "Oui, c'est ça. Exactement.", "Sí, es así. Exactamente."], ["j", "Vielen Dank. Dann bin ich in zehn Minuten da.", "Dank u wel. Dan ben ik er over tien minuten.", "Thank you. Then I'll be there in ten minutes.", "Merci beaucoup. Alors j'y serai dans dix minutes.", "Muchas gracias. Entonces llego en diez minutos."], ["a", "Viel Erfolg!", "Veel succes!", "Good luck!", "Bonne chance !", "¡Mucha suerte!"]], "v": {"1": [["Am Ende der Straße dann rechts.", "Aan het eind van de straat, dan rechts.", "At the end of the street, then right.", "Au bout de la rue, puis à droite.", "Al final de la calle, luego a la derecha."]], "5": [["Nach der Ampel gehst du weiter.", "Na het stoplicht loop je door.", "After the traffic light, keep going.", "Après le feu, tu continues.", "Después del semáforo, sigue."]], "9": [["So zehn Minuten, würde ich sagen.", "Een minuut of tien, schat ik.", "Ten minutes or so, I'd say.", "Une dizaine de minutes, je dirais.", "Diez minutos más o menos."]]}}, {"n": 30, "t": "Winkel en kassa", "tt": {"de": "Laden und Kasse", "nl": "Winkel en kassa", "en": "Shop and checkout", "fr": "Magasin et caisse", "es": "Tienda y caja"}, "r": [["j", "Das ist alles, bitte.", "Dit is alles, alstublieft.", "That's everything, please.", "C'est tout, s'il vous plaît.", "Eso es todo, por favor."], ["a", "Möchten Sie eine Tüte?", "Wilt u een tas?", "Would you like a bag?", "Vous voulez un sac ?", "¿Quiere una bolsa?"], ["j", "Ja, gern. Was kostet sie?", "Ja, graag. Hoeveel kost hij?", "Yes, please. How much is it?", "Oui, s'il vous plaît. Ça coûte combien ?", "Sí, por favor. ¿Cuánto cuesta?"], ["a", "Zehn Cent.", "Tien cent.", "Ten cents.", "Dix centimes.", "Diez céntimos."], ["j", "Wann schließen Sie heute?", "Hoe laat sluiten jullie vandaag?", "What time do you close today?", "À quelle heure fermez-vous aujourd'hui ?", "¿A qué hora cierran hoy?"], ["a", "Um neun Uhr.", "Om negen uur.", "At nine o'clock.", "À neuf heures.", "A las nueve."], ["j", "Haben Sie das auch in der großen Packung?", "Heeft u dit ook in het groot?", "Do you have this in a larger size?", "Vous avez ça en plus grand ?", "¿Tienen esto en tamaño grande?"], ["a", "Ja, die große Packung steht hinten.", "Ja, het grote pak staat achterin.", "Yes, the large pack is at the back.", "Oui, le grand format est au fond.", "Sí, el envase grande está al fondo."], ["j", "Kann ich den Kassenbon haben?", "Mag ik het bonnetje?", "Can I have the receipt?", "Je peux avoir le ticket ?", "¿Me da el ticket?"], ["a", "Ja, hier ist er. Schönen Abend!", "Ja, hier is hij. Fijne avond!", "Yes, here it is. Have a nice evening!", "Oui, le voilà. Bonne soirée !", "Sí, aquí lo tiene. ¡Buenas tardes!"], ["j", "Vielen Dank. Auf Wiedersehen!", "Dank u wel. Tot ziens!", "Thank you. Goodbye!", "Merci beaucoup. Au revoir !", "Muchas gracias. ¡Adiós!"], ["a", "Gern geschehen. Auf Wiedersehen!", "Graag gedaan. Tot ziens!", "You're welcome. Goodbye!", "Avec plaisir. Au revoir !", "De nada. ¡Adiós!"]], "v": {"1": [["Willst du eine Tüte?", "Wil je een tas?", "Do you want a bag?", "Tu veux un sac ?", "¿Quieres una bolsa?"]], "4": [["Wann machst du heute zu?", "Hoe laat ga je vandaag dicht?", "What time do you close today?", "À quelle heure fermes-tu aujourd'hui ?", "¿A qué hora cierras hoy?"]], "6": [["Hast du das auch größer?", "Heb je dit ook groter?", "Do you have this in a bigger one?", "Tu as ça en plus grand ?", "¿Tienes esto más grande?"]], "7": [["Ja, die große Packung ist hinten.", "Ja, het grote pak staat achterin.", "Yes, the big one is at the back.", "Oui, le grand paquet est au fond.", "Sí, el envase grande está al fondo."]], "8": [["Darf ich den Bon bitte haben?", "Mag ik een bonnetje, alstublieft?", "May I have the receipt, please?", "Je peux avoir le ticket de caisse, s'il vous plaît ?", "¿Me da el ticket, por favor?"]]}}, {"n": 31, "t": "Kleine praatjes met onbekenden", "tt": {"de": "Smalltalk mit Fremden", "nl": "Kleine praatjes met onbekenden", "en": "Small talk with strangers", "fr": "Petites conversations avec des inconnus", "es": "Charlas cortas con desconocidos"}, "r": [["j", "Schönes Wetter, oder?", "Lekker weertje hè!", "Nice weather, isn't it?", "Il fait beau, hein ?", "Qué buen tiempo, ¿verdad?"], ["a", "Ja, endlich. Es ist aber warm, nicht?", "Ja, eindelijk. Het is wel warm, hè?", "Yes, finally. It's pretty warm, isn't it?", "Oui, enfin. Il fait quand même chaud, non ?", "Sí, por fin. Hace bastante calor, ¿no?"], ["j", "Heute ist es aber warm!", "Wat warm vandaag, zeg!", "It's so warm today!", "Il fait vraiment chaud aujourd'hui !", "¡Qué calor hace hoy!"], ["a", "Ja, wirklich. Ich trinke viel Wasser.", "Ja, echt. Ik drink veel water.", "Yes, really. I'm drinking lots of water.", "Oui, vraiment. Je bois beaucoup d'eau.", "Sí, de verdad. Bebo mucha agua."], ["j", "Woher kommst du?", "Waar kom je vandaan?", "Where are you from?", "Tu viens d'où ?", "¿De dónde eres?"], ["a", "Ich komme aus Polen. Und du?", "Ik kom uit Polen. En jij?", "I'm from Poland. And you?", "Je viens de Pologne. Et toi ?", "Vengo de Polonia. ¿Y tú?"], ["j", "Ich komme aus Deutschland. Wie lange bleibst du hier?", "Ik kom uit Duitsland. Hoe lang blijf je hier?", "I'm from Germany. How long are you staying here?", "Je viens d'Allemagne. Tu restes combien de temps ici ?", "Vengo de Alemania. ¿Cuánto tiempo te quedas aquí?"], ["a", "Noch eine Woche. Ich bin beruflich hier.", "Nog een week. Ik ben hier voor werk.", "Another week. I'm here for work.", "Encore une semaine. Je suis là pour le travail.", "Una semana más. Estoy aquí por trabajo."], ["j", "Bist du beruflich oder im Urlaub hier?", "Ben je hier voor werk of vakantie?", "Are you here for work or holiday?", "Tu es là pour le travail ou en vacances ?", "¿Estás aquí por trabajo o de vacaciones?"], ["a", "Urlaub. Es ist eine schöne Stadt.", "Vakantie. Het is een mooie stad.", "Holiday. It's a beautiful city.", "Vacances. C'est une belle ville.", "Vacaciones. Es una ciudad preciosa."], ["j", "Ja, sicher. Viel Spaß!", "Ja, zeker. Veel plezier!", "Yes, definitely. Enjoy!", "Oui, sûrement. Amuse-toi bien !", "Sí, seguro. ¡Que te diviertas!"], ["a", "Danke. Schönen Tag noch!", "Dank je. Fijne dag nog!", "Thanks. Have a nice day!", "Merci. Bonne journée !", "Gracias. ¡Que tenga buen día!"]], "v": {"0": [["Schönes Wetter heute, nicht wahr?", "Mooi weer vandaag, hè?", "Lovely weather today, isn't it?", "Il fait beau aujourd'hui, n'est-ce pas ?", "Hace buen tiempo hoy, ¿no?"]], "3": [["Ja, echt. Ich trinke den ganzen Tag Wasser.", "Ja, echt wel. Ik drink de hele dag water.", "Yes, really. I'm drinking water all day.", "Oui, vraiment. Je bois de l'eau toute la journée.", "Sí, de verdad. Bebo agua todo el día."]], "4": [["Woher kommen Sie?", "Waar komt u vandaan?", "Where are you from?", "D'où venez-vous ?", "¿De dónde es usted?"]], "5": [["Ich komme aus Polen. Und Sie?", "Ik kom uit Polen. En u?", "I'm from Poland. And you?", "Je viens de Pologne. Et vous ?", "Vengo de Polonia. ¿Y usted?"]], "6": [["Ich komme aus Deutschland. Wie lange bleiben Sie hier?", "Ik kom uit Duitsland. Hoe lang blijft u hier?", "I'm from Germany. How long are you staying?", "Je viens d'Allemagne. Vous restez combien de temps ?", "Vengo de Alemania. ¿Cuánto tiempo se queda aquí?"]], "8": [["Sind Sie beruflich oder im Urlaub hier?", "Bent u hier voor werk of vakantie?", "Are you here for work or holiday?", "Vous êtes là pour le travail ou en vacances ?", "¿Está aquí por trabajo o de vacaciones?"]], "11": [["Danke, Ihnen auch!", "Dank u, u ook!", "Thanks, you too!", "Merci, vous aussi !", "¡Gracias, igualmente!"]]}}, {"n": 32, "t": "Spullen kwijt of kapot", "tt": {"de": "Sachen verloren oder kaputt", "nl": "Spullen kwijt of kapot", "en": "Things lost or broken", "fr": "Objets perdus ou cassés", "es": "Cosas perdidas o rotas"}, "r": [["j", "Ich habe meine Tasche verloren.", "Ik heb mijn tas verloren.", "I've lost my bag.", "J'ai perdu mon sac.", "He perdido mi bolso."], ["a", "Wo hatten Sie sie zuletzt?", "Waar had u hem voor het laatst?", "Where did you last have it?", "Où l'aviez-vous en dernier ?", "¿Dónde lo tenía por última vez?"], ["j", "Ich glaube, in der U-Bahn.", "Ik denk in de metro.", "I think on the metro.", "Je crois que c'était dans le métro.", "Creo que en el metro."], ["a", "Dann müssen Sie das beim Verkehrsbetrieb melden.", "Dan moet u het bij de vervoerder melden.", "Then you should report it to the transport company.", "Dans ce cas, signalez-le à la compagnie de transport.", "Entonces tiene que informar a la compañía de transporte."], ["j", "Mein Handy wurde gestohlen.", "Mijn telefoon is gestolen.", "My phone has been stolen.", "On m'a volé mon téléphone.", "Me han robado el móvil."], ["a", "Was ist passiert?", "Wat is er gebeurd?", "What happened?", "Qu'est-ce qui s'est passé ?", "¿Qué ha pasado?"], ["j", "Gerade eben, im Zug.", "Net, in de trein.", "Just now, on the train.", "Tout à l'heure, dans le train.", "Hace un momento, en el tren."], ["a", "Haben Sie die Nummer Ihres Handys? Dann können wir es sperren lassen.", "Heeft u het nummer van uw telefoon? Dan kunnen we het blokkeren.", "Do you have your phone number? Then we can block it.", "Vous avez le numéro de votre téléphone ? Ainsi nous pourrons le bloquer.", "¿Tiene el número de su móvil? Así podemos bloquearlo."], ["j", "Ja, die Nummer habe ich.", "Ja, ik heb het nummer.", "Yes, I have the number.", "Oui, j'ai le numéro.", "Sí, tengo el número."], ["a", "Möchten Sie auch Ihre Bankkarte sperren lassen?", "Wilt u ook uw bankpas laten blokkeren?", "Do you also want to block your bank card?", "Vous voulez aussi bloquer votre carte bancaire ?", "¿También quiere bloquear su tarjeta bancaria?"], ["j", "Ja, meine Karte funktioniert auch nicht mehr.", "Ja, mijn kaart werkt ook niet meer.", "Yes, my card doesn't work anymore either.", "Oui, ma carte ne marche plus non plus.", "Sí, mi tarjeta tampoco funciona."], ["a", "Dann können Sie die Karte auch bei Ihrer Bank sperren lassen.", "Dan kunt u de kaart ook bij uw bank blokkeren.", "Then you can also block the card with your bank.", "Vous pouvez aussi bloquer la carte auprès de votre banque.", "Entonces también puede bloquear la tarjeta en su banco."], ["j", "Wo ist die nächste Polizeiwache?", "Waar is het dichtstbijzijnde politiebureau?", "Where is the nearest police station?", "Où est le commissariat le plus proche ?", "¿Dónde está la comisaría más cercana?"], ["a", "Zwei Straßen weiter, auf der linken Seite.", "Twee straten verder, aan de linkerkant.", "Two streets further, on the left.", "Deux rues plus loin, à gauche.", "Dos calles más allá, a la izquierda."], ["j", "Vielen Dank. Ich gehe sofort.", "Dank u wel. Ik ga meteen.", "Thank you. I'll go right away.", "Merci beaucoup. J'y vais tout de suite.", "Muchas gracias. Voy enseguida."], ["a", "Viel Glück. Ich hoffe, Sie finden alles wieder.", "Succes. Ik hoop dat u alles terugvindt.", "Good luck. I hope you get everything back.", "Bon courage. J'espère que vous retrouverez tout.", "Mucha suerte. Espero que lo recupere todo."]], "v": {"0": [["Meine Tasche ist weg.", "Mijn tas is weg.", "My bag is gone.", "Mon sac a disparu.", "Se me ha perdido el bolso."]], "1": [["Wo hattest du sie zuletzt?", "Waar had je hem voor het laatst?", "Where did you last have it?", "Où tu l'avais en dernier ?", "¿Dónde lo tenías por última vez?"]], "3": [["Dann musst du das beim Verkehrsbetrieb melden.", "Dan moet je het bij de vervoerder melden.", "Then you should report it to the transport company.", "Alors signale-le à la compagnie de transport.", "Entonces tienes que informar a la compañía de transporte."]], "4": [["Jemand hat mein Handy gestohlen.", "Iemand heeft mijn telefoon gestolen.", "Someone stole my phone.", "Quelqu'un m'a volé mon téléphone.", "Alguien me ha robado el móvil."]], "5": [["Wann ist das passiert?", "Wanneer is dat gebeurd?", "When did that happen?", "Quand ça s'est passé ?", "¿Cuándo ha pasado?"]], "9": [["Willst du auch deine Bankkarte sperren lassen?", "Wil je ook je bankpas laten blokkeren?", "Do you want to block your bank card too?", "Tu veux aussi bloquer ta carte bancaire ?", "¿Quieres bloquear también tu tarjeta bancaria?"]], "12": [["Wo ist das Polizeirevier?", "Waar is het politiebureau?", "Where's the police station?", "Où se trouve le commissariat ?", "¿Dónde está la comisaría?"]]}}, {"n": 33, "t": "Sollicitatiegesprek", "tt": {"de": "Vorstellungsgespräch", "nl": "Sollicitatiegesprek", "en": "Job interview", "fr": "Entretien d'embauche", "es": "Entrevista de trabajo"}, "r": [["j", "Guten Tag, ich bin Lisa Berg. Vielen Dank für die Einladung.", "Goedendag, ik ben Lisa Berg. Dank u wel voor de uitnodiging.", "Hello, I'm Lisa Berg. Thank you for the invitation.", "Bonjour, je suis Lisa Berg. Merci pour l'invitation.", "Buenos días, soy Lisa Berg. Gracias por la invitación."], ["a", "Guten Tag, Frau Berg. Nehmen Sie bitte Platz.", "Goedendag mevrouw Berg. Gaat u maar zitten.", "Good day, Ms Berg. Please, take a seat.", "Bonjour madame Berg. Asseyez-vous, je vous en prie.", "Buenos días, señora Berg. Siéntese, por favor."], ["j", "Danke. Ich freue mich auf das Gespräch.", "Dank u. Ik kijk uit naar het gesprek.", "Thanks. I'm looking forward to the conversation.", "Merci. Je suis impatiente de commencer l'entretien.", "Gracias. Tengo muchas ganas de empezar la entrevista."], ["a", "Erzählen Sie uns bitte etwas über sich.", "Kunt u ons iets over uzelf vertellen?", "Could you tell us something about yourself?", "Pouvez-vous nous parler un peu de vous ?", "¿Puede contarnos algo sobre usted?"], ["j", "Ich arbeite seit drei Jahren in der Kinderbetreuung.", "Ik werk al drie jaar in de kinderopvang.", "I've worked in childcare for three years.", "Je travaille dans la garde d'enfants depuis trois ans.", "Trabajo en el cuidado de niños desde hace tres años."], ["a", "Was ist Ihre größte Stärke im Beruf?", "Wat is uw grootste kracht in het werk?", "What is your greatest strength at work?", "Quelle est votre plus grande qualité au travail ?", "¿Cuál es su mayor fortaleza en el trabajo?"], ["j", "Ich bin geduldig und höre den Menschen gut zu.", "Ik ben geduldig en luister goed naar mensen.", "I'm patient and I listen well to people.", "Je suis patiente et j'écoute bien les gens.", "Soy paciente y escucho bien a la gente."], ["a", "Wie gehen Sie mit Stress bei der Arbeit um?", "Hoe gaat u om met stress op het werk?", "How do you handle stress at work?", "Comment gérez-vous le stress au travail ?", "¿Cómo maneja el estrés en el trabajo?"], ["j", "Ich mache einen Plan und erledige eins nach dem anderen.", "Ik maak een planning en pak één ding tegelijk aan.", "I make a plan and tackle one thing at a time.", "Je fais un planning et je traite une chose à la fois.", "Hago un plan y abordo una cosa a la vez."], ["a", "Wann könnten Sie bei uns anfangen?", "Wanneer zou u bij ons kunnen beginnen?", "When could you start with us?", "Quand pourriez-vous commencer chez nous ?", "¿Cuándo podría empezar con nosotros?"], ["j", "Ich könnte in zwei Wochen anfangen.", "Ik kan over twee weken beginnen.", "I could start in two weeks.", "Je pourrais commencer dans deux semaines.", "Podría empezar dentro de dos semanas."], ["a", "Danke. Wir melden uns innerhalb einer Woche bei Ihnen.", "Dank u wel. Wij laten het u binnen een week weten.", "Thank you. We'll let you know within a week.", "Merci. Nous vous recontacterons d'ici une semaine.", "Gracias. Le avisaremos en una semana."], ["j", "Vielen Dank für das Gespräch. Einen schönen Tag noch.", "Dank u wel voor het gesprek. Fijne dag nog.", "Thank you for the conversation. Have a nice day.", "Merci pour l'entretien. Bonne journée.", "Gracias por la entrevista. Que tenga un buen día."]], "v": {"1": [["Guten Tag, Frau Berg. Setzen Sie sich bitte.", "Goedendag, mevrouw Berg. Neemt u plaats, alstublieft.", "Good day, Ms Berg. Please have a seat.", "Bonjour madame Berg. Veuillez vous asseoir.", "Buenos días, señora Berg. Tome asiento, por favor."]], "12": [["Vielen Dank für das Gespräch. Auf Wiedersehen.", "Dank u wel voor het gesprek. Tot ziens.", "Thank you for the conversation. Goodbye.", "Merci pour l'entretien. Au revoir.", "Gracias por la entrevista. Hasta luego."]]}}, {"n": 34, "t": "Bij de kapper", "tt": {"de": "Beim Friseur", "nl": "Bij de kapper", "en": "At the hairdresser's", "fr": "Chez le coiffeur", "es": "En la peluquería"}, "r": [["j", "Hallo, ich habe um zwölf Uhr einen Termin.", "Hoi, ik heb om twaalf uur een afspraak.", "Hi, I have an appointment at twelve.", "Bonjour, j'ai rendez-vous à midi.", "Hola, tengo una cita a las doce."], ["a", "Hallo, willkommen! Was möchtest du heute machen lassen?", "Hoi, welkom! Wat wil je vandaag laten doen?", "Hi, welcome! What would you like done today?", "Salut, bienvenue ! Qu'est-ce que tu veux faire aujourd'hui ?", "¡Hola! ¿Qué quieres hacerte hoy?"], ["j", "Ich möchte meine Haare schneiden lassen, und der Pony etwas kürzer.", "Ik wil graag mijn haar knippen en een beetje kortere pony.", "I'd like a haircut and a slightly shorter fringe.", "Je voudrais une coupe et une frange un peu plus courte.", "Quiero un corte y el flequillo un poco más corto."], ["a", "Soll ich es an den Seiten etwas kürzer machen?", "Zal ik het aan de zijkant wat korter maken?", "Shall I make it a bit shorter at the sides?", "Je le raccourcis un peu sur les côtés ?", "¿Lo acorto un poco por los lados?"], ["j", "Ja, an den Seiten darf es etwas kürzer sein.", "Ja, aan de zijkant mag wat korter.", "Yes, the sides can be a bit shorter.", "Oui, les côtés peuvent être un peu plus courts.", "Sí, los lados pueden ser un poco más cortos."], ["a", "Möchtest du es auch föhnen lassen?", "Wil je het ook laten föhnen?", "Would you like it blow-dried too?", "Tu veux aussi un brushing ?", "¿Quieres también que te lo seque?"], ["j", "Ja gern, und mit ein bisschen Volumen.", "Ja graag, en wel met een beetje volume.", "Yes please, with a bit of volume.", "Oui, avec un peu de volume.", "Sí, por favor, con un poco de volumen."], ["a", "Was hältst du von dieser Farbe? Sie ist wärmer.", "Wat vind je van deze kleur? Die is warmer.", "What do you think of this colour? It's warmer.", "Que penses-tu de cette couleur ? Elle est plus chaude.", "¿Qué te parece este color? Es más cálido."], ["j", "Schön, aber nicht zu viel Unterschied, bitte.", "Mooi, maar niet te veel verschil, graag.", "Nice, but not too much difference, please.", "Joli, mais pas une trop grande différence.", "Bonito, pero sin demasiada diferencia, por favor."], ["a", "Dann mache ich eine helle Farbe über die Spitzen.", "Dan doe ik een lichte kleur over de punten.", "Then I'll put a light colour on the ends.", "Alors je mets une couleur claire sur les pointes.", "Entonces pongo un color claro en las puntas."], ["j", "Super, ich vertraue dir.", "Prima, ik vertrouw je.", "Great, I trust you.", "Parfait, je te fais confiance.", "Perfecto, confío en ti."], ["a", "Fertig. Schau mal in den Spiegel.", "Klaar. Kijk maar in de spiegel.", "All done. Have a look in the mirror.", "C'est fini. Regarde dans le miroir.", "Listo. Mira en el espejo."], ["j", "Wow, das sieht richtig gut aus. Danke dir!", "Wow, het ziet er echt goed uit. Dank je wel!", "Wow, it looks really good. Thanks!", "Waouh, ça a l'air vraiment bien. Merci !", "Uau, queda muy bien. ¡Gracias!"]], "v": {"1": [["Hallo, willkommen! Wobei kann ich dir helfen?", "Hoi, welkom! Waar kan ik je mee helpen?", "Hi, welcome! How can I help you?", "Salut, bienvenue ! Je peux t'aider ?", "¡Hola! ¿En qué te puedo ayudar?"]], "12": [["Das ist richtig schön geworden, danke dir!", "Wat mooi geworden, dank je wel!", "It turned out really nice, thanks!", "Ça a vraiment bien tourné, merci !", "Ha quedado muy bonito, ¡gracias!"]]}}, {"n": 35, "t": "Sportclub: lidmaatschap", "tt": {"de": "Sportverein: Mitgliedschaft", "nl": "Sportclub: lidmaatschap", "en": "Sports club: membership", "fr": "Club de sport : abonnement", "es": "Club deportivo: hacerse socio"}, "r": [["j", "Hallo, ich möchte mich gern für eine Mitgliedschaft anmelden.", "Hoi, ik wil me graag aanmelden voor een lidmaatschap.", "Hi, I'd like to sign up for a membership.", "Bonjour, je voudrais m'inscrire à un abonnement.", "Hola, quiero hacerme socio."], ["a", "Schön! Möchtest du jede Woche kommen?", "Leuk! Wil je elke week komen?", "Great! Do you want to come every week?", "Super ! Tu veux venir chaque semaine ?", "¡Genial! ¿Quieres venir cada semana?"], ["j", "Ich möchte dreimal pro Woche ins Studio.", "Ik wil drie keer per week naar de zaal.", "I want to go to the gym three times a week.", "Je veux aller à la salle trois fois par semaine.", "Quiero ir al gimnasio tres veces por semana."], ["a", "Dann ist das Abo mit freiem Zugang praktisch.", "Dan is het abonnement met vrije toegang handig.", "Then the subscription with free access is handy.", "Alors l'abonnement avec accès libre est pratique.", "Entonces el abono con acceso libre es práctico."], ["j", "Was kostet das pro Monat?", "Hoeveel kost dat per maand?", "How much is that per month?", "Combien ça coûte par mois ?", "¿Cuánto cuesta al mes?"], ["a", "Das sind neununddreißig Euro im Monat.", "Dat is negenendertig euro per maand.", "That's thirty-nine euros per month.", "Ça fait trente-neuf euros par mois.", "Son treinta y nueve euros al mes."], ["j", "Gibt es auch Kosten zum Start?", "Zijn er ook kosten om mee te beginnen?", "Are there also costs to start?", "Il y a aussi des frais au début ?", "¿Hay también gastos iniciales?"], ["a", "Ja, einmalig fünfzehn Euro für die Karte.", "Ja, eenmalig vijftien euro voor de pas.", "Yes, a one-time fee of fifteen euros for the card.", "Oui, des frais uniques de quinze euros pour la carte.", "Sí, una cuota única de quince euros por la tarjeta."], ["j", "Kann ich heute schon einmal probieren?", "Kan ik de eerste keer vandaag al proberen?", "Can I try it today already?", "Je peux essayer aujourd'hui déjà ?", "¿Puedo probarlo ya hoy?"], ["a", "Ja, das geht. Ich mache dir einen Probepass.", "Ja, dat kan. Ik maak een proefpas voor je.", "Yes, you can. I'll make a trial pass for you.", "Oui, c'est possible. Je te fais un pass d'essai.", "Sí, se puede. Te hago un pase de prueba."], ["j", "Super, danke. Wann kann ich den Pass abholen?", "Super, dank je wel. Wanneer kan ik de pas ophalen?", "Great, thanks. When can I pick up the pass?", "Super, merci. Quand puis-je récupérer le pass ?", "Genial, gracias. ¿Cuándo puedo recoger el pase?"], ["a", "Die kannst du jeden Tag nach achtzehn Uhr abholen.", "Die kun je elke dag na zes uur ophalen.", "You can pick it up every day after six.", "Tu peux le récupérer chaque jour après dix-huit heures.", "Puedes recogerlo cada día después de las seis."], ["j", "Super, bis später!", "Top, tot straks!", "Great, see you later!", "Super, à tout à l'heure !", "¡Genial, hasta luego!"]], "v": {"1": [["Schön! Wie oft möchtest du kommen?", "Leuk! Hoe vaak wil je komen?", "Nice! How often do you want to come?", "Super ! Tu veux venir combien de fois ?", "¡Genial! ¿Cuántas veces quieres venir?"]], "12": [["Toll, dann sehe ich dich nachher!", "Tof, dan zie ik je straks!", "Cool, then I'll see you later!", "Super, à plus tard alors !", "Perfecto, nos vemos luego."]]}}, {"n": 36, "t": "Ouderavond op school", "tt": {"de": "Elternabend in der Schule", "nl": "Ouderavond op school", "en": "Parents' evening at school", "fr": "Réunion parents-professeurs", "es": "Reunión de padres en el colegio"}, "r": [["j", "Guten Abend, ich bin Saras Mutter.", "Goedenavond, ik ben de moeder van Sara.", "Good evening, I'm Sara's mother.", "Bonsoir, je suis la mère de Sara.", "Buenas noches, soy la madre de Sara."], ["a", "Guten Abend, willkommen. Schön, dass Sie da sind.", "Goedenavond, welkom. Fijn dat u er bent.", "Good evening, welcome. Nice that you're here.", "Bonsoir, bienvenue. Ravi que vous soyez là.", "Buenas noches, bienvenida. Me alegra que esté aquí."], ["j", "Danke. Wie läuft es in der Schule mit Sara?", "Dank u wel. Hoe gaat het op school met Sara?", "Thank you. How is Sara doing at school?", "Merci. Comment se passe l'école pour Sara ?", "Gracias. ¿Cómo va Sara en el colegio?"], ["a", "Sara ist sehr nett und arbeitet gut im Unterricht mit.", "Sara is erg aardig en werkt goed mee in de klas.", "Sara is very friendly and participates well in class.", "Sara est très gentille et participe bien en classe.", "Sara es muy simpática y participa bien en clase."], ["j", "Das freut mich. Und wie läuft es beim Rechnen?", "Dat is fijn om te horen. Met rekenen gaat het goed?", "That's good to hear. How is maths going?", "Ça me fait plaisir. Et les maths, ça va ?", "Me alegra oírlo. ¿Y las mates, cómo van?"], ["a", "Rechnen läuft gut, aber das Lesen darf etwas schneller werden.", "Rekenen gaat goed, maar lezen mag wat sneller.", "Maths is going well, but reading could be a bit faster.", "Les maths vont bien, mais la lecture peut être plus rapide.", "Las mates van bien, pero la lectura podría ser más rápida."], ["j", "Was können wir zu Hause tun, um das Lesen zu unterstützen?", "Wat kunnen wij thuis doen om het lezen te helpen?", "What can we do at home to help with reading?", "Que pouvons-nous faire à la maison pour aider la lecture ?", "¿Qué podemos hacer en casa para ayudar con la lectura?"], ["a", "Jeden Abend zehn Minuten vorlesen, das hilft schon sehr.", "Elke avond tien minuten voorlezen, dat helpt al veel.", "Ten minutes of reading aloud every evening already helps a lot.", "Dix minutes de lecture chaque soir, ça aide déjà beaucoup.", "Diez minutos de lectura en voz alta cada noche ya ayudan mucho."], ["j", "Das machen wir. Dürfen wir auch die Schulbücher mitnehmen?", "Dat doen we. Mogen we ook de boeken van school meenemen?", "We will. May we also take the school books home?", "Nous le ferons. Peut-on aussi emporter les livres de l'école ?", "Lo haremos. ¿Podemos también llevarnos los libros del colegio?"], ["a", "Ja, die können Sie nach dem Unterricht mit nach Hause nehmen.", "Ja, die kunt u na de les mee naar huis nemen.", "Yes, you can take them home after the lesson.", "Oui, vous pouvez les emporter après le cours.", "Sí, puede llevárselos a casa después de la clase."], ["j", "Gut, danke. Wann ist das nächste Gespräch?", "Fijn, dank u. Wanneer is het volgende gesprek?", "Good, thank you. When is the next meeting?", "Très bien, merci. Quand est le prochain entretien ?", "Muy bien, gracias. ¿Cuándo es la próxima reunión?"], ["a", "Das ist in drei Wochen, ich schicke Ihnen eine Einladung.", "Dat is over drie weken, ik stuur u een uitnodiging.", "That's in three weeks, I'll send you an invitation.", "C'est dans trois semaines, je vous enverrai une invitation.", "Es dentro de tres semanas, le enviaré una invitación."], ["j", "Gut, bis dann. Einen schönen Abend noch.", "Prima, tot dan. Fijne avond nog.", "Fine, see you then. Have a nice evening.", "Très bien, à bientôt. Bonne soirée.", "Perfecto, hasta entonces. Que tenga buena tarde."]], "v": {"1": [["Guten Abend, schön, dass Sie da sind.", "Goedenavond, fijn dat u er bent.", "Good evening, nice that you could come.", "Bonsoir, ravi que vous soyez là.", "Buenas noches, me alegra que haya venido."]], "12": [["Gut, dann bis dann. Schönen Abend.", "Prima, dan tot dan. Fijne avond.", "Fine, then see you then. Have a nice evening.", "Parfait, à bientôt. Bonne soirée.", "Perfecto, hasta entonces. Buenas noches."]]}}];
